/* DAWAH X — ahmad, অধ্যায় 95 · খণ্ড 95 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][95]=[[18801,18801,"","আমরা আমার জন্য কাপুরুষ হওয়ার ব্যাপারে খুশি হয়েছি। নৈতিকভাবে বলতে চাই, আমরা ঈশ্বরকে এটা করতে শিখেছি। তাকে আমাদের প্রার্থনা করতে হবে এবং তাকে হত্যা করতে হবে। যদি তারা বড় হয়, তাহলে আমরা বড় হব। এবং বলা হয়েছে \"যা যেতে হবে,\" তারা বলে \"যা গেছে\" সে উঠে গেছে এবং বলেছে, যারা আপনার জন্য ক্ষমা প্রার্থনা করেছে তাদের জন্য তিনি ঈশ্বরের কাছে অনুরোধ করেছেন। তারা বলবে, আল্লাহ তা করার আগে তারা বলবে। আর তা করবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَن ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏عَلَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَنَا وَسُنَّتَنَا فَقَالَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا قَالَ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ يُجِبْكُمْ اللَّهُ تَعَالَى وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا رَفَعَ فَارْفَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ يَسْمَعْ اللَّهُ لَكُمْ وَإِذَا سَجَدَ فَاسْجُدُوا وَإِذَا رَفَعَ فَارْفَعُوا فَإِنَّ الْإِمَامَ يَسْجُدُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِلْكَ بِتِلْكَ ‏","","",""],[18802,18802,"","ঈশ্বর হয়তো এমন কাউকে দেখেছেন, যাকে আমি ভালোবাসি আর তা করতেও পারি । আমার বাবা মারা যাওয়ার পর তিনি খুব ক্লান্ত হয়ে পড়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَن ‏ ‏الْأَعْمَشِ ‏ ‏عَن ‏ ‏شَقِيقٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ رَجُلًا أَحَبَّ قَوْمًا وَلَمَّا يَلْحَقْ بِهِمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَكَذَا ‏ ‏حَدَّثَنَاهُ ‏ ‏وَكِيعٌ ‏ ‏عَن ‏ ‏سُفْيَانَ ‏ ‏عَن ‏ ‏الْأَعْمَشِ ‏ ‏عَن ‏ ‏شَقِيقٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏أَيْضًا ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏","","",""],[18803,18803,"","আমরা আবেগ নিয়ে কথা বলেছি যা বাবার ভালবাসার অনুভূতি নিয়ে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏سُلَيْمَانَ ‏ ‏عَن ‏ ‏أَبِي وَائِلٍ ‏ ‏عَن ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏","","",""],[18804,18804,"","আমরা বাবার মশার জন্য জীবন সংগ্রাম সম্পর্কে কথা বলেছিলাম, ঈশ্বর বলেছিলেন, এটা তোমার মন থেকে হয়েছে। আর এটা শুধু যাওয়ার জন্যই। বিজ্ঞান আর আরো বিখ্যাত হওয়ার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَن ‏ ‏الْأَعْمَشِ ‏ ‏عَن ‏ ‏شَقِيقٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ وَرَائِكُمْ أَيَّامًا يَنْزِلُ فِيهَا الْجَهْلُ وَيُرْفَعُ فِيهَا الْعِلْمُ وَيَكْثُرُ فِيهَا ‏ ‏الْهَرْجُ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ ‏","","",""],[18805,18805,"","আমরা আমার বাবার সাথে কথা বলেছি যে আমরা ঈশ্বরের ইচ্ছা জানতে পেরেছি। মানুষ আবেগী লড়াই করছে আর লর্ডের সাথে যুদ্ধ করছে... ঈশ্বরের বাক্য থেকে হত্যা করা হলো ঈশ্বরের বিয়ের পথে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَن ‏ ‏شَقِيقٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ يُقَاتِلُ شَجَاعَةً وَيُقَاتِلُ ‏ ‏حَمِيَّةً ‏ ‏وَيَقْتُلُ ‏ ‏رِيَاءً ‏ ‏فَأَيُّ ذَلِكَ فِي سَبِيلِ اللَّهِ تَعَالَى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18806,18806,"","আমি আমার বাবাকে এক বছর আগে আমার বাবাকে করতে চেষ্টা করার বিষয়ে কথা বলেছিলাম । ভাবতে হবে না, সে রাতে তার লাথি মেরে তাকে বিভ্রান্ত করার আগের দিন পর্যন্ত লাথি মেরে ফেলবে। তার মুখ তার গলা থেকে গুলি করা হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَن ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَن ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخَمْسِ كَلِمَاتٍ فَقَالَ ‏ ‏إِنَّ اللَّهَ تَعَالَى لَا يَنَامُ وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ وَلَكِنَّهُ يَخْفِضُ ‏ ‏الْقِسْطَ ‏ ‏وَيَرْفَعُهُ يُرْفَعُ إِلَيْهِ عَمَلُ اللَّيْلِ قَبْلَ عَمَلِ النَّهَارِ وَعَمَلُ النَّهَارِ قَبْلَ عَمَلِ اللَّيْلِ حِجَابُهُ النُّورُ لَوْ كَشَفَهُ لَأَحْرَقَتْ ‏ ‏سُبُحَاتُ ‏ ‏وَجْهِهِ مَا انْتَهَى إِلَيْهِ بَصَرُهُ مِنْ خَلْقِهِ ‏","","",""],[18807,18807,"","তিনি বলেছিলেন যে, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি তাঁর কাছে প্রতিজ্ঞা করেছেন । সে তাদের থেকে মুক্তি দিচ্ছে না আর তাদের টাকা দিচ্ছে আর তাদের থেকে দূরে সরিয়ে দিচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَن ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَحَدَ أَصْبَرُ عَلَى أَذًى يَسْمَعُهُ مِنْ اللَّهِ عَزَّ وَجَلَّ إِنَّهُ يُشْرَكُ بِهِ وَيُجْعَلُ لَهُ وَلَدٌ وَهُوَ ‏ ‏يُعَافِيهِمْ وَيَدْفَعُ عَنْهُمْ وَيَرْزُقُهُمْ ‏","","",""],[18808,18808,"","সেই সময়, আমি আমার বাবা ও মা দুজনেই যিহোবার সাক্ষিদের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করেছিলাম । যে তার আচরণ ভালো করেছে, তারপর আমি তাকে ভালোবাসি আর আমি তাকে বিয়ে করব এবং তার উপাসনা করব।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرُ بْنُ رَاشِدٍ ‏ ‏عَن ‏ ‏فِرَاسٍ ‏ ‏عَن ‏ ‏الشَّعْبِيِّ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةٌ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ رَجُلٌ آمَنَ بِالْكِتَابِ الْأَوَّلِ وَالْكِتَابِ الْآخِرِ وَرَجُلٌ لَهُ أَمَةٌ فَأَدَّبَهَا فَأَحْسَنَ تَأْدِيبَهَا ثُمَّ أَعْتَقَهَا وَتَزَوَّجَهَا وَعَبْدٌ مَمْلُوكٌ أَحْسَنَ عِبَادَةَ رَبِّهِ وَنَصَحَ لِسَيِّدِهِ ‏ ‏أَوْ كَمَا قَالَ ‏","","",""],[18809,18809,"","আমরা একটা ছেলেকে মুছে ফেলার চেষ্টা করেছি, যে আমার বাবার কাছে ভালোর জন্য ছিল. আমার নৈতিক ইচ্ছা ছিল আমি ঈশ্বরের কাছে প্রার্থনা করেছি তার সাহায্য চাইতে, আমরা ঈশ্বরের কাছে শপথ করছি, যে কিনা তা দেখতে না। খোলা।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَن ‏ ‏بُرَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَاسٍ مِنْ قَوْمِي بَعْدَ مَا فَتَحَ ‏ ‏خَيْبَرَ ‏ ‏بِثَلَاثٍ ‏ ‏فَأَسْهَمَ ‏ ‏لَنَا وَلَمْ يَقْسِمْ لِأَحَدٍ لَمْ يَشْهَدْ الْفَتْحَ غَيْرِنَا ‏","","",""],[18810,18810,"","আমরা তাকে নাবিলে রাখার চেয়ে বরং তার চেয়েও ভালো কিছু নিয়ে কথা বলেছি। আমরা দ্রুত ফিরে যাই এবং আমার বাবাকে খুন না করার জন্য বেঁচে থাকি। কারণ সে বলছে আমি যাব না। আমি তার কাছে ঋণী। আমি তাকে ছেড়ে দেব। আমি তাকে অবশ্যই ভুলে যাব। আমি বলেছিলাম, আমি আমার কাছে ঋণী। আমি তাকে হত্যা করতে চাই। আমি আমার কাছে এটা একটা বিষয় ছিল না। আমি আমার কাছে এটা একটা ছোট দল। আমি মনে করি, আমি আমার বাবার সাথে কাজ করি। আমি আমার বাবার সাথে নেই। আমি আমার বাবার সাথে কথা বলেছি, আমি আমার বাবার সাথে নেই। আমি মনে করি, আমি তাকে খুন করতে হবে যে, আমি আমার বাবার মত। আমি আমার বাবার সাথে যোগাযোগ করি। আমি যদি আমার বাবা-মাটকে খুন করি, আমি আমার জীবনের জন্য। আমি আমার জীবনের জন্য একটা বিষয় নিয়ে কথা বলি, তাহলে আমি তাকে খুন করতে হবে না। আমি আমার বাবা-মাটমাটকে খুন করতে হবে। আমি আমার কাছে ফিরে যেতে হবে। তার একটা গাছ থেকে সে তাকে নিয়ে গেল... ...আর তারপর আমি তোমার সাথে কথা বলিনি. আর আমরা বলবো যে ঈশ্বর হচ্ছেন প্রভু, লর্ড। গুজব রয়েছে যে খুন তোমাকে মেরে ফেলবে, কেউ কেউ তাদের প্রতিবেশীকে হত্যা করবে এবং তাদের ভাইকে হত্যা করবে, এটা প্রশ্ন নয় যে সেখানে কি আছে আমার সাথে কোন সমস্যা আছে, তুমি আমাকে শিক্ষা দাও এবং তোমাকে বাইরে যেতে হবে এবং আমি দেখতে চাই যে আমরা তাকে এখান থেকে বের করে নিয়ে যাচ্ছি, আমরা তাকে যখন পেয়েছি, আমরা মাঝে মাঝে তার সাথে এমন কিছু ঘটে নি। শোনা, গ্রিম বলেছে, আমার বাবা বলেছেন যে, তিনি মারা গেছেন বলে আমি দুঃখিত। সে বলেছিল যে বাবার বাবার মূসা সামনে এসে... ...আর সে মনে করে যেন তার এক্সিডেন্ট হয়েছে, আমরা আমার বাবার জন্য একটা কুত্তাকে রক্ষা করার চেষ্টা করেছি অপরাধীর মৃত্যুর জন্য দায়ী কুকুর বলেছিল আমরা ডিপার্টমেন্টের সাথে কথা বলতে চাই... ...আমার বাবা তার সবচেয়ে ভাল মুরগির মতো ছিলেন. অনুষ্ঠান।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَن ‏ ‏يُونُسَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏أَسِيدَ بْنَ الْمُتَشَمِّسِ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ ‏ ‏أَبِي مُوسَى ‏ ‏مِنْ ‏ ‏أَصْبَهَانَ ‏ ‏فَتَعَجَّلْنَا وَجَاءَتْ ‏ ‏عُقَيْلَةُ ‏ ‏فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏أَلَا فَتًى يُنْزِلُ ‏ ‏كَنَّتَهُ ‏ ‏قَالَ ‏ ‏يَعْنِي أَمَةٌ ‏ ‏الْأَشْعَرِيَّ ‏ ‏فَقُلْتُ بَلَى ‏ ‏فَأَدْنَيْتُهَا ‏ ‏مِنْ شَجَرَةٍ فَأَنْزَلْتُهَا ثُمَّ جِئْتُ فَقَعَدْتُ مَعَ الْقَوْمِ فَقَالَ أَلَا أُحَدِّثُكُمْ حَدِيثًا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُنَاهُ فَقُلْنَا بَلَى يَرْحَمُكَ اللَّهُ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُنَا أَنَّ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ ‏ ‏الْهَرْجَ ‏ ‏قِيلَ وَمَا الْهَرْجُ قَالَ الْكَذِبُ وَالْقَتْلُ قَالُوا أَكْثَرُ مِمَّا نَقْتُلُ الْآنَ قَالَ إِنَّهُ لَيْسَ بِقَتْلِكُمْ الْكُفَّارَ وَلَكِنَّهُ قَتْلُ بَعْضِكُمْ بَعْضًا حَتَّى يَقْتُلَ الرَّجُلُ جَارَهُ وَيَقْتُلَ أَخَاهُ وَيَقْتُلَ عَمَّهُ وَيَقْتُلَ ابْنَ عَمِّهِ قَالُوا سُبْحَانَ اللَّهِ وَمَعَنَا عُقُولُنَا قَالَ لَا إِلَّا أَنَّهُ يَنْزِعُ عُقُولَ أَهْلِ ذَاكَ الزَّمَانِ حَتَّى يَحْسَبَ أَحَدُكُمْ أَنَّهُ عَلَى شَيْءٍ وَلَيْسَ عَلَى شَيْءٍ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَقَدْ خَشِيتُ أَنْ تُدْرِكَنِي وَإِيَّاكُمْ تِلْكَ الْأُمُورُ وَمَا أَجِدُ لِي وَلَكُمْ مِنْهَا مَخْرَجًا فِيمَا عَهِدَ إِلَيْنَا نَبِيُّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا أَنْ نَخْرُجَ مِنْهَا كَمَا دَخَلْنَاهَا لَمْ نُحْدِثْ فِيهَا شَيْئًا ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَن ‏ ‏الْقَاسِمِ التَّمِيمِيِّ ‏ ‏عَن ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏أَبِي مُوسَى ‏ ‏فَقَدَّمَ طَعَامَهُ فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏زَهْدَمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏أَيُّوبَ ‏ ‏عَن ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَن ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏وَحَدَّثَنِيهِ ‏ ‏الْقَاسِمُ الْكَلْبِيُّ ‏ ‏عَن ‏ ‏زَهْدَمٍ ‏ ‏قَالَ فَأَنَا لِحَدِيثِ ‏ ‏الْقَاسِمِ ‏ ‏أَحْفَظُ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏أَبِي مُوسَى ‏ ‏فَقَدَّمَ طَعَامَهُ فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏زَهْدَمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏أَيُّوبَ ‏ ‏عَن ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَن ‏ ‏زَهْدَمٍ الْجَرْمِيِّ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏وَحَدَّثَنِيهِ ‏ ‏الْقَاسِمُ الْكَلْبِيُّ ‏ ‏عَن ‏ ‏زَهْدَمٍ ‏ ‏قَالَ فَأَنَا لِحَدِيثِ ‏ ‏الْقَاسِمِ ‏ ‏أَحْفَظُ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏أَبِي مُوسَى ‏ ‏فَدَعَا بِمَائِدَتِهِ فَجِيءَ بِهَا وَعَلَيْهَا لَحْمُ دَجَاجٍ فَذَكَرَ الْحَدِيثَ ‏","","",""],[18811,18811,"","আমরা আমার বাবার সঙ্গে কথা বলেছিলাম যে তিনি চলে যাচ্ছেন । তোমাকে আত্মসমর্পণ করলাম।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَرَّتْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِنَازَةٌ ‏ ‏تُمْخَضُ ‏ ‏مَخْضَ ‏ ‏الزِّقِّ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ ‏ ‏الْقَصْدَ ‏","","",""],[18812,18812,"","আমরা আমার বাবার কথা বলেছি, আমার কল্পনার মানুষ, আর তিনি বলেছিলেন, \"ঈশ্বর, আল্লাহ্‌, আমার বাবা, ঈশ্বর, এই অভিশাপকে উৎসর্গ করেছেন এবং ক্ষুধার্থকে ফিরে পেতে সাহায্য করেছেন।\"","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَن ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَن ‏ ‏أَبِي وَائِلٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فُكُّوا الْعَانِيَ وَأَطْعِمُوا الْجَائِعَ وَعُودُوا الْمَرِيضَ ‏","","",""],[18813,18813,"","আমরা এক সুখী ছেলের কথা বলেছি যে আমার ভালবাসার জন্য কথা বলেছে, সে আমার বাবার সাথে কথা বলেছে আর তার কথোপকথন আমার কথা বলছে যে সে আমাকে সাহায্য করার চেষ্টা করছে। তারা এটাকে সহজ এবং সহজেই নিয়ে যায় ও আপনাকে ধোঁকা দেয় ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏حَدَّثَنَا ‏ ‏قَسَامَةُ بْنُ زُهَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَن ‏ ‏قَسَامَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَشْعَرِيَّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ ‏ ‏آدَمَ ‏ ‏مِنْ قَبْضَةٍ قَبَضَهَا مِنْ جَمِيعِ الْأَرْضِ فَجَاءَ بَنُو ‏ ‏آدَمَ ‏ ‏عَلَى قَدْرِ الْأَرْضِ جَعَلَ مِنْهُمْ الْأَحْمَرَ وَالْأَبْيَضَ وَالْأَسْوَدَ وَبَيْنَ ذَلِكَ وَالسَّهْلَ ‏ ‏وَالْحَزْنَ ‏ ‏وَبَيْنَ ذَلِكَ وَالْخَبِيثَ وَالطَّيِّبَ وَبَيْنَ ذَلِكَ ‏","","",""],[18814,18814,"","আমরা এক কিশোরের সুখী সন্তান নিয়ে কথা বলেছি, যে আমার বাবার এই প্রতারণার কথা বলেছে। তিনি বললেন, তিনি শহরকে ভেঙ্গে দিয়েছেন, তাই তার ভালো বাবা আছে। একজন মানুষ বলবে যে তার আছে আর সে খুব বিকৃত হবে. আমি তার জন্য খুলেছি আর আমাকে বলা হয়েছে যে ঈশ্বর হেরে গেছেন. মোসে, আমি ঈশ্বরের অনুগ্রহে এসেছি, ঈশ্বরের কাছে প্রার্থনা করেছি, আর আমি স্বপ্ন দেখছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَن ‏ ‏عُثْمَانَ بْنِ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّهُ ‏ ‏كَانَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏وَبِيَدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُودٌ يَضْرِبُ بِهِ بَيْنَ الْمَاءِ وَالطِّينِ فَجَاءَ رَجُلٌ يَسْتَفْتِحُ فَقَالَ ‏ ‏افْتَحْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ فَإِذَا هُوَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ فَفَتَحْتُ لَهُ وَبَشَّرْتُهُ بِالْجَنَّةِ ثُمَّ جَاءَ رَجُلٌ يَسْتَفْتِحُ فَقَالَ افْتَحْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ فَإِذَا هُوَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَفَتَحْتُ لَهُ وَبَشَّرْتُهُ بِالْجَنَّةِ ثُمَّ جَاءَ رَجُلٌ فَاسْتَفْتَحَ فَقَالَ افْتَحْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ عَلَى بَلْوَى تُصِيبُهُ ‏ ‏أَوْ بَلْوَى تَكُونُ ‏ ‏قَالَ فَإِذَا هُوَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَفَتَحْتُ لَهُ وَبَشَّرْتُهُ بِالْجَنَّةِ وَأَخْبَرْتُهُ فَقَالَ اللَّهُ الْمُسْتَعَانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ يَعْنِي ابْنَ غِيَاثٍ ‏ ‏عَن ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏مِنْ ‏ ‏حِيطَانِ ‏ ‏الْمَدِينَةِ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏يَحْيَى ‏ ‏إِلَّا أَنَّهُ قَالَ فِي قَوْلِ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏اللَّهُ الْمُسْتَعَانُ اللَّهُمَّ صَبْرًا وَعَلَى اللَّهِ ‏ ‏التُّكْلَانُ ‏","","",""],[18815,18815,"","আমরা আমার বাবাকে আমার মাংস থেকে বের করে দিয়ে সাহায্য করার কথা বলেছিলাম। আল্লাহ আছে আর বলবে আমি মিষ্টি আর আমার মা আর মনের কথা ভুলে যাই।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَن ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُحِلَّ لُبْسُ الْحَرِيرِ وَالذَّهَبِ لِنِسَاءِ أُمَّتِي وَحُرِّمَ عَلَى ذُكُورِهَا ‏","","",""],[18816,18816,"","আমরা একজন যুবতীর কথা বলেছি যে আমার বাবার সাথে কথা বলেছে সে সব জ্যান চোখ দিয়ে দিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ يَعْنِي ابْنَ عُمَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏غُنَيْمُ بْنُ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ عَيْنٍ زَانِيَةٌ ‏","","",""],[18817,18817,"","আমরা বেশ কয়েকবার আমার বাবাকে বিচার করার চেষ্টা করেছি। ঈশ্বর তা উদ্ধার করতে পারবেন না। আর আমি বিয়ে বা পান করতে পারবো না। আর কবি, আর কবি। তুমি তাদের মধ্যে আমাকে হুকুম দাও যে তুমি সবাই মাতাল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ ‏ ‏حَدَّثَنَا ‏ ‏سَيَّارٌ أَبُو الْحَكَمِ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏شَرَابَيْنِ ‏ ‏أَوْ أَشْرِبَةً ‏ ‏هَذَا ‏ ‏الْبِتْعُ ‏ ‏مِنْ الْعَسَلِ ‏ ‏وَالْمِزْرُ ‏ ‏مِنْ الذُّرَةِ وَالشَّعِيرِ فَمَا تَأْمُرُنِي فِيهِمَا قَالَ ‏ ‏أَنْهَاكُمْ عَنْ كُلِّ مُسْكِرٍ ‏","","",""],[18818,18818,"","আমরা বাবার কাছ থেকে বাবার কাছ থেকে জানতে চেয়েছিলাম যে, তিনি হারলে ক্ষমতা নিতে পারবেন । ভগবানের কাছে ভগবানের কাছে ভগবানের কাছে ভগবানের কাছে, তুমি আমাকে একটা চোখ বা ভগবানের নকশা করতে দাওনা, আর তারপর বল বাবা মোস বা ভগবান হয়তো কিছু করেছে। অন্ত্যেষ্টিক্রিয়ার সম্পদ বলে আমি ক্ষমতাহীনভাবে বলিনি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَن ‏ ‏التَّيْمِيِّ ‏ ‏عَن ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَخَذَ الْقَوْمُ فِي ‏ ‏عُقْبَةٍ ‏ ‏أَوْ ‏ ‏ثَنِيَّةٍ ‏ ‏فَكُلَّمَا عَلَا رَجُلٌ عَلَيْهَا نَادَى لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَغْلَةٍ يَعْرِضُهَا فِي الْخَيْلِ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّكُمْ لَا تَدْعُونَ أَصَمَّ وَلَا غَائِبًا ثُمَّ قَالَ يَا ‏ ‏أَبَا مُوسَى ‏ ‏أَوْ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏أَلَا أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ قَالَ قُلْتُ بَلَى قَالَ لَا ‏ ‏حَوْلَ ‏ ‏وَلَا قُوَّةَ إِلَّا بِاللَّهِ ‏","","",""],[18819,18819,"","আমরা তাদের কথা বলছি মাংসের বুকে আবার আঘাত করার সাথে সাথে সাথে তাদের নিয়ে। আমি তোমার যা হওয়ার জন্য অপেক্ষা করছি, ঈশ্বরের সাথে ঝামেলা না করে।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْجُعَيْدُ ‏ ‏عَن ‏ ‏يَزِيدَ بْنِ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ بَشِيرٍ ‏ ‏عَن ‏ ‏الْمُحَرَّرِ ‏ ‏عَن ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُقَلِّبُ كَعَبَاتِهَا أَحَدٌ يَنْتَظِرُ مَا تَأْتِي بِهِ إِلَّا عَصَى اللَّهَ وَرَسُولَهُ ‏","","",""],[18820,18820,"","আমার বাবা বলেছিলেন যে, ঈশ্বর আমার সত্য প্রকাশ করার জন্য প্রার্থনা করছেন ।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَن ‏ ‏مُصْعَبِ بْنِ ثَابِتٍ ‏ ‏عَن ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُؤْمِنٍ يَوْمَ الْقِيَامَةِ إِلَّا يَأْتِي بِيَهُودِيٍّ أَوْ نَصْرَانِيٍّ يَقُولُ هَذَا فِدَائِي مِنْ النَّارِ ‏","","",""],[18821,18821,"","আমরা বাবার কাছ থেকে ক্লান্ত হয়ে পড়েছিলাম । আর যুদ্ধ হল ভবিষ্যদ্বাণী আর পরিত্রাণ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَا أَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَن ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَن ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏سَمَّى لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفْسَهُ أَسْمَاءً مِنْهَا مَا حَفِظْنَا قَالَ ‏ ‏أَنَا ‏ ‏مُحَمَّدٌ ‏ ‏وَأَحْمَدُ ‏ ‏والْمُقَفِّي ‏ ‏وَالْحَاشِرُ ‏ ‏وَنَبِيُّ التَّوْبَةِ والْمَلْحَمَةِ ‏","","",""],[18822,18822,"","আমরা আমার বাবার উপর গুলি করা হয়েছে বলে কথা বলেছি এবং বললাম \"আমি মুসাকে ভালবাসি\"। তিনি আমাদের দেখেছেন যে তিনি আমাদের ঈশ্বরের বার্তাবাহকের কাছে প্রার্থনা করেছেন এবং আমরা আলো তৈরি করেছি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏يَا بُنَيَّ ‏ ‏كَيْفَ لَوْ رَأَيْتَنَا وَنَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرِيحُنَا رِيحُ الضَّأْنِ ‏","","",""],[18823,18823,"","আমরা বাবার সাথে ঈশ্বরের কথা বলেছিলাম, আমরা আমার উদ্যোগ নিয়ে কাজ করছি। ঈশ্বর ঈশ্বর তাকে একটা মই হিসেবে সেবা করেছেন । সে তাকে মেরে ফেলবে, সে অনুগত থাকবে, সে করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ حَدَّثَ ‏ ‏أَبُو الزِّنَادِ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ نَافِعٍ بْنِ عَبْدِ الْحَارِثِ الْخُزَاعِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي ‏ ‏حَائِطٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَلَى ‏ ‏قُفِّ ‏ ‏الْبِئْرِ مُدَلِّيًا رِجْلَيْهِ فَدَقَّ الْبَابَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْذَنْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ فَفَعَلَ فَدَخَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَدَلَّى رِجْلَيْهِ ثُمَّ دَقَّ الْبَابَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْذَنْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ فَفَعَلَ ثُمَّ دَقَّ الْبَابَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْذَنْ لَهُ وَبَشِّرْهُ بِالْجَنَّةِ ‏ ‏وَسَيَلْقَى بَلَاءً فَفَعَلَ ‏","","",""],[18824,18824,"","আমি আগের চেয়ে অনেক ভালো কথা বলেছি, আমার বাবা বলেছেন, ঈশ্বর তাঁর বধিরদের সাথে শান্তি স্থাপন করেছেন। এর মূল্য শুধু সব পাওয়ার কথা বলা হবে। আমরা যদি চাইতাম তবে আমরা নিশ ্ চয়ই তোমাকে বিন ্ যস ্ ত করতাম , কিন ্ তু আমাদের প ্ রতি এবং যার জন ্ য আমরা ইচ ্ ছা করলাম । আর আমরা বলে দেব যে , এটি হবে এক সম ্ প ্ রদায় । এত ভুল করে বলতে পারি সে আপনার ছেলে নয়, তারা আমাকে একটা হাত দিয়েছে অথবা আমরা দু'জন চেষ্টা করেছি যে আমাদের সন্তান আছে। হাঙ্গর বলেছিল যে আমরা একটা ছেলেকে হারিয়েছি যে আমরা একটা ছেলেকে হারিয়েছি যে তার ভিতর দিয়ে গেছে। আমার বাবা তার জীবন হারিয়েছে, আমি তার কাছে ক্ষমা চেয়েছিলাম, বড়দের যা করতে চাও বলে আমি দুঃখিত। ঈশ্বরের বার্তাবাহক তাকে উদ্ধার করেছেন এবং তাকে উদ্ধার করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَن ‏ ‏عُمَارَةَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْمَعُ اللَّهُ عَزَّ وَجَلَّ الْأُمَمَ فِي ‏ ‏صَعِيدٍ ‏ ‏يَوْمَ الْقِيَامَةِ فَإِذَا بَدَا لِلَّهِ عَزَّ وَجَلَّ أَنْ يَصْدَعَ بَيْنَ خَلْقِهِ مَثَّلَ لِكُلِّ قَوْمٍ مَا كَانُوا يَعْبُدُونَ فَيَتْبَعُونَهُمْ حَتَّى يُقْحِمُونَهُمْ النَّارَ ثُمَّ يَأْتِينَا رَبُّنَا عَزَّ وَجَلَّ وَنَحْنُ عَلَى مَكَانٍ رَفِيعٍ فَيَقُولُ ‏ ‏مَنْ أَنْتُمْ فَنَقُولُ نَحْنُ الْمُسْلِمُونَ فَيَقُولُ مَا تَنْتَظِرُونَ فَيَقُولُونَ نَنْتَظِرُ رَبَّنَا عَزَّ وَجَلَّ قَالَ فَيَقُولُ وَهَلْ تَعْرِفُونَهُ إِنْ رَأَيْتُمُوهُ فَيَقُولُونَ نَعَمْ فَيَقُولُ كَيْفَ تَعْرِفُونَهُ وَلَمْ تَرَوْهُ فَيَقُولُونَ نَعَمْ إِنَّهُ لَا ‏ ‏عِدْلَ ‏ ‏لَهُ ‏ ‏فَيَتَجَلَّى لَنَا ضَاحِكًا فَيَقُولُ أَبْشِرُوا أَيُّهَا الْمُسْلِمُونَ ‏ ‏فَإِنَّهُ لَيْسَ مِنْكُمْ أَحَدٌ إِلَّا جَعَلْتُ مَكَانَهُ فِي النَّارِ يَهُودِيًّا أَوْ نَصْرَانِيًّا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَن ‏ ‏عُمَارَةَ الْقُرَشِيِّ ‏ ‏قَالَ ‏ ‏وَفَدْنَا إِلَى ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏وَفِينَا ‏ ‏أَبُو بُرْدَةَ ‏ ‏فَقَضَى حَاجَتَنَا فَلَمَّا خَرَجَ ‏ ‏أَبُو بُرْدَةَ ‏ ‏رَجَعَ فَقَالَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏أَذْكُرُ الشَّيْخَ مَا رَدَّكَ أَلَمْ أَقْضِ حَوَائِجَكَ قَالَ فَقَالَ ‏ ‏أَبُو بُرْدَةَ ‏ ‏إِلَّا حَدِيثًا حَدَّثَنِيهِ ‏ ‏أَبِي ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَجْمَعُ اللَّهُ عَزَّ وَجَلَّ الْأُمَمَ يَوْمَ الْقِيَامَةِ فَذَكَرَ الْحَدِيثَ قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِأَبِي بُرْدَةَ ‏ ‏آللَّهِ لَسَمِعْتَ ‏ ‏أَبَا مُوسَى ‏ ‏يُحَدِّثُ بِهِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ لَأَنَا سَمِعْتُهُ مِنْ أَبِي يُحَدِّثُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18825,18825,"","আমরা একটা জীবন সম্পর্কে কথা বলেছিলাম, আমি বাবাকে জীবন-মৃত্যুর পরে ভালো কথা বলেছি। আমার বাবা বলেছেন, লর্ড মুসা তাকে ভালো করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَن ‏ ‏أَبِي حَصِينٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَعْتَقَ الرَّجُلُ أَمَتَهُ ثُمَّ تَزَوَّجَهَا بِمَهْرٍ جَدِيدٍ كَانَ لَهُ أَجْرَانِ ‏","","",""],[18826,18826,"","আমরা আমার বাবা তার বাবার কাছ থেকে দূরে খনন করা কথা বলেছিলাম, তার শ্বাসে এতিমটি হয়তো পাপ করেছে এবং বিয়েও করবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَن ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏رَفَعَهُ قَالَ ‏ ‏تُسْتَأْمَرُ الْيَتِيمَةُ فِي نَفْسِهَا فَإِنْ سَكَتَتْ فَقَدْ أَذِنَتْ وَإِنْ أَبَتْ فَلَا تُزَوَّجْ ‏","","",""],[18827,18827,"","আমরা একটি অতীতের কথা বলেছি, কিন্তু আমরা একটি চমৎকার বাবা কথা বলেছি, যে কিনা অতীতে সুখী বাবা। আমার বাবা বলেছেন, তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন, তিনি তার পাপ ক্ষমা প্রার্থনা করেছেন। যদি তার ছেলে হয়, তবে তার পাপ হবে। তাদের সবাইকে যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبِيعٌ يَعْنِي أَبَا سَعِيدٍ النَّصْرِيَّ ‏ ‏عَن ‏ ‏مُعَاوِيَةَ بْنِ إِسْحَاقَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏أَبُو بُرْدَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذِهِ الْأُمَّةَ مَرْحُومَةٌ جَعَلَ اللَّهُ عَزَّ وَجَلَّ عَذَابَهَا بَيْنَهَا فَإِذَا كَانَ يَوْمُ الْقِيَامَةِ دُفِعَ إِلَى كُلِّ امْرِئٍ مِنْهُمْ رَجُلٌ مِنْ أَهْلِ الْأَدْيَانِ فَقَالَ هَذَا يَكُونُ فِدَاءَكَ مِنْ النَّارِ ‏","","",""],[18828,18828,"","আমরা আমাদের বাবার মৃত্যু আমরা যখন পেয়েছি, তখন থেকে আমরা আমাদের বাবার মৃত্যু রক্ষা করেছি। আমি একজন রক্ষা কর্মী বলে যে সে ছিল... ...যে কিনা এক অকাল্টহাসি জানে এবং তার একটা কবর স্বপ্ন আছে। ঈশ্বর তাকে রক্ষা করতে যাচ্ছেন। বাবা বলেন, \"মানুষ আমাদের কথা শুনেছে।\" তিনি আত্মসমর্পণ করেছেন এবং আমরা সাক্ষ্য রক্ষা করতে শিখেছি না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَبْدِ اللَّهِ الْأَوْدِيُّ ‏ ‏عَن ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ ‏ ‏أَنَّ رَجُلًا يُقَالُ لَهُ ‏ ‏حَمَمَةُ ‏ ‏كَانَ مِنْ ‏ ‏أَصْحَابِ مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى ‏ ‏أَصْبَهَانَ ‏ ‏غَازِيًا فِي خِلَافَةِ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ اللَّهُمَّ إِنَّ ‏ ‏حَمَمَةَ ‏ ‏يَزْعُمُ أَنَّهُ يُحِبُّ لِقَاءَكَ فَإِنْ كَانَ ‏ ‏حَمَمَةُ ‏ ‏صَادِقًا فَاعْزِمْ لَهُ صِدْقَهُ وَإِنْ كَانَ كَاذِبًا فَاعْزِمْ عَلَيْهِ وَإِنْ كَرِهَ اللَّهُمَّ لَا تَرُدَّ ‏ ‏حَمَمَةَ ‏ ‏مِنْ سَفَرِهِ هَذَا قَالَ فَأَخَذَهُ الْمَوْتُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً الْبَطْنُ ‏ ‏فَمَاتَ ‏ ‏بأَصْبَهَانَ ‏ ‏قَالَ فَقَامَ ‏ ‏أَبُو مُوسَى ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّا وَاللَّهِ مَا سَمِعْنَا فِيمَا سَمِعْنَا مِنْ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا بَلَغَ عِلْمَنَا إِلَّا أَنَّ ‏ ‏حَمَمَةَ ‏ ‏شَهِيدٌ ‏","","",""],[18829,18829,"","আমরা একদিন বাবাকে সবচেয়ে দুঃখের সময়ে বাঁচানোর চেষ্টা করার পর থেকে কথা বললাম। নবী ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং তিনি পবিত্র ঘোড়দৌড়ের মতো আত্মসমর্পণ করবেন। খারাপ থেকে খারাপ। দয়া করে, কত কঠিন হতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَن ‏ ‏أَبِي كَبْشَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مُوسَى ‏ ‏يَقُولُ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْجَلِيسِ الصَّالِحِ كَمَثَلِ الْعَطَّارِ إِنْ لَا ‏ ‏يُحْذِيكَ ‏ ‏يَعْبَقُ ‏ ‏بِكَ مِنْ رِيحِهِ وَمَثَلُ الْجَلِيسِ السَّوْءِ كَمَثَلِ صَاحِبِ ‏ ‏الْكِيرِ ‏","","",""],[18830,18830,"","আমি একটা গাছের জন্য প্রার্থনা করি, যেটা প্রভু তার গর্ভে ফিরে যাওয়ার চেষ্টা করেন ।","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا سُمِّيَ الْقَلْبُ مِنْ تَقَلُّبِهِ إِنَّمَا مَثَلُ الْقَلْبِ كَمَثَلِ رِيشَةٍ مُعَلَّقَةٍ فِي أَصْلِ شَجَرَةٍ يُقَلِّبُهَا الرِّيحُ ظَهْرًا لِبَطْنٍ ‏","","",""],[18831,18831,"","তিনি আমাদের যথেষ্ট স্পর্শ করেছিলেন এবং আমাদের নিরাপদে স্পর্শ করেছিলেন । তোমাদের সবার মৃত্যুর জন্য দায়ী।","‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَيْنَ أَيْدِيكُمْ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ فِيهَا مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا ‏ ‏وَيُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا الْقَاعِدُ فِيهَا خَيْرٌ مِنْ الْقَائِمِ وَالْقَائِمُ فِيهَا خَيْرٌ مِنْ الْمَاشِي وَالْمَاشِي فِيهَا خَيْرٌ مِنْ السَّاعِي قَالُوا فَمَا تَأْمُرُنَا قَالَ كُونُوا ‏ ‏أَحْلَاسَ ‏ ‏بُيُوتِكُمْ ‏","","",""],[18832,18832,"","দিনের বেলায় আমরা কীভাবে একা থাকব, সেই বিষয়ে আমরা কথা বলেছিলাম । যখন আমি বাড়ি শুকাচ্ছি আর আমার নিজের জন্য এটা রেখে দিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ ثَرْوَانَ ‏ ‏عَن ‏ ‏الْهُزَيْلِ بْنِ شُرَحْبِيلَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَسِّرُوا ‏ ‏قِسِيَّكُمْ ‏ ‏وَقَطِّعُوا ‏ ‏أَوْتَارَكُمْ ‏ ‏يَعْنِي فِي ‏ ‏الْفِتْنَةِ ‏ ‏وَالْزَمُوا أَجْوَافَ الْبُيُوتِ وَكُونُوا فِيهَا كَالْخَيِّرِ مِنْ بَنِي ‏ ‏آدَمَ ‏","","",""],[18833,18833,"","আমরা আনন্দের সাথে কথা বলেছি, আমরা সেই সব মানুষদের কথা বলছি যারা আমার বাবার প্রতি তার আসক্তি ভুলে গেছে, যারা কোরানের টাওয়ারের মতো কোরান পড়তে পারে। তার ভালো আর আশা, তার মিষ্টি রান্নার আশা, আর কখনোই তাকে কখনোই এমন ভাবে বয়ে নিয়ে যায় না যে পবিত্র প্রভুকে পড়তে পারে। পবিত্র পিতার মত পবিত্র পিতার পড়া","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏أَنَسٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ مَثَلُ ‏ ‏الْأُتْرُجَّةِ ‏ ‏طَعْمُهَا طَيِّبٌ وَرِيحُهَا طَيِّبٌ وَمَثَلُ الْمُؤْمِنِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ مَثَلُ التَّمْرَةِ طَعْمُهَا طَيِّبٌ وَلَا رِيحَ لَهَا وَمَثَلُ الْمُنَافِقِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الرَّيْحَانَةِ طَيِّبٌ رِيحُهَا وَلَا طَعْمَ لَهَا ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً طَعْمُهَا مُرٌّ ‏ ‏وَمَثَلُ الْمُنَافِقِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ مَثَلُ ‏ ‏الْحَنْظَلَةِ ‏ ‏لَا رِيحَ لَهَا وَطَعْمُهَا خَبِيثٌ ‏","","",""],[18834,18834,"","আমরা খুশির সাথে কথা বলেছি, \"আমরা কাপুরুষ হিসেবে শাসন করেছি।\" আমার মনে হয় আমি তার সাথে লড়াই করার চেষ্টা করছি, যে কিনা তার প্রার্থনায় বসে আছে। তার প্রার্থনা শুনে মনে হচ্ছে প্রভুর কথা শুনেই আমার বাবা চুপ করে বলেছিলেন, কিন্তু আমি বলেছি প্রভুর কথা মেনে চলতে। আমাকে অনুসরণ কর একজন শক্তিধর মানুষ, আমি যা করতে চাই বলে আমি যা করতে চাই, তার জন্য তোমার প্রার্থনা করি এবং আমরা আমাদের নিজস্ব চলচ্চিত্র তৈরি করি। আমি আপনাদের পড়াবো যদি তারা বড় হয় এবং বড় হয়। বল, ডার্ক ওয়ানের আসার আগেই সে তোমাকে বলে দিয়েছে যে ঈশ্বর এটা করেছেন, সে আল্লাহ্‌কে এটা বলার জন্য শুনেছি যে তারা হয়তো তোমাদের জন্য ঈশ্বরের কথা শুনেছে। ( গীতসংহিতা ৩৭: ১০) আপনার কাছে ঈশ্বরের কাছে প্রার্থনা করুন এবং তিনি আপনাকে তার কাছে সমর্পণ করবেন, যদি আপনি শপথ করার শপথ করে থাকেন । শপথ করার শপথটা হল, ভালদের কাছে লালা, নবী এবং তাঁর আশীর্বাদের জন্য, ঈশ্বর, আমি নিশ্চিত সে একজন সালাদ। দাড়ি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ ثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَن ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏أَنَّ ‏ ‏الْأَشْعَرِيَّ ‏ ‏صَلَّى بِأَصْحَابِهِ صَلَاةً فَقَالَ رَجُلٌ مِنْ الْقَوْمِ حِينَ جَلَسَ فِي صَلَاتِهِ أَقَرَّتْ الصَّلَاةُ ‏ ‏بِالْبِرِّ ‏ ‏وَالزَّكَاةِ فَلَمَّا قَضَى ‏ ‏الْأَشْعَرِيُّ ‏ ‏صَلَاتَهُ أَقْبَلَ عَلَى الْقَوْمِ فَقَالَ أَيُّكُمْ الْقَائِلُ كَلِمَةَ كَذَا وَكَذَا ‏ ‏فَأَرَمَّ ‏ ‏الْقَوْمُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏أَرَمَّ ‏ ‏السُّكُوتُ ‏ ‏قَالَ لَعَلَّكَ يَا ‏ ‏حِطَّانُ ‏ ‏قُلْتَهَا ‏ ‏لِحِطَّانَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ وَاللَّهِ إِنْ قُلْتُهَا وَلَقَدْ رَهِبْتُ أَنْ ‏ ‏تَبْعَكَنِي ‏ ‏بِهَا قَالَ رَجُلٌ مِنْ الْقَوْمِ أَنَا قُلْتُهَا وَمَا أَرَدْتُ بِهَا إِلَّا الْخَيْرَ فَقَالَ ‏ ‏الْأَشْعَرِيُّ ‏ ‏أَلَا تَعْلَمُونَ مَا تَقُولُونَ فِي صَلَاتِكُمْ فَإِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَنَا فَعَلَّمَنَا سُنَّتَنَا وَبَيَّنَ لَنَا صَلَاتَنَا فَقَالَ ‏ ‏أَقِيمُوا صُفُوفَكُمْ ثُمَّ لِيَؤُمَّكُمْ أَقْرَؤُكُمْ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا قَالَ ‏ { ‏وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ يُجِبْكُمْ اللَّهُ ثُمَّ إِذَا كَبَّرَ الْإِمَامُ وَرَكَعَ فَكَبِّرُوا وَارْكَعُوا فَإِنَّ الْإِمَامَ يَرْكَعُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتِلْكَ بِتِلْكَ فَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ يَسْمَعْ اللَّهُ لَكُمْ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ عَلَى لِسَانِ نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ وَإِذَا كَبَّرَ الْإِمَامُ وَسَجَدَ فَكَبِّرُوا وَاسْجُدُوا فَإِنَّ الْإِمَامَ يَسْجُدُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتِلْكَ بِتِلْكَ فَإِذَا كَانَ عِنْدَ الْقَعْدَةِ فَلْيَكُنْ مِنْ أَوَّلِ قَوْلِ أَحَدِكُمْ أَنْ يَقُولَ التَّحِيَّاتُ الطَّيِّبَاتُ الصَّلَوَاتُ لِلَّهِ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ ‏","","",""],[18835,18835,"","যখন এই ঘটনা ঘটে, তখন আমরা এক ঘোড়ার সাথে এক বানরের সাথে আমরা সুখী সম্পর্কে কথা বলেছিলাম। আমার মনে হয় আমি আমার ছেলেকে চুমু দিচ্ছি, প্রার্থনা করছি এবং আমার লোকদের কথা শোনাব। আমি বলেছিলাম যে, আপনার ডান কাজ যে - ব্যক্তি করেছেন, তিনি কখনও তা বুঝতে পারবেন না । ঈশ্বর যখন তাঁর কাছে এসেছিলেন, তখন তিনি এক দ্বন্দ্বের সঙ্গে তার অনুসরণ করেছিলেন । আমাকে হুমকি দেয়ার জন্য, সে তার ঋণের উপর সফল হবে। সে তাকে তিনবার জিজ্ঞেস করলো যে সে নাকি রাতে খুন করবে। আমি ঘুমাতাম এবং আমি ঘুমাতাম। আমি নিজের শক্তি নিয়ে যেতে পারবো না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بُرْدَةَ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏أَقْبَلْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعِي رَجُلَانِ مِنْ ‏ ‏الْأَشْعَرِيِّينَ ‏ ‏أَحَدُهُمَا عَنْ يَمِينِي وَالْآخَرُ عَنْ يَسَارِي فَكِلَاهُمَا سَأَلَ الْعَمَلَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَاكُ ‏ ‏قَالَ مَا تَقُولُ يَا ‏ ‏أَبَا مُوسَى ‏ ‏أَوْ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏قَالَ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا وَمَا شَعُرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ قَالَ فَكَأَنِّي أَنْظُرُ إِلَى سِوَاكِهِ تَحْتَ شَفَتِهِ ‏ ‏قَلَصَتْ ‏ ‏قَالَ ‏ ‏إِنِّي أَوْ لَا نَسْتَعْمِلُ عَلَى عَمَلِنَا مَنْ أَرَادَهُ وَلَكِنْ اذْهَبْ أَنْتَ يَا ‏ ‏أَبَا مُوسَى ‏ ‏أَوْ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏فَبَعَثَهُ عَلَى ‏ ‏الْيَمَنِ ‏ ‏ثُمَّ أَتْبَعَهُ ‏ ‏مُعَاذَ بْنَ جَبَلٍ ‏ ‏فَلَمَّا قَدِمَ عَلَيْهِ قَالَ انْزِلْ وَأَلْقَى لَهُ وِسَادَةً فَإِذَا رَجُلٌ عِنْدَهُ ‏ ‏مُوثَقٌ ‏ ‏فَقَالَ مَا هَذَا قَالَ كَانَ يَهُودِيًّا فَأَسْلَمَ ثُمَّ رَاجَعَ دِينَهُ دِينَ السَّوْءِ فَتَهَوَّدَ فَقَالَ لَا أَجْلِسُ حَتَّى يُقْتَلَ قَضَاءُ اللَّهِ وَرَسُولِهِ ثَلَاثَ مِرَارٍ فَأَمَرَ بِهِ فَقُتِلَ ثُمَّ تَذَاكَرْنَا ‏ ‏قِيَامَ ‏ ‏اللَّيْلِ فَقَالَ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏أَمَّا أَنَا فَأَنَامُ وَأَقُومُ أَوْ أَقُومُ وَأَنَامُ وَأَرْجُو فِي نَوْمَتِي مَا أَرْجُو فِي ‏ ‏قَوْمَتِي ‏","","",""],[18836,18836,"","আমরা বাবার মোটাতার দুই বছর সুখী কথা বলেছি, কিন্তু ঈশ্বরের আছে আমার বাবার ছেলে আছে। কবি বলেছিলেন, এটা ঈশ্বরের কাছে তাঁর কাছে পৌঁছে দেয়া হবে এবং তিনি তরল বা তরল পদার্থ সমর্পণ করবেন। যা - ই হোক না কেন, ঈশ্বরের তাঁকে বিশ্বাস করার জন্য অন্য কোনো উপায় নেই । দুই বিশ্বাসী।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَن ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بُرْدَةَ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَهُ السَّائِلُ أَوْ ذُو ‏ ‏الْحَاجَةِ ‏ ‏قَالَ ‏ ‏اشْفَعُوا ‏ ‏تُؤْجَرُوا وَلْيَقْضِ اللَّهُ عَزَّ وَجَلَّ عَلَى لِسَانِ رَسُولِهِ مَا شَاءَ وَقَالَ الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا وَقَالَ ‏ ‏الْخَازِنُ ‏ ‏الْأَمِينُ الَّذِي يُؤَدِّي مَا أُمِرَ بِهِ طَيِّبَةً بِهِ نَفْسُهُ أَحَدُ الْمُتَصَدِّقِينَ ‏","","",""],[18837,18837,"","আমরা একটি সুখী এবং দৃঢ় ইচ্ছা সঙ্গে বাস করার চেষ্টা করেছি. আমরা একটি প্রথা একটি সময় তিনি একটি সময়ে একটি সময়ে জীবন যে যখন তিনি একটি সময় তিনি নিজেকে হত্যা যখন তিনি একটি সময়ে জীবন. পুত্র একবার আমাকে অনুভব. বাবা, আমার পালনকর, আমার প্রভু, আমার প্রভু ও প্রভু। পুরুষটি অনেক বেশি এবং কখনো আপনাকে দ্রাক্ষা হিসেবে অন্তর্ভুক্ত করা হয়নি। তৃতীয়টি হচ্ছে খাদ্যের স্তর।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏عَن ‏ ‏مُرَّةَ الْهَمْدَانِيِّ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَمُلَ مِنْ الرِّجَالِ كَثِيرٌ وَلَمْ يَكْمُلْ مِنْ النِّسَاءِ غَيْرُ ‏ ‏مَرْيَمَ بِنْتِ عِمْرَانَ ‏ ‏وَآسِيَةَ امْرَأَةِ فِرْعَوْنَ ‏ ‏وَإِنَّ فَضْلَ ‏ ‏عَائِشَةَ ‏ ‏عَلَى النِّسَاءِ كَفَضْلِ ‏ ‏الثَّرِيدِ ‏ ‏عَلَى سَائِرِ الطَّعَامِ ‏","","",""],[18838,18838,"","আমরা বাবার সাথে কথা বলেছিলাম আমার বাবার সাথে একজন যাজক হিসেবে তার জেদের কথা. অথবা সে যে আবার তাকে শিকার করছে, সে বলে ঈশ্বর তাকে পথ করে দিয়েছে. আর সে তার পথ খুঁজে পেয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْعُمَيْسِ ‏ ‏عَن ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَن ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏يَوْمُ عَاشُورَاءَ ‏ ‏يَوْمًا تَصُومُهُ ‏ ‏الْيَهُودُ ‏ ‏تَتَّخِذُهُ عِيدًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُومُوهُ أَنْتُمْ ‏","","",""],[18839,18839,"","আমরা আমার বাবার সাথে কথা বলেছিলাম যে সে ঈশ্বরের কাছে যাবে, যদি সে তার কাছে নিজেকে সমর্পণ করত যদি সে তার প্রত্যেক মানুষের কাছে মূল্য থাকত, যার আশা ছিল সে এই আশা থেকে পেয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَن ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ الْقِيَامَةِ دُفِعَ إِلَى كُلِّ مُؤْمِنٍ رَجُلٌ مِنْ أَهْلِ ‏ ‏الْمِلَلِ ‏ ‏فَقَالَ لَهُ هَذَا فِدَاؤُكَ مِنْ النَّارِ ‏","","",""],[18840,18840,"","সেই যাজক আমাকে বলেছিলেন যে, ভাববাদী তার কাছে প্রার্থনা করেন এবং জিজ্ঞেস করেন যে, কেন আমি এটা ঈশ্বর । সে বলেছে যে সে আমাকে বলেছে যে সে আমাকে বলেনি. কামনাটা হচ্ছে সেই মহিলা যাকে আমার শক্তি আছে আর প্রতারণা করা হয়েছে আর তারপর আমি শেষ হয়ে গেছি. তোমার বাবার আশীর্বাদ আর ঈশ্বর তাদের মধ্য দিয়ে চলে এসেছেন, আমি খুশি নই তুমি জানো না আমি কী নিয়ে কথা বলছিলাম... সে এতটা নিশ্চিত নয় যে সে তোমাকে নিতে আসছে। আর যদি আমরা এক বছর প্রার্থনা করি... ...তাহলে সে আত্মসমর্পণ করবে যতক্ষণ না সে সাক্ষ্য দিতে না পারে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَن ‏ ‏قَيْسِ بْنِ مُسْلِمٍ ‏ ‏عَن ‏ ‏طَارِقِ بْنِ شِهَابٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏قَدِمْتُ مِنْ ‏ ‏الْيَمَنِ ‏ ‏قَالَ فَقَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَ ‏ ‏أَهْلَلْتَ ‏ ‏قَالَ قُلْتُ ‏ ‏بِإِهْلَالٍ ‏ ‏كَإِهْلَالِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ هَلْ مَعَكَ مِنْ ‏ ‏هَدْيٍ ‏ ‏قَالَ قُلْتُ ‏ ‏يَعْنِي لَا ‏ ‏قَالَ فَأَمَرَنِي فَطُفْتُ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ أَتَيْتُ امْرَأَةً مِنْ قَوْمِي فَمَشَطَتْ رَأْسِي وَغَسَلَتْهُ ثُمَّ أَحْلَلْتُ فَلَمَّا كَانَ يَوْمُ ‏ ‏التَّرْوِيَةِ ‏ ‏أَهْلَلْتُ ‏ ‏بِالْحَجِّ قَالَ فَكُنْتُ أُفْتِي النَّاسَ بِذَلِكَ ‏ ‏إِمَارَةَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏فَبَيْنَا أَنَا وَاقِفٌ فِي سُوقِ الْمَوْسِمِ إِذْ جَاءَ رَجُلٌ ‏ ‏فَسَارَّنِي ‏ ‏فَقَالَ إِنَّكَ لَا تَدْرِي مَا أَحْدَثَ أَمِيرُ الْمُؤْمِنِينَ فِي شَأْنِ ‏ ‏النُّسُكِ ‏ ‏قَالَ قُلْتُ أَيُّهَا النَّاسُ مَنْ كُنَّا أَفْتَيْنَاهُ فِي شَيْءٍ ‏ ‏فَلْيَتَّئِدْ ‏ ‏فَهَذَا أَمِيرُ الْمُؤْمِنِينَ قَادِمٌ عَلَيْكُمْ فَبِهِ فَأْتَمُّوا قَالَ فَقَالَ لِي إِنْ نَأْخُذْ بِكِتَابِ اللَّهِ تَعَالَى فَإِنَّهُ يَأْمُرُ بِالتَّمَامِ وَإِنْ نَأْخُذْ بِسُنَّةِ نَبِيِّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّهُ لَمْ ‏ ‏يَحِلَّ ‏ ‏حَتَّى ‏ ‏نَحَرَ ‏ ‏الْهَدْيَ ‏","","",""],[18841,18841,"","আমরা একে অপরের কথা বলেছি কিন্তু আমার কাছে আছে বাবার দাদাকে আবার সাহায্য করতে। ঈশ্বর এটা উদ্ধার করতে হবে এবং প্রতিদিন আমি ঈশ্বরের আশীর্বাদ পাব। ফ্রি!","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ الْكِنْدِيُّ ‏ ‏عَن ‏ ‏سَعِيدٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَتُوبُ إِلَى اللَّهِ عَزَّ وَجَلَّ فِي كُلِّ يَوْمٍ مِائَةَ مَرَّةٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏يَعْنِي ‏ ‏مُغِيرَةَ بْنَ أَبِي الْحُرِّ ‏","","",""],[18842,18842,"","আমরা কথা বলেছি বাবা কত খুশি ছিলেন যে আমার বাবা বাধ্য ছিলেন। আমি তাকে একটা ইঙ্গিত দেব আর ঈশ্বর বলেন যে যুবকটি ভালো হবে। কবি আর একজন যুবক যে বলল। তাকে অলৌকিক কাজগুলো থেকে বিক্রি করতে হবে এবং যুদ্ধের প্রতিটি মাতালকে হত্যা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏بَعَثَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏وَمُعَاذُ بْنُ جَبَلٍ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ شَرَابًا يُصْنَعُ بِأَرْضِنَا يُقَالُ لَهُ ‏ ‏الْمِزْرُ ‏ ‏مِنْ الشَّعِيرِ وَشَرَابٌ يُقَالُ لَهُ ‏ ‏الْبِتْعُ ‏ ‏مِنْ الْعَسَلِ فَقَالَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[18843,18843,"","আমরা বাবার সাথে কথা বলেছি... ...ঈশ্বর তার কাছে প্রার্থনা করেছেন, যদি আমি তোমাকে কখনো খুঁজে পাই,","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏بُرَيْدُ بْنُ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا مَرَّ أَحَدُكُمْ بِالنَّبْلِ فِي الْمَسْجِدِ فَلْيُمْسِكْ ‏ ‏بِنُصُولِهَا ‏","","",""],[18844,18844,"","আমরা আমার বাবার কথা বলেছিলাম যে তিনি ঈশ্বরের কাছে যাচ্ছেন, যদি তিনি নিজেকে আত্মসমর্পণ করতেন যদি তিনি প্রত্যেক মানুষের কাছে মূল্য থাকত, যাদের উপহার হিসেবে আশা ছিল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَن ‏ ‏طَلْحَةَ بْنِ يَحْيَى ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ الْقِيَامَةِ دُفِعَ إِلَى كُلِّ مُؤْمِنٍ رَجُلٌ مِنْ أَهْلِ ‏ ‏الْمِلَلِ ‏ ‏فَيُقَالُ لَهُ هَذَا فِدَاؤُكَ مِنْ النَّارِ ‏","","",""],[18845,18845,"","আমি আমার বাবার সাথে প্রভু মোশির চেয়ে ভালো কথা বলেছি, যদি মেসারকে খুন করতে হয়, তাহলে আমি ওদেরকে মেরে ফেলব, সে তার সঙ্গীকে মারতে চেয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونٍَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَاجَهَ الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَقَتَلَ أَحَدُهُمَا صَاحِبَهُ فَهُمَا فِي النَّارِ قِيلَ يَا رَسُولَ اللَّهِ هَذَا الْقَاتِلُ فَمَا بَالُ الْمَقْتُولِ قَالَ إِنَّهُ أَرَادَ قَتْلَ صَاحِبِهِ ‏","","",""],[18846,18846,"","আমরা বাবার কথা বলেছি, আমার বাবার ক্লান্ত হওয়ার জন্য, ঈশ্বর তাদের কিছু বছর কথা দিয়েছেন যে তোমাকে হত্যা করতে হবে না। সে পরবর্তী তিন বছর থেকে বলবে সে তাকে যেতে দিবে না। যাও, আমি ওর সাথে যা দেখছি তা নিয়ে আমি মাথা ঘামাচ্ছি না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَن ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَن ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبُو مُوسَى ‏ ‏عَلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَرَجَعَ فَلَقِيَهُ ‏ ‏عُمَرُ ‏ ‏فَقَالَ مَا شَأْنُكَ رَجَعْتَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مِنْ اسْتَأْذَنَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ ‏ ‏فَقَالَ ‏ ‏لَتَأْتِيَنَّ عَلَى هَذَا ‏ ‏بِبَيِّنَةٍ ‏ ‏أَوْ لَأَفْعَلَنَّ وَلَأَفْعَلَنَّ فَأَتَى مَجْلِسَ قَوْمِهِ فَنَاشَدَهُمْ اللَّهَ تَعَالَى ‏ ‏فَقُلْتُ أَنَا مَعَكَ فَشَهِدُوا لَهُ بِذَلِكَ فَخَلَّى سَبِيلَهُ ‏","","",""],[18847,18847,"","বাবা বলেছেন যে আমার মা আমাকে ক্ষমা করে দিয়েছে। অতিথি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏وهَاشِمٌ يَعْنِي ابْنَ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أُمَّتِي أُمَّةٌ مَرْحُومَةٌ لَيْسَ عَلَيْهَا فِي الْآخِرَةِ عَذَابٌ إِنَّمَا عَذَابُهُمْ فِي الدُّنْيَا الْقَتْلُ وَالْبَلَابِلُ وَالزَّلَازِلُ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏بِالزَّلَازِلِ وَالْقَتْلِ وَالْفِتَنِ ‏","","",""],[18848,18848,"","আমরা তোমাকে সাহায্য করার চেষ্টার চেয়েও বেশি কথা বলেছি। আমার বাবা একজন চমৎকার মানুষ যে কিনা একজন দেবতা। সে ঈশ্বরের কাছে প্রার্থনা করেছে এবং সে ইচ্ছার জন্য প্রার্থনা করেছে। আত্মসমর্পন করা এবং অপমান করা, বা লিখিত লিখিত লিখিত লিখিত লিখিত লেখা।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏الْعَوَّامُ بْنُ حَوْشَبٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْمَاعِيلَ السَّكْسَكِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا بُرْدَةَ بْنَ أَبِي مُوسَى ‏ ‏وَاصْطَحَبَ هُوَ ‏ ‏وَيَزِيدُ بْنُ أَبِي كَبْشَةَ ‏ ‏فِي سَفَرٍ وَكَانَ ‏ ‏يَزِيدُ ‏ ‏يَصُومُ فَقَالَ لَهُ ‏ ‏أَبُو بُرْدَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا مُوسَى ‏ ‏مِرَارًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا مَرِضَ الْعَبْدُ أَوْ سَافَرَ كُتِبَ لَهُ مِنْ الْأَجْرِ مِثْلُ مَا كَانَ يَعْمَلُ مُقِيمًا صَحِيحًا ‏","","",""],[18849,18849,"","আমরা কথা বলেছিলাম একটি বিতর্ক সৃষ্টি করতে। আমার বাবা বলেছেন, তিনি আমার বাবার কথা শুনেছেন আর তিনি চলে যাচ্ছেন। মৃত্যুর পর তার মৃত্যু দেখে ভয় পেয়ে যায় যে সে বলেছে যে সে ব্যর্থ হয়েছে। তিনি যখন শুষ্ক হয়ে যাবেন, তখন তিনি তার তরবারি দিয়ে চলে যাবেন আর তাকে মেরে ফেলবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا ثَنَا ‏ ‏جَعْفَرٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏أَبَا عِمْرَانَ الْجَوْنِيَّ ‏ ‏يَقُولُ ثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏وَهُوَ ‏ ‏بِحَضْرَةِ الْعَدُوِّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَبْوَابَ الْجَنَّةِ تَحْتَ ظِلَالِ السُّيُوفِ قَالَ فَقَامَ رَجُلٌ مِنْ الْقَوْمِ ‏ ‏رَثُّ ‏ ‏الْهَيْئَةِ فَقَالَ يَا ‏ ‏أَبَا مُوسَى ‏ ‏أَأَنْتَ سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ هَذَا قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏فَرَجَعَ إِلَى أَصْحَابِهِ فَقَالَ ‏ ‏أَقْرَأُ عَلَيْكُمْ السَّلَامَ ثُمَّ كَسَرَ ‏ ‏جَفْنَ ‏ ‏سَيْفِهِ ثُمَّ مَشَى بِسَيْفِهِ إِلَى الْعَدُوِّ فَضَرَبَ بِهِ حَتَّى قُتِلَ ‏","","",""],[18850,18850,"","আমরা ইশ্বরের সাথে কথা বলেছি, যখন আমরা পর্বতে ফিরে যাব, ঈশ্বর তাঁর পুত্রের মঙ্গল করুন, তার মঙ্গলের জন্য আল্লাহ তার ছেলেকে আশীর্বাদ করবেন। অন্যদের সাথে নিজেদের তুলনা করা যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الصَّمَدِ الْعَمِّىُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَن ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي الْجَنَّةِ خَيْمَةٌ مِنْ لُؤْلُؤَةٍ مُجَوَّفَةٍ عَرْضُهَا سِتُّونَ مِيلًا فِي كُلِّ زَاوِيَةٍ مِنْهَا أَهْلٌ مَا يَرَوْنَ الْآخَرِينَ يَطُوفُ عَلَيْهِمْ الْمُؤْمِنُ ‏","","",""],[18851,18851,"","যখন আমি তোমাকে ভালবাসি, তখন ঈশ্বরের দোহাইর কথা বলেছিলাম। কিন্তু তাকে বলা হয়েছিল যে তিনি ঈশ্বরের কাছে পাঠান, তিনি তাকে জানতেন এবং তিনি আমাকে জানতেন তিনি আমার প্রতি পাগল ছিলেন, আমি তাদের দিকে তাকিয়ে দেখব যখন তারা মারা যাবে তাদের ফোন করার চেষ্টা করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ ‏ ‏عَن ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَنَّتَانِ مِنْ فِضَّةٍ آنِيَتُهُمَا وَمَا فِيهِمَا وَجَنَّتَانِ مِنْ ذَهَبٍ آنِيَتُهُمَا وَمَا فِيهِمَا وَمَا بَيْنَ الْقَوْمِ وَبَيْنَ أَنْ يَنْظُرُوا إِلَى رَبِّهِمْ تَعَالَى إِلَّا رِدَاءُ الْكِبْرِيَاءِ عَلَى وَجْهِهِ عَزَّ وَجَلَّ فِي جَنَّاتِ عَدْنٍ ‏","","",""],[18852,18852,"","বাবার ভালোবাসা দিয়ে আমার বাবা আমার বাবার সাথে কথা বলেছি। আমার বাবা তার কাছে প্রার্থনা করেছেন এবং ডজন খানেক বার স্বর্গে ক্যাম্পটি দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَن ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَن ‏ ‏أَبِي بَكْرِ بْنِ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخَيْمَةُ دُرَّةٌ طُولُهَا فِي السَّمَاءِ سِتُّونَ مِيلًا فِي كُلِّ زَاوِيَةٍ مِنْهَا أَهْلٌ لِلْمُؤْمِنِ وَلَا يَرَاهُمْ الْآخَرُونَ ‏","","",""],[18853,18853,"","বেনের সাথে আমরা কথা বলেছি, আর তারপর আমরা আমার বাবাকে দেবতা হিসেবে বিচার করতে চাই, সে বলতে রাজি হবে যে তিনি ক্ষমা চান। ঈশ্বর আপনাকে হুমকি দিচ্ছেন এবং অনুরোধ করবেন কতটা তার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏قَالَ ثَنَا ‏ ‏سُفْيَانُ بْنُ سَعِيدٍ ‏ ‏عَن ‏ ‏حَكِيمِ بْنِ دَيْلَمٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏يَهُودُ ‏ ‏يَأْتُونَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَتَعَاطَسُونَ عِنْدَهُ رَجَاءَ أَنْ يَقُولَ لَهُمْ يَرْحَمُكُمْ اللَّهُ فَكَانَ يَقُولُ لَهُمْ ‏ ‏يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ ‏","","",""],[18854,18854,"","সকালে আমরা দেখা করেছি যে সে হয়তো তার কথা শুনেছেন আমি সকাল থেকে গভর্নরের কাছ থেকে বলছি যে সে আমাদের সাহায্য করার চেষ্টা করেছে. আমার বাবা বলেছেন, আল্লাহ ঈশ্বরের কাছে এসেছেন এবং আল্লাহ তাকে সাহায্য করবেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏مُحَمَّدِ بْنِ الصَّبَّاحِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَن ‏ ‏بُرَيْدٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَعَاهَدُوا الْقُرْآنَ فَإِنَّهُ أَشَدُّ ‏ ‏تَفَلُّتًا ‏ ‏مِنْ قُلُوبِ الرِّجَالِ مِنْ الْإِبِلِ مِنْ ‏ ‏عُقُلِهِ ‏","","",""],[18855,18855,"","আমরা আবেগ নিয়ে কথা বলেছি, বাবার বাবার 'চাষ'র সুখী ছেলে নিয়ে। সে যদি কাজ না করত বা বলতে পারত যে তার যা করার দরকার ছিল, সে বলছিল, সে তা করতে পারবে না। খারাপ লোকের সাথে তোমাকে স্পর্শ করার জন্য, সে আমার বন্ধু।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عَلَى كُلِّ مُسْلِمٍ ‏ ‏صَدَقَةٌ ‏ ‏قَالُوا فَإِنْ لَمْ يَجِدْ قَالَ يَعْتَمِلُ بِيَدَيْهِ فَيَنْفَعُ نَفْسَهُ وَيَتَصَدَّقُ قَالُوا فَإِنْ لَمْ يَفْعَلْ ‏ ‏أَوْ يَسْتَطِعْ ‏ ‏قَالَ يُعِينُ ذَا الْحَاجَةِ ‏ ‏الْمَلْهُوفَ ‏ ‏قَالَ فَإِنْ لَمْ يَسْتَطِعْ ‏ ‏أَوْ لَمْ يَفْعَلْ ‏ ‏قَالَ يَأْمُرُ بِالْخَيْرِ قَالُوا فَإِنْ لَمْ يَسْتَطِعْ ‏ ‏أَوْ يَفْعَلْ ‏ ‏قَالَ يُمْسِكُ عَنْ الشَّرِّ فَإِنَّهُ ‏ ‏صَدَقَةٌ ‏","","",""],[18856,18856,"","আমরা আমার বাবার অসহায় ছেলেকে নিয়ে কথা বলেছি। আমার ভাইয়ের সাথে দেখা হয়েছে। ঈশ্বরের কাছে প্রার্থনা করবে যেন তিনি তার কাছে ক্ষমা চান এবং আপনার ভাই তাকে আদেশ দেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَن ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَن ‏ ‏أَخِيهِ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَدِمَ رَجُلَانِ مِنْ ‏ ‏الْأَشْعَرِيِّينَ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَجَعَلَا يُعَرِّضَانِ بِالْعَمَلِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَخْوَنَكُمْ عِنْدِي مَنْ يَطْلُبُهُ ‏","","",""],[18857,18857,"","আমরা বাবা মোসসকে বলেছিলাম, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন, এতিমকে তার শ্বাসে পাস করবেন, সে তার ক্ষমা করবে এবং সে কোন ভুল করবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو بُرْدَةَ ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسْتَأْمَرُ ‏ ‏الْيَتِيمَةُ فِي نَفْسِهَا فَإِنْ سَكَتَتْ فَقَدْ أَذِنَتْ وَإِنْ أَنْكَرَتْ لَمْ تُكْرَهْ ‏ ‏قُلْتُ ‏ ‏لِيُونُسَ ‏ ‏سَمِعْتَهُ مِنْهُ ‏ ‏أَوْ سَمِعْتَهُ مِنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[18858,18858,"","আমরা কথা বলেছি, হামাদ মানে আমাদের বাবার জীবনের দুই দিনের ছেলে আমি ঈশ্বরের কাছে প্রার্থনা করছি এবং সে বলবে যে তারা তাঁকে না বলে। তারা বাইরে যাচ্ছে। মানুষ ছড়িয়ে পড়ার সাথে সাথে, ঈশ্বরকে হত্যা করে, কে তোমাকে বলেছিল তুমি তাদের ছেড়ে চলে যাচ্ছ, বয়স হল, মানুষ বলল, ঈশ্বর,","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَن ‏ ‏أَبِي بَكْرِ بْنِ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبْشِرُوا وَبَشِّرُوا النَّاسَ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ صَادِقًا بِهَا دَخَلَ الْجَنَّةَ فَخَرَجُوا يُبَشِّرُونَ النَّاسَ فَلَقِيَهُمْ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَبَشَّرُوهُ فَرَدَّهُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَدَّكُمْ قَالُوا ‏ ‏عُمَرُ ‏ ‏قَالَ لِمَ رَدَدْتَهُمْ يَا ‏ ‏عُمَرُ ‏ ‏قَالَ إِذَنْ يَتَّكِلَ النَّاسُ يَا رَسُولَ اللَّهِ ‏","","",""],[18859,18859,"","আমরা বাবার প্রিয় প্রভুর প্রতি বাবার ভালোবাসা নিয়ে কথা বলেছি। লর্ড তার কাছে প্রার্থনা করেছেন এবং আশ্বস্ত করেছেন আমাদের কাছ থেকে না এসে কে চুরি করেছে এবং লুট করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَن ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنَّا مَنْ ‏ ‏حَلَقَ ‏ ‏وَخَرَقَ ‏ ‏وَسَلَقَ ‏","","",""],[18860,18860,"","বাবা আমাদের কাছে প্রার্থনা করেছিলেন যেন আমরা ঈশ্বরের অনুগ্রহের জন্য প্রার্থনা করি এবং আমরা যেন তাকে ফিরে যেতে পারি, সে সব পথে ফিরে যায়। আর তার মধ ্ যে সে যা ছিল সে-সন ্ বন ্ ধে অবশ ্ য প ্ রত ্ যক ্ ষদশ ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَن ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَن ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏لَقَدْ ذَكَّرَنَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏صَلَاةً كُنَّا ‏ ‏نُصَلِّيهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِمَّا نَسِينَاهَا وَإِمَّا تَرَكْنَاهَا عَمْدًا ‏ ‏يُكَبِّرُ كُلَّمَا رَكَعَ وَكُلَّمَا رَفَعَ وَكُلَّمَا سَجَدَ ‏","","",""],[18861,18861,"","আমরা সকালে কথা বলেছিলাম, বাবার বিখ্যাত আত্মা শুনে আমার বাবার খুব ঠান্ডা লাগে... ...তারা লর্ডের শান্তি শুনতে। লোকটার চোখের সামনে পড়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏مُحَمَّدِ بْنِ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ زَكَرِيَّا ‏ ‏عَن ‏ ‏بُرَيْدٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا ‏ ‏يُثْنِي ‏ ‏عَلَى رَجُلٍ ‏ ‏وَيُطْرِيهِ ‏ ‏فِي الْمِدْحَةِ فَقَالَ لَقَدْ أَهْلَكْتُمْ ‏ ‏أَوْ قَطَعْتُمْ ‏ ‏ظَهْرَ الرَّجُلِ ‏","","",""],[18862,18862,"","আমরা আশাবাদী যে আমরা যা করেছি তা নিয়ে কথা বলেছি, তারপর একটি দুঃখজনক ছেলে বাবার স্বপ্নের স্বপ্নের কথা বলছিল। তিনি বলেছিলেন, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং প্রভুকে সমর্পন করবেন ভালো বা ভালো কিছু করার জন্য। একজন ভালো প্রভু যিনি আমার বাবাকে হত্যা করেছিলেন... ...সেই খুনীকে হত্যা করেছিলেন... ...যে বলেছিল যে, বাবা অনুগত আর সে সফল হতে পারে নি। আগুনের মধ্যে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ مُؤَمَّلٌ ‏ ‏قَالَ ثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَن ‏ ‏أَبِي وَائِلٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اجْعَلْ ‏ ‏عُبَيْدًا أَبَا عَامِرٍ ‏ ‏فَوْقَ أَكْثَرِ النَّاسِ يَوْمَ الْقِيَامَةِ قَالَ فَقُتِلَ ‏ ‏عُبَيْدٌ ‏ ‏يَوْمَ ‏ ‏أَوْطَاسٍ ‏ ‏وَقَتَلَ ‏ ‏أَبُو مُوسَى ‏ ‏قَاتِلَ ‏ ‏عُبَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو وَائِلٍ ‏ ‏وَإِنِّي لَأَرْجُو أَنْ لَا يَجْمَعَ اللَّهُ عَزَّ وَجَلَّ بَيْنَ قَاتِلِ ‏ ‏عُبَيْدٍ ‏ ‏وَبَيْنَ ‏ ‏أَبِي مُوسَى ‏ ‏فِي النَّارِ ‏","","",""],[18863,18863,"","আমি তোমাকে আমার আগের চেয়ে ভাল মানুষ বলতে চাচ্ছিলাম... ...আমি তোমাকে ফোন করব... ...তারা এটা করবে, আমরা ভাল. তুমি বলেছিলে তুমি ঈশ্বরের অনুগ্রহে আছ, আমরা বলেছিলাম তুমি এটা প্রার্থনাও করতে যাওনি, ঈশ্বর তাঁর কাছে প্রার্থনা করো এবং সে তোমাকে আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَن ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏لَقِيَ ‏ ‏عُمَرُ ‏ ‏أَسْمَاءَ بِنْتَ عُمَيْسٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏فَقَالَ نِعْمَ الْقَوْمُ أَنْتُمْ لَوْلَا أَنَّكُمْ سَبَقْتُمْ بِالْهِجْرَةِ وَنَحْنُ أَفْضَلُ مِنْكُمْ قَالَتْ كُنْتُمْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَلِّمُ جَاهِلَكُمْ وَيَحْمِلُ رَاجِلَكُمْ وَفَرَرْنَا بِدِينِنَا فَقَالَتْ لَا أَنْتَهِي حَتَّى أَدْخُلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَتْ فَذَكَرَتْ مَا قَالَ لَهَا ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ ‏ ‏لَكُمْ الْهِجْرَةُ مَرَّتَيْنِ هِجْرَتُكُمْ إِلَى ‏ ‏الْحَبَشَةِ ‏ ‏وَهِجْرَتُكُمْ إِلَى ‏ ‏الْمَدِينَةِ ‏","","",""],[18864,18864,"","আমি বাবার সাথে তর্ক করেছি, আমার বাবাকে খুঁজে পাওয়ার কারণ আমি খুশি না। সে প্রভুর সাথে ঘোরে যাবে... সে এটা করতে পারবে.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏لَيْثِ بْنِ أَبِي سُلَيْمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏زَمَنَ ‏ ‏الْحَجَّاجِ ‏ ‏يُحَدِّثُ عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ رَأَى جِنَازَةً يُسْرِعُونَ بِهَا فَقَالَ ‏ ‏لِتَكُنْ عَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏","","",""],[18865,18865,"","আমরা তোমার টাকা নিয়ে কথা বলেছি, বাবা, আমাকে এমন মনে করে যেন আমার বাবার একটা বড় স্বপ্ন আছে। আমার মায়ের মাথা সেলাই হয়ে গেছে আর সে আমাকে ভয় দেখায় নি আর তাই তাকে ছিনিয়ে নিয়ে যায়। আমার মায়ের ভয় ফিরে পেতে আপনি এটা আর গন্ধ না, আপনি বলেছিলেন আপনার ছেলে এটা চিঁড়ে ফেলেছে, তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং তিনি বলেছিলেন তিনি এটা প্রার্থনা করবেন। তারা তাকে গন্ধ পেয়েছে, আর সে বিশ্বাস করেনি যে ঈশ্বর জিতে গেছেন আর তার কোন গন্ধ নেই.","‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ مَالِكٍ أَبُو جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ كُلَيْبٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَبِي مُوسَى ‏ ‏فِي بَيْتِ ابْنَةِ ‏ ‏أُمِّ الْفَضْلِ ‏ ‏فَعَطَسْتُ وَلَمْ ‏ ‏يُشَمِّتْنِي ‏ ‏وَعَطَسَتْ ‏ ‏فَشَمَّتَهَا ‏ ‏فَرَجَعْتُ إِلَى أُمِّي فَأَخْبَرْتُهَا فَلَمَّا جَاءَهَا قَالَتْ عَطَسَ ابْنِي عِنْدَكَ فَلَمْ ‏ ‏تُشَمِّتْهُ ‏ ‏وَعَطَسَتْ ‏ ‏فَشَمَّتَّهَا ‏ ‏فَقَالَ إِنَّ ابْنَكِ عَطَسَ فَلَمْ يَحْمَدْ اللَّهَ تَعَالَى فَلَمْ ‏ ‏أُشَمِّتْهُ ‏ ‏وَإِنَّهَا عَطَسَتْ فَحَمَدَتْ اللَّهَ تَعَالَى ‏ ‏فَشَمَّتُّهَا ‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا عَطَسَ أَحَدُكُمْ فَحَمِدَ اللَّهَ ‏ ‏فَشَمِّتُوهُ ‏ ‏وَإِنْ لَمْ يَحْمَدْ اللَّهَ عَزَّ وَجَلَّ فَلَا ‏ ‏تُشَمِّتُوهُ ‏ ‏فَقَالَتْ أَحْسَنْتَ أَحْسَنْتَ ‏","","",""],[18866,18866,"","আমরা পবিত্র পিতার সাথে কথা বলেছি যে আমরা গতবার শোকের কথা শুনেছি, আমার বাবার জন্য ঈশ্বর আমার সবচেয়ে খারাপ পিতা। ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ ثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَن ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحَبَّ دُنْيَاهُ أَضَرَّ بِآخِرَتِهِ وَمَنْ أَحَبَّ آخِرَتَهُ أَضَرَّ بِدُنْيَاهُ فَآثِرُوا مَا يَبْقَى عَلَى مَا ‏ ‏يَفْنَى ‏","","",""],[18867,18867,"","আমার নৈতিক মান তাকে ঈশ্বরের কাছে প্রার্থনা করতে বলেছিলেন যে, আমি তাঁর কাছে প্রার্থনা করব, যাকে আমি তার ঋণ শোধ করতে চাই । যা - ই হোক না কেন, তা প্রভাবিত করবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَن ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَن ‏ ‏الْمُطَّلِبِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ دُنْيَاهُ أَضَرَّ بِآخِرَتِهِ وَمَنْ أَحَبَّ آخِرَتَهُ أَضَرَّ بِدُنْيَاهُ فَآثِرُوا مَا يَبْقَى عَلَى مَا ‏ ‏يَفْنَى ‏","","",""],[18868,18868,"","আমরা কথা বলেছি, বাবা কিভাবে তার বাবাকে খুঁজে পেতে পারেন। আর যদি তারা চলে না যায়, তাহলে তুমি চলে যাও এবং চলে যাও, সবাই এটাতেই আছে। তাদের একজনের সাথে দেখা করতে আসায় আমি বিশ্বাস করি এটা স্বপ্ন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏مُعَاذًا ‏ ‏وَأَبَا مُوسَى ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ ‏ ‏بَشِّرُوا وَلَا ‏ ‏تُنَفِّرُوا ‏ ‏وَيَسِّرُوا وَلَا تُعَسِّرُوا ‏ ‏وَتَطَاوَعَا ‏ ‏وَلَا تَخْتَلِفَا قَالَ فَكَانَ لِكُلِّ وَاحِدٍ مِنْهُمَا ‏ ‏فُسْطَاطًا ‏ ‏يَكُونُ فِيهِ يَزُورُ أَحَدُهُمَا صَاحِبَهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏أَظُنُّهُ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏","","",""],[18869,18869,"","আমরা আমার বাবা একজন যাজকের সাথে কথা বলেছি যে একটা কুত্তার বাচ্চা আছে। ঈশ্বরের রোগী... ...সে একজন জেদীকে সাহায্য করেছে এই কথা বলতে। যদি তুমি বন্ধু হও, তাহলে তাকে ঈশ্বরের অনুগ্রহে বড় হতে বলো। সুখী বয় সম্বন্ধে কথা বলতে গিয়ে আমরা বলেছিলাম যে, তোমার চাচা একজন ছেলে ।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَن ‏ ‏زَائِدَةَ ‏ ‏عَن ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏مَرِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاشْتَدَّ مَرَضُهُ فَقَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏يُصَلِّ بِالنَّاسِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ رَقِيقٌ مَتَى يَقُومُ مَقَامَكَ لَا يَسْتَطِيعُ أَنْ يُصَلِّيَ بِالنَّاسِ فَقَالَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَإِنَّكُنَّ ‏ ‏صَوَاحِبَاتُ ‏ ‏يُوسُفَ ‏ ‏فَأَتَاهُ الرَّسُولُ فَصَلَّى ‏ ‏أَبُو بَكْرٍ ‏ ‏بِالنَّاسِ فِي ‏ ‏حَيَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ ثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ ثَنَا ‏ ‏عَبْدُ الْمَلِكِ يَعْنِي ابْنَ عُمَيْرٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَرِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ ‏ ‏فَذَكَرَهُ ‏","","",""],[18870,18870,"","আমরা বাবার সঙ্গে আমার বাবার কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يُونُسُ بْنُ الْحَارِثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّلَاةُ عَلَى ظَهْرِ الدَّابَّةِ فِي السَّفَرِ هَكَذَا وَهَكَذَا وَهَكَذَا وَهَكَذَا ‏","","",""],[18871,18871,"","আমরা আমার বাবাকে একজন যাজক হওয়ার বিষয়ে বলেছিলাম । ঈশ্বর তোমাকে আশীর্বাদ করবেন এবং আমাকে ঈশ্বর রক্ষা করার আদেশ দেবেন, আর তারপর আপনি তা করবেন । ফিরে যাও, তুমি সেই মহান লোকদের পেয়ে গেছো যারা বেঁচে যাবে বা চলে যাবে, তুমি তাকে আঘাত করার বা সাহস করার সিঁড়ি দিয়ে লাফ দিচ্ছ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَن ‏ ‏لَيْثٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الظُّهْرِ ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ مَكَانَكُمْ فَاسْتَقْبَلَ الرِّجَالَ فَقَالَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَأْمُرُنِي أَنْ آمُرَكُمْ أَنْ تَتَّقُوا اللَّهَ وَأَنْ تَقُولُوا قَوْلًا سَدِيدًا ثُمَّ تَخَطَّى الرِّجَالَ فَأَتَى النِّسَاءَ فَقَالَ إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَأْمُرُنِي أَنْ آمُرَكُنَّ أَنْ تَتَّقِينَ اللَّهَ عَزَّ وَجَلَّ وَأَنْ تَقُلْنَ قَوْلًا سَدِيدًا ثُمَّ رَجَعَ إِلَى الرِّجَالِ فَقَالَ إِذَا دَخَلْتُمْ مَسَاجِدَ الْمُسْلِمِينَ وَأَسْوَاقَهُمْ ‏ ‏أَوْ أَسْوَاقَ الْمُسْلِمِينَ وَمَسَاجِدَهُمْ ‏ ‏وَمَعَكُمْ مِنْ هَذِهِ النَّبْلِ شَيْءٌ فَأَمْسِكُوا ‏ ‏بِنُصُولِهَا ‏ ‏لَا تُصِيبُوا أَحَدًا مِنْ الْمُسْلِمِينَ فَتُؤْذُوهُ ‏ ‏أَوْ تَجْرَحُوهُ ‏","","",""],[18872,18872,"","বাবা, বাবা তো তোমার ব্যাপারে কথা বলতে চায়, আর বাবা তোমার ব্যাপারে কথা বলার চেষ্টা করছিল। ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সে নিজেকে আত্মসমর্পণ করেছে যদি আগুন থেকে তাকে পরিবর্তন করে দেয়। না সে না.","‏ ‏حَدَّثَنَا ‏ ‏أَبو أَحْمَدَ حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا غَيَّرَتْ النَّارُ لَوْنَهُ ‏","","",""],[18873,18873,"","বাবা আমার বাবাকে খুঁজে পাওয়ার চেষ্টা করার বিষয়ে আমার বাবার সঙ্গে কথা বলেছিলেন । যদি আমরা পরাজিত হতাম, কিন্তু আমরা হয়ত এটা তার কাজ থেকে মনে রাখতে পারতাম। লালটা বলে দেব আমরা আমার মাথা দিয়ে একটা অন্ত্যেষ্টিক্রিয়ার জন্য বসে আছি। তুমি যা বলবে তা করা হয়েছে, আমি ঈশ্বরের কাছে প্রার্থনা করব, যদি সে আমাকে দাফনের মাধ্যমে সেটা দিতে চায়, আমরা তার মজা করছি, ঈশ্বর একবার মানুষকে এমন একজন মানুষকে দিয়েছেন যে তার কাজ শেষ করে বই কিনে নিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَن ‏ ‏لَيْثٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِذَا مَرَّتْ بِكُمْ جِنَازَةٌ فَإِنْ كَانَ مُسْلِمًا أَوْ يَهُودِيًّا أَوْ نَصْرَانِيًّا فَقُومُوا لَهَا فَإِنَّهُ لَيْسَ لَهَا نَقُومُ وَلَكِنْ نَقُومُ لِمَنْ مَعَهَا مِنْ الْمَلَائِكَةِ ‏ ‏قَالَ ‏ ‏لَيْثٌ ‏ ‏فَذَكَرْتُ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏لِمُجَاهِدٍ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَخْبَرَةَ الْأَزْدِىُّ ‏ ‏قَالَ ‏ ‏إِنَّا لَجُلُوسٌ مَعَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏نَنْتَظِرُ جِنَازَةً إِذْ مَرَّتْ بِنَا أُخْرَى فَقُمْنَا فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏مَا يُقِيمُكُمْ فَقُلْنَا هَذَا مَا تَأْتُونَا بِهِ يَا ‏ ‏أَصْحَابَ مُحَمَّدٍ ‏ ‏قَالَ وَمَا ذَاكَ قُلْتُ زَعَمَ ‏ ‏أَبُو مُوسَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا مَرَّتْ بِكُمْ جِنَازَةٌ إِنْ كَانَ مُسْلِمًا أَوْ يَهُودِيًّا أَوْ نَصْرَانِيًّا فَقُومُوا لَهَا فَإِنَّهُ لَيْسَ لَهَا نَقُومُ وَلَكِنْ نَقُومُ لِمَنْ مَعَهَا مِنْ الْمَلَائِكَةِ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏مَا فَعَلَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطُّ غَيْرَ مَرَّةٍ بِرَجُلٍ مِنْ ‏ ‏الْيَهُودِ ‏ ‏وَكَانُوا ‏ ‏أَهْلَ كِتَابٍ ‏ ‏وَكَانَ يَتَشَبَّهُ بِهِمْ فَإِذَا نُهِيَ انْتَهَى فَمَا عَادَ لَهَا بَعْدُ ‏","","",""],[18874,18874,"","আমরা একটি ভাল হাত দিয়ে কথা বলেছি, এবং তারপর আমরা একটি মহান লর্ডের কাছে প্রার্থনা করব। ঈশ্বর তাঁর কাছে প্রার্থনা করলেন এবং তিনি ঈশ্বরের প্রভু এবং তাঁর পালনকর ্ তা শিক্ষা গ্রহণ করবেন শুনলাম, লর্ডের ইচ্ছা পূরণ করা হবে, এটাই তার ভবিষ্যদ্বাণী নয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ ثَنَا ‏ ‏بُرَيْدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏جَاءَ سَائِلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْفَعُوا ‏ ‏فَلْتُؤْجَرُوا وَلْيَقْضِ اللَّهُ عَلَى لِسَانِ نَبِيِّهِ مَا شَاءَ ‏","","",""],[18875,18875,"","আমরা একটা নির্দিষ্ট খারাপ সাথে কথা বলেছি, আর তারপর আমি আমার বাবাকে বিয়ে করতে পেরে খুশি হব, অথবা আমার বাবা ঈশ্বরের প্রতি সৎ থাকা তার পিপাসার দ্বারা উদ্ধার করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَ ثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏قَالَ ثَنَا ‏ ‏غَالِبٌ التَّمَّارُ ‏ ‏عَن ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَن ‏ ‏مَسْرُوقِ بْنِ أَوْسٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏قَضَى فِي الْأَصَابِعِ بِعَشْرٍ عَشْرٍ مِنْ الْإِبِلِ ‏","","",""],[18876,18876,"","বেনের পরের বার বাবা আমার কাছে ভালবাসা প্রকাশ করতে পারে, আমার বাবা লর্ডশিপের রহস্যের প্রতি আগ্রহী।","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَن ‏ ‏أَبِي بَلْجٍ ‏ ‏قَالَ حَدَّثَنَاهُ ‏ ‏أَبُو بَكْرِ بْنُ أَبِي مُوسَى الْأَشْعَرِيُّ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ الطَّاعُونَ فَقَالَ وَخْزٌ مِنْ أَعْدَائِكُمْ مِنْ الْجِنِّ وَهِيَ شَهَادَةُ الْمُسْلِمِ ‏","","",""],[18877,18877,"","আমরা দুটো উপায় নিয়ে ঝগড়ার কথা বলেছি, আর তারপর আমরা আমার ভাইয়ের জীবন নিয়ে বাপ্তাইজিত হয়েছি। আমার ছেলের রক্ত সেই গুরুতর অবস্থায় রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ ثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏هَارُونَ أَبِي إِسْحَاقَ الْكُوفِيِّ ‏ ‏مَنْ ‏ ‏هَمْدَانَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى فِي يَوْمٍ وَلَيْلَةٍ ثِنْتَيْ عَشَرَ رَكْعَةً سِوَى الْفَرِيضَةِ بُنِيَ لَهُ بَيْتٌ فِي الْجَنَّةِ ‏","","",""],[18878,18878,"","আমার বাবা একজন পলাতকের কাছ থেকে তার বাবাকে নিয়ে বাপ্তাইজিত হওয়ার ব্যাপারে কথা বলেছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏عَن ‏ ‏يُونُسَ بْنِ أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَن ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نِكَاحَ إِلَّا ‏ ‏بِوَلِيٍّ ‏","","",""],[18879,18879,"","ঈশ্বর তাকে আদেশ দিয়েছেন আর তারা আত্মসমর্পণ করবে, নতুবা স্ত্রী যখন এক শক্তি পার হয়ে যাবে, তখন তারা তেরীক হয়ে যাবে । তাকে অসীম অসীমভাবে খুঁজে বের করো।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏قَالَ ثَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ ‏ ‏عَن ‏ ‏غُنَيْمِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ اسْتَعْطَرَتْ فَمَرَّتْ بِقَوْمٍ لِيَجِدُوا رِيحَهَا فَهِيَ زَانِيَةٌ ‏","","",""],[18880,18880,"","আমরা দুজন সালমনের কথা বলেছি, \"আমাদের আমার কেঁচোকে ভালবাসি\" তিনি তার জন্য প্রার্থনা করেছেন এবং তিনি তাকে ছেড়ে দিবেন। আমি তাকে ভালবাসি এবং তার স্বামীও আছে। আমি ঠিক আছি, ঈশ্বর জিতে গেছে এবং তার টাকাও দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ ثَنَا ‏ ‏صَالِحُ بْنُ صَالِحٍ ‏ ‏عَن ‏ ‏الشَّعْبِيِّ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَتْ لَهُ ‏ ‏جَارِيَةٌ ‏ ‏فَأَدَّبَهَا فَأَحْسَنَ أَدَبَهَا وَعَلَّمَهَا فَأَحْسَنَ تَعْلِيمَهَا ثُمَّ أَعْتَقَهَا وَتَزَوَّجَهَا فَلَهُ أَجْرَانِ وَأَيُّمَا رَجُلٍ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏آمَنَ بِنَبِيِّهِ وَآمَنَ ‏ ‏بِمُحَمَّدٍ ‏ ‏فَلَهُ أَجْرَانِ وَأَيُّمَا عَبْدٍ مَمْلُوكٍ أَدَّى حَقَّ اللَّهِ عَزَّ وَجَلَّ عَلَيْهِ وَحَقَّ ‏ ‏مَوَالِيهِ ‏ ‏فَلَهُ أَجْرَانِ ‏","","",""],[18881,18881,"","বাবার এই ধরনের চিন্তা দেখে বাবার বিচার করা আমার বাবার বাবার অপরাধ নিয়ে আমি বেশ কয়েকবার কথা বলেছি। আমি দুঃখিত, আমার বাবার কাছে তার সাথে যে ভবিষ্যদ্বাণীর জন্য তিনি দায়ী ছিলেন তার বাবার জন্য আমি দুঃখিত। বাবা, এভাবে আঘাত করে ও নিজের ছেলেকে চুমু খায় ।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏أَبِي تَمِيمَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏ح ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏وَحَدَّثَنِي ‏ ‏الضَّحَّاكُ أَبُو الْعَلَاءِ ‏ ‏أَنَّهُ سَمِعَهُ مِنْ ‏ ‏أَبِي تَمِيمَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ الدَّهْرَ ضُيِّقَتْ عَلَيْهِ جَهَنَّمُ هَكَذَا وَقَبَضَ كَفَّهُ ‏","","",""],[18882,18882,"","আমি আমার বাবার ব্যাপারে বেশ কয়েকবার কথা বলেছি, যে ভুল লোক বলেছিল আর তাকে ছেলে হিসেবে বর্ণনা করেছি, এটা আমার বাবার মশার সন্তান যে তোমাকে নিজে নিজে নিজে নিজে করেছে। আমার গোপনীয়তা ছিল তাদের মধ্যে একজন যদি আমি কিছু একটা করতে পারতাম... ...যদি আমি লর্ড এবং লর্ডের সাথে দেখা করতে পারতাম। সে বলল, যদি আপনি আমার কাছে ফিরে আসেন তাহলে আমি মনে করি আপনি তার কাছে ফিরে আসবেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏أَبِي التَّيَّاحِ الضُّبَعِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏وَصَفَهُ كَانَ يَكُونُ مَعَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏أَبُو مُوسَى ‏ ‏إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏إِنَّكَ رَجُلٌ مِنْ أَهْلِ زَمَانِكَ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانَ أَحَدُهُمْ إِذَا أَصَابَهُ الشَّيْءُ مِنْ الْبَوْلِ ‏ ‏قَرَضَهُ ‏ ‏بِالْمَقَارِيضِ ‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى ‏ ‏دَمْثٍ ‏ ‏يَعْنِي مَكَانٍ لَيِّنٍ ‏ ‏فَبَالَ فِيهِ وَقَالَ إِذَا بَالَ أَحَدُكُمْ فَلْيَرْتَدْ لِبَوْلِهِ ‏","","",""],[18883,18883,"","আমরা আমার বাবার সাথে বেশ কয়েকবার কথা বলেছি আমার বাবার অনুগ্রহে সন্তুষ্ট হয়ে, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং মানুষের উৎসর্গের জন্য আশ্বস্ত করেছেন এই তিন বার এই অনুষ্ঠানটি চিহ্নিত করা হবে আমার হাতে পেপারটা নাও, তার ডান হাত নাও আর তার রক্ত নিয়ে নাও।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ ثَنَا ‏ ‏عَلِيُّ بْنُ عَلِيِّ بْنِ رِفَاعَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْرَضُ النَّاسُ يَوْمَ الْقِيَامَةِ ثَلَاثَ عَرَضَاتٍ فَأَمَّا عَرْضَتَانِ فَجِدَالٌ وَمَعَاذِيرُ وَأَمَّا الثَّالِثَةُ فَعِنْدَ ذَلِكَ تَطِيرُ الصُّحُفُ فِي الْأَيْدِي فَآخِذٌ بِيَمِينِهِ وَآخِذٌ بِشِمَالِهِ ‏","","",""],[18884,18884,"","আমি যখন তাকে বলেছিলাম যে, আমি যদি তার কাছে আসি, তা হলে আমি তাকে জিজ্ঞেস করি যে, কেন তিনি আমার ছেলেকে হত্যা করবেন । তোমাকে বলা হয়েছে যে তুমি অন্য বোতামে যাচ্ছ আর আমি আমার বাবা মুসার কথা বলছি, যেখানে আমরা মিথ্যা বলেছি. বাবা মুসা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ ثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَن ‏ ‏أَسِيدِ بْنِ أَبِي أَسِيدٍ ‏ ‏عَن ‏ ‏مُوسَى بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَيِّتُ يُعَذَّبُ بِبُكَاءِ الْحَيِّ عَلَيْهِ إِذَا قَالَتْ النَّائِحَةُ ‏ ‏وَاعَضُدَاهُ ‏ ‏وَانَاصِرَاهُ ‏ ‏وَاكَاسِبَاهُ ‏ ‏جُبِذَ ‏ ‏الْمَيِّتُ وَقِيلَ لَهُ أَنْتَ عَضُدُهَا أَنْتَ نَاصِرُهَا أَنْتَ كَاسِبُهَا فَقُلْتُ سُبْحَانَ اللَّهِ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَلَا ‏ ‏تَزِرُ ‏ ‏وَازِرَةٌ ‏ ‏وِزْرَ ‏ ‏أُخْرَى ‏} ‏فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏أُحَدِّثُكَ عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَقُولُ هَذَا فَأَيُّنَا كَذَبَ فَوَاللَّهِ مَا كَذَبْتُ عَلَى ‏ ‏أَبِي مُوسَى ‏ ‏وَلَا كَذَبَ ‏ ‏أَبُو مُوسَى ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18885,18885,"","আমি একটা ঘোড়া সম্বন্ধে বলেছিলাম, যে আমাকে ঈশ্বরের জীবন সম্বন্ধে বলতে চেয়েছিল । রাজা, আমি পৃথিবীর সবচাইতে বেশি হত্যা করছি তুমি যা বলবে তার চেয়ে বেশি। কেউ কেউ বলে যে সময় তার চাচার। আমি তাদের বেশি কিছু ভুলে যাচ্ছি, তোমার কথা ভুলে যাওয়া উচিত। আর তোমাকে ভুলে যাওয়া উচিত না। ওর কাছ থেকে বের হয়ে যাও, আমরা তাকে সবসময় টাকা দেই নি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ ‏ ‏الْهَرْجَ ‏ ‏قَالُوا وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ الْقَتْلُ قَالُوا أَكْثَرُ مِمَّا نَقْتُلُ إِنَّا لَنَقْتُلُ فِي الْعَامِ الْوَاحِدِ أَكْثَرَ مِنْ سَبْعِينَ أَلْفًا قَالَ إِنَّهُ لَيْسَ بِقَتْلِكُمْ الْمُشْرِكِينَ وَلَكِنْ قَتْلُ بَعْضِكُمْ بَعْضًا قَالُوا وَمَعَنَا عُقُولُنَا يَوْمَئِذٍ قَالَ إِنَّهُ لَيُنْزَعُ عُقُولُ أَكْثَرِ أَهْلِ ذَلِكَ الزَّمَانِ وَيُخَلَّفُ لَهُ ‏ ‏هَبَاءٌ ‏ ‏مِنْ النَّاسِ يَحْسَبُ أَكْثَرُهُمْ أَنَّهُ عَلَى شَيْءٍ وَلَيْسُوا عَلَى شَيْءٍ ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ مَا أَجِدُ لِي وَلَكُمْ مِنْهَا مَخْرَجًا إِنْ أَدْرَكَتْنِي وَإِيَّاكُمْ إِلَّا أَنْ نَخْرُجَ مِنْهَا كَمَا دَخَلْنَاهَا لَمْ نُصِبْ فِيهَا دَمًا وَلَا مَالًا ‏","","",""],[18886,18886,"","আমরা বধিরদের কথা বলেছিলাম যে আমার ছেলের দয়া দেখানোর পর, আমার বাবা বা বাবার ছেলে সম্পর্কে বিভ্রান্ত, যেমনটা সে বলেছিল, তার ভালোবাসা আগুনের ভেতর থেকে করা হয়েছে। কিন্তু, নিপীড়ন তার খেলাধুলায় ফল উৎপন্ন করেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ ثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَسِيدُ بْنُ أَبِي أَسِيدٍ ‏ ‏عَن ‏ ‏ابْنِ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَن ‏ ‏ابْنِ أَبِي قَتَادَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَرَّهُ أَنْ يُحَلِّقَ حَبِيبَتَهُ حَلْقَةً مِنْ نَارٍ فَلْيُحَلِّقْهَا حَلْقَةً مِنْ ذَهَبٍ وَمَنْ سَرَّهُ أَنْ يُسَوِّرَ حَبِيبَتَهُ سِوَارًا مِنْ نَارٍ فَلْيُسَوِّرْهَا سِوَارًا مِنْ ذَهَبٍ وَلَكِنْ الْفِضَّةُ فَالْعَبُوا بِهَا لَعِبًا ‏","","",""],[18887,18887,"","বাবার বাবার ঠাণ্ডার দুই দিন কথা বলেছি, আমার বাবাকে বলতে গিয়ে, সে জানে, সে নাকি ঈশ্বরের কাছে ভয় পায়, যে তোমাকে আমি তাদের আত্মাতে পরিণত করব।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِمْرَانُ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا خَافَ مِنْ رَجُلٍ ‏ ‏أَوْ مِنْ قَوْمٍ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ إِنِّي أَجْعَلُكَ فِي نُحُورِهِمْ وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ ‏","","",""],[18888,18888,"","আমরা ঈশ্বর সম্পর্কে কথা বলেছিলাম, \"আমরা আমার বাবার সাথে আমাকে ভালবাসতে চাই\" ঈশ্বরের দোহাই, ঈশ্বর এটা বলতে ভয় পাচ্ছেন। তাদের হৃদয় তাদের খারাপ থেকে রক্ষা করা উচিত।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ثَنَا ‏ ‏مُعَاذٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا خَافَ قَوْمًا قَالَ ‏ ‏اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ ‏","","",""],[18889,18889,"","আমরা এমন এক নির্দিষ্ট ছেলের কথা বলেছিলাম, যিনি বলেছিলেন যে, আমার বাবা হয়তো তার হাত হারিয়ে ফেলেছেন । তার জন্য আমি আদেশ পালন করি... ...যে তাদের সিনেমা কিনেছিল.","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو لَيْلَى عَبْدُ اللَّهِ بْنُ مَيْسَرَةَ ‏ ‏عَن ‏ ‏مَزِيدَةَ بْنِ جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أُمِّي ‏ ‏كُنْتُ فِي مَسْجِدِ ‏ ‏الْكُوفَةِ ‏ ‏فِي خِلَافَةِ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏وَعَلَيْنَا ‏ ‏أَبُو مُوسَى الْأَشْعَرِيُّ ‏ ‏قَالَ ‏ ‏فَسَمِعَتْهُ يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِصَوْمِ ‏ ‏عَاشُورَاءَ ‏ ‏فَصُومُوا ‏","","",""],[18890,18890,"","আমরা সবাই আমার বাবার সাথে কথা বলেছি যে আমার ছেলের ঘোড়া জয়ের চেষ্টা করছে। কবি বলেছিলেন, আমরা আমার বাবার দোহাই প্রার্থনা করেছি, তিনি আমাদের প্রার্থনা করেছেন। আমরা যদি তার অভাব বোধ করি, তাহলে আমরা তাকে ছেড়ে দেব ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَن ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَن ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَن ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏لَقَدْ صَلَّى بِنَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏صَلَاةً ذَكَّرَنَا بِهَا صَلَاةً كُنَّا ‏ ‏نُصَلِّيهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِمَّا أَنْ نَكُونَ نَسِينَاهَا وَإِمَّا أَنْ نَكُونَ تَرَكْنَاهَا عَمْدًا ‏ ‏يُكَبِّرُ فِي كُلِّ رَفْعٍ وَوَضْعٍ وَقِيَامٍ وَقُعُودٍ ‏","","",""],[18891,18891,"","আমরা ঈশ্বরের কথা বলেছিলাম, \"আমার বাবার ভালবাসার জন্য আমাদের একটা শট ছিল।\" ঈশ্বর আমাদের বলেছেন, ঈশ্বর আমাদের এটা দিতে এবং আত্মসমর্পণ করতে শিখিয়েছিলেন। তুমি বিশ্বাস করো না, বা এম-কে পড়।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَن ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏أَبِي غَلَّابٍ ‏ ‏عَن ‏ ‏حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏عَلَّمَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَلْيَؤُمَّكُمْ أَحَدُكُمْ وَإِذَا قَرَأَ الْإِمَامُ فَأَنْصِتُوا ‏","","",""],[18892,18892,"","আমরা সবাই ভালোর জন্য জন্মগ্রহণ করেছি. আমি বলতে চাচ্ছি সে খারাপ লোক, আর তারপর আমাদের বলতে হবে \"আমার ছেলে\" তার কিছু গোপন তথ্য তিনি বলেছেন যে তিনি মনে করেছিলেন আমরা ঈশ্বরের কাছে প্রার্থনা করতে চাই এবং তিনি তা করতে পারবেন না। আমি তাকে গুলি করব। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং ইচ্ছা প্রকাশ করেছেন। আমি তাকে যা বলবো, তার নির্দেশনায় আমরা তা মেনে চলব। সে বলেছিল, আমরা যুদ্ধ করতে চাই না, না। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আশ্বস্ত হয়েছেন যে আমি যেন তার কথা শুনি। যারা জীবনের আনন্দকে হারাত বা যারা জীবনের সবচেয়ে বেশি ক্ষতিগ্রস্ত তাদের জন্য এটা সম্ভবত সবচেয়ে বেশি কঠিন সম্ভবত, অধিকাংশ ক্ষেত্রে সম্ভবত তা হতে পারে সম্ভবত, অধিকাংশ ক্ষেত্রে সম্ভবত তা হতে পারে সম্ভবত, এটা সম্ভবত সবচেয়ে বেশি সম্ভাব্য হতে পারে । সম্ভবত, অধিকাংশ ক্ষেত্রে এটি সম্ভবত সবচেয়ে বেশি জনপ্রিয় হতে পারে সম্ভবত সম্ভবত এর মধ্যে সবচেয়ে বেশি সম্ভাবনা রয়েছে আমার মাকে স্বর্গে নিয়ে যাওয়ার প্রতিশ্রুতি দেওয়া। আর আমার ভাগ্যটা পরে নাও, আমার মার মৃত্যুর সাথে সাথে মজা করবে, ঈশ্বর আমাদের এমন ভাব করতে দিবেন যে সে আমাদের কথা বলবে, ঈশ্বর তাকে দিয়েছেন এবং বলেছেন, ঈশ্বর আমাদের ছেড়ে দিয়েছেন। তাদের বলতে হবে যে ঈশ্বর আদেশ দিয়েছেন আর তাকে উদ্ধার করা হবে, ঈশ্বর আমাদের তাকে যেতে সাহায্য করবেন, তাকে ছেড়ে দিতে সাহায্য করবেন। ঈশ্বর না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى يَعْنِي الْأَشْيَبَ ‏ ‏قَالَ ثَنَا ‏ ‏سُكَيْنُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَزِيدُ الْأَعْرَجُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏يَعْنِي أَظُنُّهُ ‏ ‏الشَّنِّيَّ ‏ ‏قَالَ ثَنَا ‏ ‏حَمْزَةُ بْنُ عَلِيِّ بْنِ مَخْفَرٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ قَالَ ‏ ‏فَعَرَّسَ ‏ ‏بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَانْتَهَيْتُ بَعْضَ اللَّيْلِ إِلَى ‏ ‏مُنَاخِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَطْلُبُهُ فَلَمْ أَجِدْهُ قَالَ فَخَرَجْتُ بَارِزًا أَطْلُبُهُ وَإِذَا رَجُلٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَطْلُبُ مَا أَطْلُبُ قَالَ فَبَيْنَا نَحْنُ كَذَلِكَ إِذْ اتَّجَهَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ أَنْتَ بِأَرْضِ حَرْبٍ وَلَا نَأْمَنُ عَلَيْكَ فَلَوْلَا إِذْ بَدَتْ لَكَ الْحَاجَةُ قُلْتَ لِبَعْضِ أَصْحَابِكَ فَقَامَ مَعَكَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي سَمِعْتُ ‏ ‏هَزِيزًا ‏ ‏كَهَزِيزِ ‏ ‏الرَّحَى ‏ ‏أَوْ حَنِينًا كَحَنِينِ النَّحْلِ ‏ ‏وَأَتَانِي آتٍ مِنْ رَبِّي عَزَّ وَجَلَّ قَالَ فَخَيَّرَنِي أَنْ يَدْخُلَ ‏ ‏شَطْرُ ‏ ‏أُمَّتِي الْجَنَّةَ وَبَيْنَ ‏ ‏شَفَاعَتِي ‏ ‏لَهُمْ فَاخْتَرْتُ ‏ ‏شَفَاعَتِي ‏ ‏لَهُمْ وَعَلِمْتُ أَنَّهَا أَوْسَعُ لَهُمْ فَخَيَّرَنِي بِأَنْ يَدْخُلَ ثُلُثُ أُمَّتِي الْجَنَّةَ وَبَيْنَ ‏ ‏الشَّفَاعَةِ ‏ ‏لَهُمْ فَاخْتَرْتُ لَهُمْ ‏ ‏شَفَاعَتِي ‏ ‏وَعَلِمْتُ أَنَّهَا أَوْسَعُ لَهُمْ فَقَالَا يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ تَعَالَى أَنْ يَجْعَلَنَا مِنْ أَهْلِ ‏ ‏شَفَاعَتِكَ ‏ ‏قَالَ فَدَعَا لَهُمَا ثُمَّ إِنَّهُمَا نَبَّهَا ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَخْبَرَاهُمْ بِقَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَجَعَلُوا يَأْتُونَهُ وَيَقُولُونَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ تَعَالَى أَنْ يَجْعَلَنَا مِنْ أَهْلِ ‏ ‏شَفَاعَتِكَ ‏ ‏فَيَدْعُوَ لَهُمْ قَالَ فَلَمَّا أَضَبَّ عَلَيْهِ الْقَوْمُ وَكَثُرُوا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا لِمَنْ مَاتَ وَهُوَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ ‏","","",""],[18893,18893,"","আমরা সাঁতারের কথা বলেছিলাম যার মানে আমার বাবা একটা ছেলেকে বলত যে সে কখনোই বাবা হবে না। আমি আমার হাত তুলে নেয়ার কবরে আছি, আমার বাবা আমাকে আর একটা উপায় এঁকেছে। তোমাকে হত্যা করতে হবে অথবা আমি বলছি যে আমি তোমাকে বলছি না। আমার বাবা ঈশ্বরের কাছে প্রার্থনা করেছে এবং তোমাদের কাছে আমার একটি পাঠ আছে। সেই ঘোড়াটা বলেছিল যে, তার নিজের ও তার হৃদয় যখন তাকে অবাক করে দিয়েছিল, তখন তিনি বলেছিলেন যে, আপনার সুরক্ষাকে তিনি অবাক হয়ে গিয়েছিলেন । অমর ছিলো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ يَعْنِي السَّالَحِينِيَّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏أَبِي سِنَانٍ ‏ ‏قَالَ ‏ ‏دَفَنْتُ ابْنًا لِي وَإِنِّي لَفِي الْقَبْرِ إِذْ أَخَذَ بِيَدَيَّ ‏ ‏أَبُو طَلْحَةَ ‏ ‏فَأَخْرَجَنِي فَقَالَ أَلَا أُبَشِّرُكَ قَالَ قُلْتُ بَلَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ تَعَالَى ‏ ‏يَا مَلَكَ الْمَوْتِ قَبَضْتَ وَلَدَ عَبْدِي قَبَضْتَ ‏ ‏قُرَّةَ ‏ ‏عَيْنِهِ وَثَمَرَةَ فُؤَادِهِ قَالَ نَعَمْ قَالَ فَمَا قَالَ قَالَ حَمِدَكَ وَاسْتَرْجَعَ قَالَ ابْنُوا لَهُ بَيْتًا فِي الْجَنَّةِ وَسَمُّوهُ بَيْتَ الْحَمْدِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏فَذَكَرَهُ إِلَّا أَنَّهُ قَالَ ‏ ‏أَبُو طَلْحَةَ الْخَوْلَانِيُّ ‏ ‏وَقَالَ ‏ ‏الضَّحَّاكُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَرْزَبٍ ‏","","",""],[18894,18894,"","আমরা হাত ভেঙ্গে হাত ভেঙ্গে বলতে চেষ্টা করলাম, \"আমরা কখনোই আমার বাবার জন্য কাদার অর্থ বোঝানি\" ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি একটি বার্তা দিয়েছেন যেখানে তিনি একজন প্রতিবেশী এবং তারপর তিনি তার পরে। প্রতিবেশীকে বিয়ে করা হয়।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ ثَنَا ‏ ‏خَالِدٌ يَعْنِي الطَّحَّانَ ‏ ‏عَن ‏ ‏مُطَرِّفٍ ‏ ‏عَن ‏ ‏عَامِرٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الَّذِي يُعْتِقُ ‏ ‏جَارِيَةً ‏ ‏ثُمَّ يَتَزَوَّجُهَا لَهُ أَجْرَانِ ‏","","",""],[18895,18895,"","আমরা দুদিন আগে কথা বলেছি, আমাদের লর্ডের ইচ্ছার বিরুদ্ধে সতর্ক থাকতে বলেছিলাম, আমি ঈশ্বরের কাছে প্রার্থনা করব আর সে বলবে প্রতিটি মাতাল একটা যুদ্ধ।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَرِيشُ بْنُ سُلَيْمٍ ‏ ‏قَالَ ثَنَا ‏ ‏طَلْحَةُ بْنُ مُصَرِّفٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[18896,18896,"","এরপর বাবা বলেছিলেন, \"তাহলে আমরা বাবার নামে ফিরে যাব, সে বলল, \"আমরা খুন করতে যাচ্ছি\"। তিনি চোরকে মুক্ত করেছিলেন এবং চুরি করা বন্ধ করে দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ ثَنَا ‏ ‏أَبِي ‏ ‏قَالَ ثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏قَالَ ثَنَا ‏ ‏عَاصِمُ بْنُ سُلَيْمَانَ ‏ ‏عَن ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏قَالَ قَالٍَ ‏ ‏أَبُو مُوسَى ‏ ‏إِنِّي بَرِيءٌ مِمَّنْ بَرِئَ اللَّهُ مِنْهُ وَرَسُولُهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَرِئَ مِمَّنْ ‏ ‏حَلَقَ ‏ ‏وَسَلَقَ ‏ ‏وَخَرَقَ ‏","","",""],[18897,18897,"","আমার বাবা ঈশ্বরের কাছে প্রার্থনা করার ব্যাপারে আগ্রহী ছিলেন এবং তিনি সেই বিষয়টা স্বীকার করতেন । সেই ব্যক্তি নিরাপদে আমাকে স্পর্শ করে এবং সেইসঙ্গে তাকে স্পর্শ করে এবং সেইসঙ্গে তিনি আমাদের স্পর্শ করেন । আমার ছেলে মারা গিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ ثَنَا ‏ ‏أَبِي ‏ ‏قَالَ ثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ ثَرْوَانَ ‏ ‏عَن ‏ ‏هُزَيْلِ بْنِ شُرَحْبِيلَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ فِيهَا مُؤْمِنًا وَيُمْسِي كَافِرًا ‏ ‏وَيُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا الْقَاعِدُ فِيهَا خَيْرٌ مِنْ الْقَائِمِ وَالْقَائِمُ فِيهَا خَيْرٌ مِنْ الْمَاشِي وَالْمَاشِي فِيهَا خَيْرٌ مِنْ السَّاعِي فَاكْسِرُوا ‏ ‏قِسِيَّكُمْ ‏ ‏وَقَطِّعُوا أَوْتَارَكُمْ وَاضْرِبُوا بِسُيُوفِكُمْ الْحِجَارَةَ فَإِنْ دُخِلَ عَلَى أَحَدِكُمْ بَيْتَهُ فَلْيَكُنْ كَخَيْرِ ابْنَيْ ‏ ‏آدَمَ ‏","","",""],[18898,18898,"","ঈশ্বরের কাছে আশীর্বাদ হল একজন যাজক, যিনি তার বাবার কাছে প্রার্থনা করেছিলেন এবং তিনি সেই মুক্তির মূল্য প্রদান করবেন । ফেয়ার দেবী, তাদের নিজেদের বংশধরদের কাছে যাচ্ছি, তারা হয়তো বড় হয়ে উঠতে চায় কাপুরুষের মতো একটা ডানাতে, আর এজন্যই তারা ভয় পাবে। আমি জানি, তারা আমাদের সাথে আছে। আমি কি? নিচে নামছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو قُدَامَةَ الْحَارِثُ بْنُ عُبَيْدٍ الْإِيَادِيُّ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو عِمْرَانَ يَعْنِي الْجَوْنِيَّ ‏ ‏عَن ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جِنَانُ ‏ ‏الْفِرْدَوْسِ أَرْبَعٌ ثِنْتَانِ مِنْ ذَهَبٍ حِلْيَتُهُمَا وَآنِيَتُهُمَا وَمَا فِيهِمَا وَثِنْتَانِ مِنْ فِضَّةٍ آنِيَتُهُمَا وَحِلْيَتُهُمَا وَمَا فِيهِمَا وَلَيْسَ بَيْنَ الْقَوْمِ وَبَيْنَ أَنْ يَنْظُرُوا إِلَى رَبِّهِمْ عَزَّ وَجَلَّ إِلَّا رِدَاءُ الْكِبْرِيَاءِ عَلَى وَجْهِهِ فِي جَنَّةِ عَدْنٍ وَهَذِهِ الْأَنْهَارُ ‏ ‏تَشْخَبُ ‏ ‏مِنْ جَنَّةِ عَدْنٍ ثُمَّ ‏ ‏تَصْدَعُ ‏ ‏بَعْدَ ذَلِكَ أَنْهَارًا ‏","","",""],[18899,18899,"","আমরা সেই বধিরদের কথা বলেছিলাম, আমরা আমার বাবার জেদ নিয়ে যে জেদের কথা বলেছিলাম, সে তার কথা বলেছি। হ্যারিকেন.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو دَارِسٍ ‏ ‏صَاحِبُ الْجَوْرِ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو بُرْدَةَ بْنُ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّهُ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ بَعْدَ الْعَصْرِ ‏","","",""],[18900,18900,"","আমরা বাবাকে বলেছিলাম যে সে পরের বার কষ্ট পাবে যখন সে বলেছিল সে একটা খারাপ ছেলে। তিনি তাকে জগতের সুবিধা সম্বন্ধে প্রশ্ন জিজ্ঞেস করেছিলেন । আমি যখন এগুলো পড়তাম, তখন আমার শরীর ও চোখের জল ভেসে যেত । তিনি যখন গরমের সময় কাছাকাছি ছিলেন, তখন তিনি তাকে স্পর্শ করা বন্ধ করে দিয়েছিলেন এবং শেষ সূর্যটি ছিল তৃতীয় বারের মতো । ভেঙ্গে গিয়েছে, সময় হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ ثَنَا ‏ ‏بَدْرُ بْنُ عُثْمَانَ ‏ ‏مَوْلًى لِآلِ ‏ ‏عُثْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي مُوسَى ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَأَتَاهُ سَائِلٌ يَسْأَلُهُ عَنْ مَوَاقِيتِ الصَّلَاةِ فَلَمْ يَرُدَّ عَلَيْهِ شَيْئًا ‏ ‏فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَقَامَ بِالْفَجْرِ حِينَ انْشَقَّ الْفَجْرُ وَالنَّاسُ لَا يَكَادُ يَعْرِفُ بَعْضُهُمْ بَعْضًا ثُمَّ أَمَرَهُ فَأَقَامَ بِالظُّهْرِ حِينَ ‏ ‏زَالَتْ ‏ ‏الشَّمْسُ وَالْقَائِلُ يَقُولُ انْتَصَفَ النَّهَارُ أَوْ لَمْ يَنْتَصِفْ وَكَانَ أَعْلَمَ مِنْهُمْ ثُمَّ أَمَرَهُ فَأَقَامَ بِالْعَصْرِ وَالشَّمْسُ مُرْتَفِعَةٌ ثُمَّ أَمَرَهُ فَأَقَامَ بِالْمَغْرِبِ حِينَ وَقَعَتْ الشَّمْسُ ثُمَّ أَمَرَهُ فَأَقَامَ بِالْعِشَاءِ حِينَ غَابَ ‏ ‏الشَّفَقُ ‏ ‏ثُمَّ أَخَّرَ الْفَجْرَ مِنْ الْغَدِ حَتَّى انْصَرَفَ مِنْهَا وَالْقَائِلُ يَقُولُ طَلَعَتْ الشَّمْسُ أَوْ كَادَتْ وَأَخَّرَ الظُّهْرَ حَتَّى كَانَ قَرِيبٌ مِنْ وَقْتِ الْعَصْرِ بِالْأَمْسِ ثُمَّ أَخَّرَ الْعَصْرَ حَتَّى انْصَرَفَ مِنْهَا وَالْقَائِلُ يَقُولُ احْمَرَّتْ الشَّمْسُ ثُمَّ أَخَّرَ الْمَغْرِبَ حَتَّى كَانَ عِنْدَ سُقُوطِ ‏ ‏الشَّفَقِ ‏ ‏وَأَخَّرَ الْعِشَاءَ حَتَّى كَانَ ثُلُثُ اللَّيْلِ الْأَوَّلُ فَدَعَا السَّائِلَ فَقَالَ الْوَقْتُ فِيمَا بَيْنَ هَذَيْنِ ‏","","",""],[18901,18901,"","আমরা প্রেমের বিষয়ে বলেছিলাম যে, তিনি যখন একটা সময়ে তার বাবার সঙ্গে কথা বলেছিলেন, তখন আমরা দুই ছেলে একটা ষাঁড় সম্বন্ধে কথা বলেছিলাম । ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি হতাশ হয়ে পড়বেন । তার মহিমা, লাঠিতে খুশি হও।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ ثَنَا ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏مَكْحُولٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عَائِشَةَ ‏ ‏وَكَانَ جَلِيسًا ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْعَاصِ ‏ ‏دَعَا ‏ ‏أَبَا مُوسَى الْأَشْعَرِيَّ ‏ ‏وَحُذَيْفَةَ بْنَ الْيَمَانِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏فَقَالَ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكَبِّرُ فِي الْفِطْرِ وَالْأَضْحَى فَقَالَ ‏ ‏أَبُو مُوسَى ‏ ‏كَانَ يُكَبِّرُ أَرْبَعَ تَكْبِيرَاتٍ تَكْبِيرَهُ عَلَى الْجَنَائِزِ وَصَدَّقَهُ ‏ ‏حُذَيْفَةُ ‏ ‏فَقَالَ ‏ ‏أَبُو عَائِشَةَ ‏ ‏فَمَا نَسِيتُ بَعْدُ قَوْلَهُ تَكْبِيرَهُ عَلَى الْجَنَائِزِ ‏ ‏وَأَبُو عَائِشَةَ ‏ ‏حَاضِرٌ ‏ ‏سَعِيدَ بْنَ الْعَاصِ ‏","","",""],[18902,18902,"","আমি আমার বাবা ও আমার মাসতুতোকে খননের বিষয়ে কথা বলেছিলাম । রাতের আলোতে আমি আমার ছেলের আনন্দ দিয়েছিলাম আমি তাকে আমার মায়ের মৃত্যু থেকে বের করে দিয়েছিলাম সে তোমাকে আর কিছু কিনে নেয়নি. সে তোমাকে আর কিছু কিনে নেয়নি. সে আমার বাবার সাথে কথা বলেছিল. ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيتُ خَمْسًا بُعِثْتُ إِلَى الْأَحْمَرِ وَالْأَسْوَدِ وَجُعِلَتْ لِي الْأَرْضُ طَهُورًا وَمَسْجِدًا وَأُحِلَّتْ لِي الْغَنَائِمُ وَلَمْ تُحَلَّ لِمَنْ كَانَ قَبْلِي وَنُصِرْتُ بِالرُّعْبِ شَهْرًا وَأُعْطِيتُ الشَّفَاعَةَ وَلَيْسَ مِنْ نَبِيٍّ إِلَّا وَقَدْ سَأَلَ شَفَاعَةً وَإِنِّي أَخْبَأْتُ شَفَاعَتِي ثُمَّ جَعَلْتُهَا لِمَنْ مَاتَ مِنْ أُمَّتِي لَمْ يُشْرِكْ بِاللَّهِ شَيْئًا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ يَعْنِي الزُّبَيْرِيَّ ‏ ‏قَالَ ثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَن ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ وَلَمْ يُسْنِدْهُ ‏","","",""],[18903,18903,"","আমরা একটা নিশ্চিত ছেলে, যে বাবার সাথে কথা বলেছিল, আমি তার কাছে প্রার্থনা করেছি আর তাকে উদ্ধার করা হবে আর সে তার মুখে থাকবে। হামাদ তার নীরবতাকে জাগিয়ে তুলেছিলেন এই বলে যে তিনি বাপ্তিস্ম নিয়েছেন এবং আমাদের কাছে বর্ণনা করেছেন যে তিনি লম্বা হবেন।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏غَيْلَانُ بْنُ جَرِيرٍ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَسْتَاكُ ‏ ‏وَهُوَ وَاضِعٌ طَرَفَ السِّوَاكِ عَلَى لِسَانِهِ يَسْتَنُّ إِلَى فَوْقَ ‏ ‏فَوَصَفَ ‏ ‏حَمَّادٌ ‏ ‏كَأَنَّهُ يَرْفَعُ سِوَاكَهُ قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَوَصَفَهُ لَنَا ‏ ‏غَيْلَانُ ‏ ‏قَالَ كَانَ يَسْتَنُّ طُولًا ‏","","",""],[18904,18904,"","বাবা আমার বাবার সাথে রাগে ফেটে পড়েছিলো। ঈশ্বর জানেন, আমি আমার পাপের জন্য ফোন করবো। আমার দাদা আমার জন্য ক্ষমা করবেন। তোমার সব দোষ আর আমার চাচার দোষ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ ثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو بِهَؤُلَاءِ الدَّعَوَاتِ ‏ ‏اللَّهُمَّ اغْفِرْ لِي خَطَايَايَ وَجَهْلِي وَإِسْرَافِي فِي أَمْرِي وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي اللَّهُمَّ اغْفِرْ لِي جَدِّي وَهَزْلِي وَخَطَئِي وَعَمْدِي كُلُّ ذَلِكَ عِنْدِي ‏","","",""],[18905,18905,"","আমরা একজন প্রভুর কথা বলেছি যে হয়ত আমার কান্নার কথা নিজের ভাইয়ের জীবন নিয়ে বলেছে, আমি ঈশ্বরের কাছে অনুরোধ করব, সে একটা উন্মাদ আর সে একটা বেশ্যার বাচ্চা, সে উষ্ণভাবে মারা যাবে। অথবা ঘোড়ার কাছ থেকে এমন কোনো রাজদণ্ড ছিল, যে তাকে হয়তো দেখেছিল যে, যে তাকে হত্যা করেছে, সে নিজেই তাকে হত্যা করেছে । এবং আছে.","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عَبْدِ اللَّهِ يَعْنِي الْبَكَّائِيَّ ‏ ‏قَالَ ثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَن ‏ ‏شَقِيقِ بْنِ سَلَمَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُنَكِّسٌ فَقَالَ يَا رَسُولَ اللَّهِ مَا الْقِتَالُ فِي سَبِيلِ اللَّهِ تَعَالَى فَإِنَّ أَحَدَنَا يُقَاتِلُ ‏ ‏حَمِيَّةً ‏ ‏وَيُقَاتِلُ غَضَبًا فَلَهُ أَجْرٌ قَالَ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ إِلَيْهِ وَلَوْلَا أَنَّهُ كَانَ قَائِمًا ‏ ‏أَوْ كَانَ قَاعِدًا الشَّكُّ مِنْ ‏ ‏زُهَيْرٍ ‏ ‏مَا رَفَعَ رَأْسَهُ إِلَيْهِ فَقَالَ ‏ ‏مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18906,18906,"","আমরা একটা মোসের কথা বলেছিলাম যে আমার বাবা আর তার প্রভু বলেছিলেন যে মানুষ মানুষ ঈশ্বরের অনুগ্রহে এসেছে, ঈশ্বর তাকে আর ঈশ্বর দিয়েছেন যা বলেছে যুদ্ধ করার পথে যুদ্ধ করতে। ঈশ্বর আমাদের একজনকে মারতে বলেছেন, একটা কাদা আর নোংরা কাদার জন্য, যদি সে না নিতে না পারে তাহলে তার মাথা গলিয়ে ফেলতে হবে। ঈশ্বরের দয়া।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ ثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ ثَنَا ‏ ‏مَنْصُورُ بْنُ الْمُعْتَمِرِ ‏ ‏عَن ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏سَأَلَ رَجُلٌ ‏ ‏أَوْ جَاءَ رَجُلٌ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ مُنَكِّسٌ رَأْسَهُ فَقَالَ مَا الْقِتَالُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ فَإِنَّ أَحَدَنَا يُقَاتِلُ ‏ ‏حَمِيَّةً ‏ ‏وَغَضَبًا فَلَهُ أَجْرٌ قَالَ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ إِلَيْهِ وَلَوْلَا أَنَّهُ كَانَ قَائِمًا ‏ ‏أَوْ كَانَ قَاعِدًا الشَّكُّ مِنْ ‏ ‏زُهَيْرٍ ‏ ‏مَا رَفَعَ رَأْسَهُ إِلَيْهِ فَقَالَ ‏ ‏مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18907,18907,"","আমরা যুদ্ধে কথা বলেছি, আর আমার একটা ছেলে আছে, যার কথা দেয়া হয়েছে। আমার বাবা আমার বিখ্যাত মানুষ। আমি যা বলেছি, আমি তা ছেড়ে দেব।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ ثَنَا ‏ ‏عُمَرُ بْنُ عَلِيِّ بْنِ مُقَدَّمٍ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو عُمَيْسٍ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏وَقَالَ ‏ ‏أَتَانِي نَاسٌ مِنْ ‏ ‏الْأَشْعَرِيِّينَ ‏ ‏فَقَالُوا اذْهَبْ مَعَنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّ لَنَا حَاجَةً قَالَ فَقُمْتُ مَعَهُمْ فَقَالُوا يَا رَسُولَ اللَّهِ اسْتَعِنْ بِنَا فِي عَمَلِكَ فَاعْتَذَرْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا قَالُوا وَقُلْتُ لَمْ أَدْرِ مَا حَاجَتُهُمْ فَصَدَّقَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَذَرَنِي وَقَالَ ‏ ‏إِنَّا لَا نَسْتَعِينُ فِي عَمَلِنَا مَنْ سَأَلَنَاهُ ‏","","",""],[18908,18908,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা আমার বাবাকে সাহায্য করতে করতে ক্লান্ত হয়ে গেছি... ...তার দাদাকে উদ্ধার করতে হবে আর মূসাকে উদ্ধার করতে হবে। তাদের আত্মার শপথ, তুমি বলতে চাচ্ছ মা, আমরা তার বাবাকে নিয়ে মজা করছি, সে যেভাবে বলে, সে যেভাবে বলে, তা থেকে মদ খাই। সে বলেছে, সে নাকি ভগবানকে বলে, আল্লাহ যেন এটা করতে বলে। সবাই ফ্রি মাতাল হয়ে আত্মসমর্পণ করে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا مُوسَى ‏ ‏وَمُعَاذَ بْنَ جَبَلٍ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ لَهُمَا ‏ ‏يَسِّرَا وَلَا تُعَسِّرَا وَبَشِّرَا وَلَا تُنَفِّرَا ‏ ‏وَتَطَاوَعَا ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏يَا رَسُولَ اللَّهِ إِنَّا بِأَرْضٍ يُصْنَعُ فِيهَا شَرَابٌ مِنْ الْعَسَلِ يُقَالُ لَهُ ‏ ‏الْبِتْعُ ‏ ‏وَشَرَابٌ مِنْ الشَّعِيرِ يُقَالُ لَهُ ‏ ‏الْمِزْرُ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[18909,18909,"","আমরা আবেগে বাপ্তাইজিত হয়েছি, তারপর একটা সময়ের জন্য একটা দাঙ্গা শুরু হল যখন মানুষ মারা যায়। আমি ভাবছিলাম যে আমরা এটা ছেড়ে দেব। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং ইচ্ছার জন্য প্রার্থনা করেছেন। আমার মায়ের কাছে অনুরোধ করেছেন, যেন তিনি আমাদের প্রভুর কাছে আমাদের কথা বলেন । খাবার তোমার শত্রুদের পাগলামির শত্রু করে দিয়েছে এবং আমাকে যে সমস্ত প্রচেষ্টা করতে হচ্ছে, তা থেকে আমাকে আদেশ করতে হবে । আমার বাবা তার সাথে কথা বলেছিলেন, আর তিনি বলেছিলেন যে সে অনেক ব্যস্ত, তোমার সম্মানার্থে ছেলে যে আমার ছেলের দশ বছরের মধ্যে বাইরে চলে গেছে, আর তারপর সে তা করেছে। ঈশ্বর দাবি করেছেন যে, ঈশ্বর দাবি করেছেন এবং আমার মায়ের শিল্প... ...তাকে স্মরণ করতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ قَوْمِي ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَدْ كُنْتُ أَحْفَظُ اسْمَهُ ‏ ‏قَالَ ‏ ‏كُنَّا عَلَى بَابِ ‏ ‏عُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏نَنْتَظِرُ الْإِذْنَ عَلَيْهِ فَسَمِعْتُ ‏ ‏أَبَا مُوسَى الْأَشْعَرِيَّ ‏ ‏يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَاءُ أُمَّتِي بِالطَّعْنِ وَالطَّاعُونِ قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ هَذَا الطَّعْنُ قَدْ عَرَفْنَاهُ فَمَا الطَّاعُونُ قَالَ ‏ ‏طَعْنُ ‏ ‏أَعْدَائِكُمْ مِنْ الْجِنِّ وَفِي كُلٍّ شَهَادَةٌ ‏ ‏قَالَ ‏ ‏زِيَادٌ ‏ ‏فَلَمْ أَرْضَ بِقَوْلِهِ فَسَأَلْتُ سَيِّدَ الْحَيِّ وَكَانَ مَعَهُمْ فَقَالَ ‏ ‏صَدَقَ حَدَّثَنَاهُ ‏ ‏أَبُو مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو بَكْرٍ النَّهْشَلِيُّ ‏ ‏قَالَ ثَنَا ‏ ‏زِيَادُ بْنُ عِلَاقَةَ ‏ ‏عَن ‏ ‏أُسَامَةَ بْنِ شَرِيكٍ ‏ ‏قَالَ ‏ ‏خَرَجْنَا فِي بِضْعَ عَشْرَةَ مِنْ ‏ ‏بَنِي ثَعْلَبَةَ ‏ ‏فَإِذَا نَحْنُ ‏ ‏بِأَبِي مُوسَى ‏ ‏فَإِذَا هُوَ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُمَّ اجْعَلْ فَنَاءَ أُمَّتِي فِي الطَّاعُونِ فَذَكَرَهُ ‏","","",""],[18910,18910,"","বাবার মৃত্যুর সময় আমার বাবার সাথে যুদ্ধ করার কথা বলেছিলাম, ঈশ্বর আমার বাবার মৃত্যু ফিরিয়ে দেবার জন্য একটা তলোয়ারে আত্মসমর্পণ করেছেন, যা ধ্বংস হয়ে গেছে এবং মানুষকে ঘৃণা করতে হুমকি দিয়েছে। নিজেকে শ্বাস নিন, এটাকে কখনোই বলবেন না, ঈশ্বর একজন যাজক হতে পারেন... ...আমি তোমাকে সব বলতে চাই না যে তুমি অপরাধী।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ ثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَن ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ قَالَ فَأَهْبَطَنَا ‏ ‏وَهْدَةً ‏ ‏مِنْ الْأَرْضِ قَالَ ‏ ‏فَرَفَعَ النَّاسُ أَصْوَاتَهُمْ بِالتَّكْبِيرِ فَقَالَ أَيُّهَا النَّاسُ ‏ ‏ارْبَعُوا ‏ ‏عَلَى أَنْفُسِكُمْ فَإِنَّكُمْ لَا تَدْعُونَ أَصَمَّ وَلَا غَائِبًا إِنَّكُمْ تَدْعُونَ سَمِيعًا قَرِيبًا قَالَ ثُمَّ دَعَانِي وَكُنْتُ مِنْهُ قَرِيبًا فَقَالَ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏أَلَا أَدُلُّكَ عَلَى كَلِمَةٍ مِنْ كَنْزِ الْجَنَّةِ قَالَ قُلْتُ بَلَى قَالَ لَا ‏ ‏حَوْلَ ‏ ‏وَلَا ‏ ‏قُوَّةَ ‏ ‏إِلَّا بِاللَّهِ ‏","","",""],[18911,18911,"","আমরা একজন মাত্র লোককে বলেছিলাম যে, সে আমার বাবা মোশির ব্যাপারে, সে আমার কাছে প্রার্থনা করলো, সে আমাকে চুদতে নিষেধ করলো না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ الْحَدَّادُ ‏ ‏قَالَ ثَنَا ‏ ‏يُونُسُ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا نِكَاحَ إِلَّا ‏ ‏بِوَلِيٍّ ‏","","",""],[18912,18912,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং বলেছিলেন যে, তিনি কিছু শুনেছেন অথবা শুনেছেন । ঈশ্বরের কাছে প্রার্থনা কর, যেন তিনি এক নারীকে সমর্পণ করেন, যিনি ব্যর্থতার মুখে পতিত হয়েছেন এবং এরপর ঈশ্বরের শক্তিতে চলে গিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏وَرَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَا ثَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ ‏ ‏عَن ‏ ‏غُنَيْمِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏غُنَيْمًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مُوسَى ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ اسْتَعْطَرَتْ ثُمَّ مَرَّتْ عَلَى الْقَوْمِ لِيَجِدُوا رِيحَهَا فَهِيَ زَانِيَةٌ ‏","","",""],[18913,18913,"","আমরা একটা কথা বলেছিলাম আর অন্যান্য বললো, \"আমরা আমার বাবার গান গাইবার জন্য লড়াই চালিয়েছি।\" ঈশ্বর তাকে শুনেছেন এবং তিনি আমাকে বলতে শুনেছেন তিনি আমাকে ঈশ্বরের কাছে গান গাইতে শুনেছেন। আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি যদি আমার বাবা মারা যায়, তাহলে সে আমার বাবা আমাকে ছেড়ে দিয়েছে। আর আমি তোমাকে বলেছিলাম, আমি তোমার সাথে নেই। চোখ","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا ثَنَا ‏ ‏ثَابِتُ بْنُ عُمَارَةَ ‏ ‏عَن ‏ ‏غُنَيْمِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏سَمِعْتُ ‏ ‏غُنَيْمًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ عَيْنٍ زَانِيَةٌ ‏","","",""],[18914,18914,"","আমরা বাবার রক্তের ব্যাপারে আমার বাবার বংশধরদের কথা বলেছি, আমি এটা ঈশ্বরের দোহাইর জন্য করবো আর আমি তাকে মারার সুযোগ দেব, ঈশ্বর তাকে আদেশ দিয়েছেন আর আত্মসমর্পণ করতে হবে আমি বলছি যে, ঈশ্বর ঈশ্বরের কাছে এসেছেন এবং আমি এমন নই যে আমিই সে-ই হতে পারি। আমরা এটা বহন করি, তারপর আমরা তা করেছি। আমি ঈশ্বরের নামে শপথ করে বলছি, তুমি সমাধান করেছ, ঈশ্বর আমাকে তাঁর থেকে ভালো দেখতে চান না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُلَيْمَانُ يَعْنِي التَّيْمِيَّ ‏ ‏عَن ‏ ‏أَبِي السَّلِيلِ ‏ ‏عَن ‏ ‏زَهْدَمٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَسْتَحْمِلُهُ ‏ ‏فَقَالَ لَا وَاللَّهِ لَا أَحْمِلُكُمْ فَلَمَّا رَجَعْنَا أَرْسَلَ إِلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِثَلَاثِ ‏ ‏ذَوْدٍ ‏ ‏بُقْعِ ‏ ‏الذُّرَى ‏ ‏قَالَ فَقُلْتُ حَلَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ لَا ‏ ‏يَحْمِلَنَا ‏ ‏ثُمَّ حَمَلَنَا فَأَتَيْنَاهُ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّكَ حَلَفْتَ أَنْ لَا تَحْمِلَنَا فَحَمَلْتَنَا فَقَالَ ‏ ‏لَمْ أَحْمِلْكُمْ وَلَكِنَّ اللَّهَ حَمَلَكُمْ وَاللَّهِ لَا أَحْلِفُ عَلَى يَمِينٍ فَأَرَى غَيْرَهَا خَيْرًا مِنْهَا إِلَّا أَتَيْتُهُ ‏ ‏أَبُو السَّلِيلِ ضُرَيْبُ بْنُ نُقَيْرٍ ‏","","",""],[18915,18915,"","আমি আমার বাবার সাথে কথা বলেছি, সে আমাকে খুন করবে বলে যে সে আমাকে খুন করবে। আমাকে এক সেকেন্ডের জন্য থাকতে বলা হয়েছে, কিন্তু আমি তাকে তুলে নিতে পারি নি। জিহ্বা, সে আমাকে বলল আল্লাহ তার জন্য প্রার্থনা করেছে আর বলবে যে, এই তিন বার কে জিতেছে আর তাকে হত্যা করেছে। এটা একটা বিল্ডিং, নাকি আমি এটাকে বসে ঈশ্বরের কাছে ডাকতে পারি। বানান.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونٍَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏دَاوُدُ ‏ ‏عَن ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَن ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبُو مُوسَى ‏ ‏عَلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَرَجَعَ فَلَقِيَهُ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَقَالَ مَا شَأْنُكَ رَجَعْتَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ اسْتَأْذَنَ ثَلَاثًا فَلَمْ يُؤْذَنْ لَهُ فَلْيَرْجِعْ ‏ ‏فَقَالَ ‏ ‏لَتَأْتِيَنَّ عَلَى هَذِهِ ‏ ‏بِبَيِّنَةٍ ‏ ‏أَوْ لَأَفْعَلَنَّ وَلَأَفْعَلَنَّ ‏ ‏فَأَتَى مَجْلِسَ قَوْمِهِ ‏ ‏فَنَاشَدَهُمْ ‏ ‏اللَّهَ تَعَالَى فَقُلْتُ أَنَا مَعَكَ فَشَهِدُوا لَهُ فَخَلَّى سَبِيلَهُ ‏","","",""],[18916,18916,"","আমরা আমাদের কাছে অনেক কিছু করেছি, আমাদের বলা হয়েছে যে আমরা আমার বাবার চেয়ে ভাল শাসন করতে পারব... ...তার জীবনের সবচেয়ে বেশি কিছু করতে পারব। খুন করতে চায়, সে বলেছে তার বন্ধুকে মারতে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا الْمُسْلِمَانِ تَوَاجَهَا بِسَيْفَيْهِمَا فَقَتَلَ أَحَدُهُمَا صَاحِبَهُ فَهُمَا فِي النَّارِ قِيلَ يَا رَسُولَ اللَّهِ هَذَا الْقَاتِلُ مَا بَالُ الْمَقْتُولِ قَالَ إِنَّهُ أَرَادَ قَتْلَ صَاحِبِهِ ‏","","",""],[18917,18917,"","আমি আমার বাবাকে তার দাদার কাছ থেকে সাহায্য করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏جَدِّهِ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أُمَّتِي أُمَّةٌ مَرْحُومَةٌ لَيْسَ عَلَيْهَا فِي الْآخِرَةِ عَذَابٌ إِلَّا عَذَابُهَا فِي الدُّنْيَا الْقَتْلُ وَالْبَلَاءُ وَالزَّلَازِلُ ‏","","",""],[18918,18918,"","সে শুনলো যে বাবা আমার বাবার মাউস পরে আছে আর বলেছে সে নাকি তার পোশাক পরা অবস্থায় আছে নিজের কাপড়, গোপন রাখা ছিল এই বলে যে আমার বাবা একজন ঠান্ডা ঠান্ডা ছিল যখন তিনি বলেছিলেন যে তিনি এটা শুনেছেন. আমি বলতে চাচ্ছি, এমন একটা ছেলে যে ঈশ্বরকে লিখতে শুরু করেছে, সে ঠিক তা করেনি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونٍَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْعَوَّامُ ‏ ‏وَمُحَمَّدُ بْنُ يَزِيدَ ‏ ‏الْمَعْنَى ‏ ‏قَالَ ثَنَا ‏ ‏الْعَوَّامُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ إِسْمَاعِيلَ السَّكْسَكِيُّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا بُرْدَةَ بْنَ أَبِي مُوسَى ‏ ‏وَهُوَ يَقُولُ ‏ ‏لِيَزِيدَ بْنِ أَبِي كَبْشَةَ ‏ ‏وَاصْطَحَبَا فِي سَفَرٍ فَكَانَ ‏ ‏يَزِيدُ ‏ ‏يَصُومُ فِي السَّفَرِ فَقَالَ لَهُ ‏ ‏أَبُو بُرْدَةَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا مُوسَى ‏ ‏مِرَارًا ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْعَبْدَ الْمُسْلِمَ إِذَا مَرِضَ أَوْ سَافَرَ كُتِبَ لَهُ مِنْ الْأَجْرِ كَمَا كَانَ يَعْمَلُ مُقِيمًا صَحِيحًا ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ يَزِيدَ ‏ ‏كَتَبَ اللَّهُ مِثْلَ مَا كَانَ يَعْمَلُ مُقِيمًا صَحِيحًا ‏","","",""],[18919,18919,"","ঈশ্বর তা দূর করে দেবেন এবং আমি গৌরব বা গৌরবের সঙ্গে আপনার দৃঢ়সংকল্পকে রক্ষা করব । তার ফোন একটু বেশিই হয়ে যায়, আমার বাবা একজন মাউস আর আমাদের কাউকে কিছু টাকা দিতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا مَرَّ أَحَدُكُمْ بِسُوقٍ أَوْ مَجْلِسٍ أَوْ مَسْجِدٍ وَمَعَهُ نَبْلٌ فَلْيَقْبِضْ عَلَى ‏ ‏نِصَالِهَا ‏ ‏فَلْيَقْبِضْ عَلَى ‏ ‏نِصَالِهَا ‏ ‏ثَلَاثًا ‏ ‏قَالَ ‏ ‏أَبُو مُوسَى ‏ ‏فَمَا زَالَ بِنَا الْبَلَاءُ حَتَّى ‏ ‏سَدَّدَ ‏ ‏بِهَا بَعْضُنَا فِي وُجُوهِ بَعْضٍ ‏","","",""],[18920,18920,"","বাবা আমাকে আমার ঈশ্বর যিহোবার কাছে আমার বাবার কাছে এই কথা বলেছিলেন । তার হাত দিয়ে সে তার কথা অনুযায়ী... ...যে মানুষদের কাছে প্রার্থনা করছে... আমি যে - কবর থেকে এসেছি, তা থেকে তিনি আমাকে বলেছিলেন, তিনি কোনো কিছু না বলে বরং কোনো শক্তি অথবা ক্ষমতাই লাভ করেননি ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَن ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ فَأَسْرَعْنَا ‏ ‏الْأَوْبَةَ ‏ ‏وَأَحْسَنَّا الْغَنِيمَةَ فَلَمَّا ‏ ‏أَشْرَفْنَا ‏ ‏عَلَى ‏ ‏الرُّزْدَاقِ ‏ ‏جَعَلَ الرَّجُلُ مِنَّا يُكَبِّرُ ‏ ‏قَالَ حَسِبْتُهُ قَالَ بِأَعْلَى صَوْتِهِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّهَا النَّاسُ وَجَعَل يَقُولُ بِيَدِهِ هَكَذَا ‏ ‏وَوَصَفَ ‏ ‏يَزِيدُ ‏ ‏كَأَنَّهُ يُشِيرُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّهَا النَّاسُ ‏ ‏إِنَّكُمْ لَا تُنَادُونَ أَصَمَّ وَلَا غَائِبًا إِنَّ الَّذِي تُنَادُونَ دُونَ رُءُوسِ رِكَابِكُمْ ثُمَّ قَالَ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏أَوْ يَا ‏ ‏أَبَا مُوسَى ‏ ‏أَلَا أَدُلُّكَ عَلَى كَلِمَةٍ مِنْ كُنُوزِ الْجَنَّةِ قُلْتُ بَلَى يَا رَسُولَ اللَّهِ قَالَ قُلْ لَا ‏ ‏حَوْلَ ‏ ‏وَلَا ‏ ‏قُوَّةَ ‏ ‏إِلَّا بِاللَّهِ ‏","","",""],[18921,18921,"","আমার বাবা আমাকে এমন একজন ব্যক্তির কথা বলতে বলেছিলেন, যিনি তা করবেন বলে ঈশ্বর শিক্ষা দিয়েছেন । তিনি আমাকে পরিত্যাগ না করার জন্য এই বিষয়টা সাক্ষ্য দেবেন এবং তাকে হত্যা করবেন এবং তিনি কার কাছে পাপ করেছেন, তা তিনি জানেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏حِطَّانَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ لِرَجُلٍ ‏ ‏هَلُمَّ ‏ ‏فَلْنَجْعَلْ يَوْمَنَا هَذَا لِلَّهِ عَزَّ وَجَلَّ فَوَاللَّهِ لَكَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَاهِدٌ هَذَا الْيَوْمَ فَخَطَبَ فَقَالَ ‏ ‏وَمِنْهُمْ مَنْ يَقُولُ ‏ ‏هَلُمَّ ‏ ‏فَلَنَجْعَلْ يَوْمَنَا هَذَا لِلَّهِ عَزَّ وَجَلَّ فَمَا زَالَ يَقُولُهَا حَتَّى تَمَنَّيْتُ أَنَّ الْأَرْضَ ‏ ‏سَاخَتْ ‏ ‏بِي ‏","","",""],[18922,18922,"","আমরা আমার বাবার একজন যাজকের সাথে কথা বলেছিলাম, সে বলত এটা লর্ডের অগ্নির যোদ্ধা, যেটা প্রতিবেশীদের দেখা যায়.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَن ‏ ‏غُنَيْمِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ هَذَا الْقَلْبَ كَرِيشَةٍ ‏ ‏بِفَلَاةٍ ‏ ‏مِنْ الْأَرْضِ يُقِيمُهَا الرِّيحُ ظَهْرًا لِبَطْنٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏","","",""],[18923,18923,"","আমরা যদি সাক্ষ্য দিই এবং আমাদের ছেলেদের সঙ্গে আছি, তা হলে আমরা ঈশ্বরের কাছে প্রার্থনা করছি । এরপর আমরা আত্মসমর্পণ করব, পশমের মত।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ ثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَ ‏ ‏أَبُو بُرْدَةَ بْنُ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ أَبِي ‏ ‏لَوْ شَهِدْتَنَا وَنَحْنُ مَعَ نَبِيِّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَصَابَتْنَا السَّمَاءُ حَسِبْتَ أَنَّ رِيحَنَا رِيحُ الضَّأْنِ إِنَّمَا لِبَاسُنَا الصُّوفُ ‏","","",""],[18924,18924,"","আমরা আমার বাবা জন্মগ্রহণ করেন সম্পর্কে কথা বলেছি এবং আমাকে বলতে চাই যে তিনি একজন যাজক নন। যদি তিনি আমাদের প্রভুর বার্তাবাহকের সাথে বাস করতে দেখেন, তাহলে তিনি তাকে উদ্ধার করতে পারতেন এবং আমরা চলে যেতাম। বাল।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏أَبُو مُوسَى ‏ ‏يَا بُنَيَّ ‏ ‏لَوْ رَأَيْتَنَا وَنَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصَابَنَا الْمَطَرُ وَجَدْتَ مِنَّا رِيحَ الضَّأْنِ ‏","","",""],[18925,18925,"","আমরা আমার বাবা একটু কামনার কথা বলেছিলাম। শহরের বাইরে থেকে সে পৃথিবীকে ছেড়ে চলে গেছে আর তার ১০০ বছরের মধ্যে, এটাই আমার পায়ের উপর দিয়ে বাধা সৃষ্টি করে। খোদা, সে আমাদের উদ্ধার করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ ثَنَا ‏ ‏ثَابِتٌ ‏ ‏قَالَ ثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَن ‏ ‏أَبِي مِجْلَزٍ ‏ ‏قَالَ ‏ ‏صَلَّى ‏ ‏أَبُو مُوسَى ‏ ‏بِأَصْحَابِهِ وَهُوَ مُرْتَحِلٌ مِنْ ‏ ‏مَكَّةَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَصَلَّى الْعِشَاءَ رَكْعَتَيْنِ وَسَلَّمَ ثُمَّ قَامَ فَقَرَأَ مِائَةَ آيَةٍ مِنْ سُورَةِ ‏ ‏النِّسَاءِ ‏ ‏فِي رَكْعَةٍ فَأُنْكِرَ ذَلِكَ عَلَيْهِ فَقَالَ مَا ‏ ‏أَلَوْتُ ‏ ‏أَنْ أَضَعَ قَدَمَيَّ حَيْثُ وَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدَمَهُ وَأَنْ أَصْنَعَ مِثْلَ مَا صَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18926,18926,"","আমরা বধিরদের কথা বলেছি এবং বলতে গেলাম, \"তাহলে আমরা পরের বার বাবা আমাকে থামিয়েছি\" বাবা, ক্যাম্পটি আকাশের একটি শুকনো সীমা যা কিনা পৃথিবীর প্রত্যেক প্রান্তে লম্বা হবে। সে বলল যে আমরা ঘুরে গিয়ে তার সাথে শেষ কথা বলব। আমার বাবা যা বানিয়েছে, গুহাগুলো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏قَالَ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏عَن ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ الْأَشْعَرِيِّ ‏ ‏أَخْبَرَهُ عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَيْمَةُ ‏ ‏دُرَّةٌ ‏ ‏مُجَوَّفَةٌ طُولُهَا فِي السَّمَاءِ سِتُّونَ مِيلًا فِي كُلِّ زَاوِيَةٍ أَهْلٌ لِلْمُؤْمِنِ لَا يَرَاهُمْ الْآخَرُونَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ ثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَذَكَر نَحْوَهُ ‏ ‏آخِرُ حَدِيثِ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏وَهُوَ آخِرُ مُسْنَدِ ‏ ‏الْكُوفِيِّينَ ‏","","",""],[18927,18927,"","আমরা ঈশ্বরের সেরাটার ব্যাপারে কথা বলেছি, কিন্তু ঈশ্বর একজন ভালো ছেলে, আমার বাবার গর্ভে আছে আমার শান্তি জয়ের জন্য। আমি আপনাকে পদত্যাগ করতে বলছি না। ঈশ্বর তাকে ফেলে দিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏شَكَّ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏فِي الْحَوْضِ فَأَرْسَلَ إِلَى ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏فَأَتَاهُ فَقَالَ لَهُ جُلَسَاءُ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏إِنَّمَا أَرْسَلَ إِلَيْكَ الْأَمِيرُ لِيَسْأَلَكَ ‏ ‏عَنْ الْحَوْضِ هَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ شَيْئًا قَالَ نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُهُ فَمَنْ كَذَّبَ بِهِ فَلَا سَقَاهُ اللَّهُ مِنْهُ ‏","","",""],[18928,18928,"","আমরা আমার ছেলের এই আতঙ্কের কথা বলেছি যে, বাবার আশীর্বাদের জন্য ঈশ্বর প্রার্থনা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏سَيَّارٍ أَبِي الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏بِالسِّتِّينَ إِلَى الْمِائَةِ ‏","","",""],[18929,18929,"","আমার ছেলে বাবার সঙ্গে কথা বলেছিলাম, যিনি ছিলেন আমার বাবা ।","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي ‏ ‏الْغَدَاةِ ‏ ‏بِالْمِائَةِ إِلَى السِّتِّينَ وَالسِّتِّينَ إِلَى الْمِائَةِ ‏","","",""],[18930,18930,"","তিনি বলেছিলেন যে, ঈশ্বর যে - দুর্দশার জন্য প্রার্থনা করেছেন, তা ঈশ্বর দূর করেছেন । আমরা মরণশীল অথবা ঈশ্বর আপনার মঙ্গল করুক আর আপনি যুদ্ধ করতে যাচ্ছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏رَاحِلَةٌ ‏ ‏أَوْ نَاقَةٌ أَوْ بَعِيرٌ ‏ ‏عَلَيْهَا بَعْضُ مَتَاعِ الْقَوْمِ وَعَلَيْهَا ‏ ‏جَارِيَةٌ ‏ ‏فَأَخَذُوا بَيْنَ جَبَلَيْنِ فَتَضَايَقَ بِهِمْ الطَّرِيقُ فَأَبْصَرَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏حَلْ ‏ ‏حَلْ ‏ ‏اللَّهُمَّ الْعَنْهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَاحِبُ هَذِهِ ‏ ‏الْجَارِيَةِ ‏ ‏لَا تَصْحَبُنَا ‏ ‏رَاحِلَةٌ ‏ ‏أَوْ نَاقَةٌ أَوْ بَعِيرٌ ‏ ‏عَلَيْهَا مِنْ لَعْنَةِ اللَّهِ تَبَارَكَ وَتَعَالَى ‏","","",""],[18931,18931,"","বাবা বলেছিলেন যে, ঈশ্বর কীভাবে তার জন্য প্রার্থনা করেছিলেন এবং তিনি তাকে প্রথম ফোন করেছিলেন । আমরা জানি যে, আমরা যদি তাঁর অবস্থান ও অবস্থানের প্রতি সম্মান দেখাই, তা হলে আমরা তাঁকে অনুকরণ করতে পারব । সে ছয়শ এর মধ্যে পড়া শুরু করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْمِنْهَالِ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ مَعَ أَبِي إِلَى ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏فَقَالَ لَهُ أَبِي حَدِّثْنَا كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَكْتُوبَةَ قَالَ كَانَ ‏ ‏يُصَلِّي ‏ ‏الْهَجِيرَ ‏ ‏وَهِيَ الَّتِي تَدْعُونَهَا الْأُولَى حِينَ ‏ ‏تَدْحَضُ ‏ ‏الشَّمْسُ وَيُصَلِّي الْعَصْرَ وَيَرْجِعُ أَحَدُنَا إِلَى رَحْلِهِ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَالشَّمْسُ حَيَّةٌ ‏ ‏قَالَ وَنَسِيتُ مَا قَالَ فِي الْمَغْرِبِ ‏ ‏وَكَانَ يَسْتَحِبُّ أَنْ يُؤَخِّرَ الْعِشَاءَ وَكَانَ يَكْرَهُ النَّوْمَ قَبْلَهَا وَالْحَدِيثَ بَعْدَهَا وَكَانَ يَنْفَتِلُ مِنْ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏حِينَ يَعْرِفُ أَحَدُنَا جَلِيسَهُ وَكَانَ يَقْرَأُ بِالسِّتِّينَ إِلَى الْمِائَةِ ‏","","",""],[18932,18932,"","আমরা সুখী এবং ভাল কথা বলেছি, \"আমাদের বাবার বিজয়ী হওয়ার কথা শুনতে হবে\" ঈশ্বর আমাকে কিছু বলতে শিখিয়েছিলেন তাকে বলার উপায়টা নষ্ট করে দেয়ার জন্য। শিখতে","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَا ثَنَا ‏ ‏أَبَانُ بْنُ صَمْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَازِعِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي شَيْئًا أَنْتَفِعُ بِهِ قَالَ ‏ ‏اعْزِلْ الْأَذَى عَنْ طَرِيقِ الْمُسْلِمِينَ ‏","","",""],[18933,18933,"","আমরা ঈশ্বরের দোহাই দিয়ে কথা বলেছি, বাবাকে ভালবাসতে বাধ্য করা হচ্ছে। ঈশ্বর তাকে এটা প্রদান করতে বলেছেন যে, রাজ্য হল এমন এক রাষ্ট্র, যা তাঁর চেয়ে তিনি কত বড় ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏أَنْبَأَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ الْوَاسِطِيِّ ‏ ‏عَنْ ‏ ‏رُفَيْعٍ أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِآخِرَةٍ إِذَا طَالَ الْمَجْلِسُ فَقَامَ قَالَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ فَقَالَ لَهُ بَعْضُنَا إِنَّ هَذَا قَوْلٌ مَا كُنَّا نَسْمَعُهُ مِنْكَ فِيمَا ‏ ‏خَلَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا ‏ ‏كَفَّارَةُ ‏ ‏مَا يَكُونُ فِي الْمَجْلِسِ ‏","","",""],[18934,18934,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...আমরা একজন যাজকের সাথে দেখা করতে গিয়ে... ...যে বলেছে যে সে স্যুট পরে আছে, একটা নদী তার হাতে দিয়ে তৈরি হয়েছে আর আমার ফোনটা ভালুকের মত করে তারা বলে যে সে প্রার্থনা করে কিভাবে তার কথা শোনে যে আমি আমার অভ্যাসে ফিরে যাচ্ছি, আমার বাবা এসে আমার স্নায়ুগুলো নিয়ে এসেছে লাথি মেরে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَزْرَقِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو بَرْزَةَ ‏ ‏بِالْأَهْوَازِ ‏ ‏عَلَى ‏ ‏جَرْفِ ‏ ‏نَهْرٍ وَقَدْ جَعَلَ ‏ ‏اللِّجَامَ ‏ ‏فِي يَدِهِ وَجَعَلَ ‏ ‏يُصَلِّي فَجَعَلَتْ الدَّابَّةُ ‏ ‏تَنْكُصُ ‏ ‏وَجَعَلَ يَتَأَخَّرُ مَعَهَا فَجَعَلَ رَجُلٌ مِنْ ‏ ‏الْخَوَارِجِ ‏ ‏يَقُولُ اللَّهُمَّ اخْزِ هَذَا الشَّيْخَ كَيْفَ ‏ ‏يُصَلِّي فَلَمَّا صَلَّى قَالَ قَدْ سَمِعْتُ مَقَالَتَكُمْ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتًّا ‏ ‏أَوْ سَبْعًا أَوْ ثَمَانِيًا ‏ ‏فَشَهِدْتُ أَمْرَهُ وَتَيْسِيرَهُ فَكَانَ رُجُوعِي مَعَ دَابَّتِي أَهْوَنَ عَلَيَّ مِنْ تَرْكِهَا فَتَنْزِعُ إِلَى ‏ ‏مَأْلَفِهَا ‏ ‏فَيَشُقُّ عَلَيَّ وَصَلَّى ‏ ‏أَبُو بَرْزَةَ ‏ ‏الْعَصْرَ رَكْعَتَيْنِ ‏","","",""],[18935,18935,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেন যেন তিনি একজন মানুষকে দেবতাদের কাছে পৌঁছে দেন । যদি আমি ঈশ্বরকে না পেয়ে বা এটা করতে ব্যর্থ হই, তারা তোমার কারণে করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرٌ أَبُو الْوَازِعِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏يَقُولُ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا إِلَى حَيٍّ مِنْ أَحْيَاءِ ‏ ‏الْعَرَبِ ‏ ‏فَضَرَبُوهُ وَسَبُّوهُ فَرَجَعَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَكَا ذَلِكَ إِلَيْهِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَهْلَ ‏ ‏عُمَانَ ‏ ‏أَتَيْتَ مَا ضَرَبُوكَ وَلَا سَبُّوكَ ‏","","",""],[18936,18936,"","আমি জানি না ভাববাদী তার কাছে প্রার্থনা করেছিলেন আর তিনি স্বপ্ন দেখেন যে তুমি প্রেমে পড়ছ কিনা। আর এই ভুলটা হল পথভ্র । স্ত্রী।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏لَا أَعْلَمُهُ إِلَّا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِمَّا أَخْشَى عَلَيْكُمْ شَهَوَاتِ ‏ ‏الْغَيِّ ‏ ‏فِي بُطُونِكُمْ وَفُرُوجِكُمْ وَمُضِلَّاتِ الْفِتَنِ ‏","","",""],[18937,18937,"","আমরা তার ব্যাপারে কথা বলেছি, সে আমাদের বাবার ব্যাপারে বলেছে, সে বলবে... ...আমি তোমার ইটের উপর তোমার ভালোবাসা আছে আর তোমার মুখ ভুল বলছে.","‏ ‏حَدَّثَنَاه ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِمَّا أَخْشَى عَلَيْكُمْ شَهَوَاتِ ‏ ‏الْغَيِّ ‏ ‏فِي بُطُونِكُمْ وَفُرُوجِكُمْ وَمُضِلَّاتِ الْهَوَى ‏","","",""],[18938,18938,"","তিনি বলেছিলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর কাছে আমি তার কাছে প্রার্থনা করব এবং তার জন্য তিনি যেন তা করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ أَبِي بَرْزَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا مَا أَنَا قُلْتُهُ وَلَكِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَهُ ‏","","",""],[18939,18939,"","আমার বাবা তার প্রতিবেশীদের নিয়ে তর্ক করেছেন, তার কিছু অনুসন্ধানে শোনার পর আমার বাবা স্বস্তি পেয়েছিলেন। অথবা অন্ধভাবে লর্ডকে বিরক্ত করে, আর সে একটা রূপকথা বানায়।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏جَارِهِمْ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمَيْدَ بْنَ هِلَالٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبْغَضَ النَّاسِ ‏ ‏أَوْ أَبْغَضَ الْأَحْيَاءِ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَقِيفُ ‏ ‏وَبَنُو حَنِيفَةَ ‏","","",""],[18940,18940,"","আমরা একজন সমকামীর কথা বলেছিলাম বাবা বিগ বয় বলে যে আমার সাথে শান্তি স্থাপন করার জন্য... ...ঈশ্বর আদেশ দিয়েছেন যে ঈশ্বর তাকে আদেশ দিয়েছেন আর প্রভুর কাছে আত্মসমর্পণ করবে. জেদী আর তারা তাদের পথ অনুসরণ করে না, তার বাসায় ব্যাখ্যা করে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ شَاذَانُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَبْدِ اللَّهِ بْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ ‏ ‏مَنْ آمَنَ بِلِسَانِهِ وَلَمْ يَدْخُلْ الْإِيمَانُ قَلْبَهُ لَا تَغْتَابُوا الْمُسْلِمِينَ وَلَا تَتَّبِعُوا عَوْرَاتِهِمْ فَإِنَّهُ مَنْ يَتَّبِعْ عَوْرَاتِهِمْ يَتَّبِعْ اللَّهُ عَوْرَتَهُ وَمَنْ يَتَّبِعْ اللَّهُ عَوْرَتَهُ يَفْضَحْهُ فِي بَيْتِهِ ‏","","",""],[18941,18941,"","আমরা দুটো উপায় নিয়ে কথা বলেছি... ...আমাদের সময় হয়েছে ছুরি খুঁজতে... ...আমরা একটা সিনেমা শুনতে যাচ্ছি... ...নাকি সে থামবে নাকি সে থামবে. তারা বেঁচে থাকবে আর দেখবে, তাদের কাছ থেকে তারা এটা করেছে ঈশ্বরের দোহাই আর অনুগত আর লোকদের সাথে আমি মিলিত হয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏سُكَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏سَيَّارُ بْنُ سَلَامَةَ ‏ ‏سَمِعَ ‏ ‏أَبَا بَرْزَةَ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَئِمَّةُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِذَا اسْتُرْحِمُوا رَحِمُوا وَإِذَا عَاهَدُوا وَفَوْا وَإِذَا حَكَمُوا عَدَلُوا فَمَنْ لَمْ يَفْعَلْ ذَلِكَ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[18942,18942,"","আমরা দুই দিনের কথা বলেছি যখন আমরা প্রমান করতে পেরেছি যে আমি বাধ্য হয়েছি, ঈশ্বরের জন্য একটি জয়ের জন্য প্রার্থনা করছি এবং একটি উপহার হিসেবে তা প্রদান করা হবে। তার জন্য মর্গে গিয়ে তাকে হত্যা করা হয়েছে। ঈশ্বর, আমরা দুই ছেলে ও ঈশ্বরকে হারিয়েছি। তাকে সাহায্য করার জন্য তিনি তাকে সাহায্য করেছিলেন, যাতে ঈশ্বর তাকে সাহায্য না করেন, তাকে তার কাছে হাত দিতে হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏كِنَانَةَ بْنِ نُعَيْمٍ الْعَدَوِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي مَغْزًى لَهُ فَلَمَّا فَرَغَ مِنْ الْقِتَالِ قَالَ ‏ ‏هَلْ تَفْقِدُونَ مِنْ أَحَدٍ قَالَ فَقَالُوا يَا رَسُولَ اللَّهِ نَفْقِدُ فُلَانًا وَفُلَانًا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ أَفْقِدُ ‏ ‏جُلَيْبِيبًا ‏ ‏فَالْتَمِسُوهُ فَالْتَمَسُوهُ فَوَجَدُوهُ عِنْدَ سَبْعَةٍ قَدْ قَتَلَهُمْ ثُمَّ قَتَلُوهُ فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ عَلَيْهِ فَقَالَ قَتَلَ سَبْعَةً ثُمَّ قَتَلُوهُ هَذَا مِنِّي وَأَنَا مِنْهُ قَتَلَ سَبْعَةً وَقَتَلُوهُ هَذَا مِنِّي وَأَنَا مِنْهُ فَرُفِعَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعَهُ عَلَى سَاعِدِهِ فَمَا كَانَ لَهُ سَرِيرٌ إِلَّا سَاعِدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى دَفَنَهُ وَمَا ذَكَرَ غُسْلًا ‏","","",""],[18943,18943,"","আমার ভাইয়ের সুনাম খেলার জন্য ক্লান্ত হয়ে পড়ে, সে একটি ঘোড়ার সাথে থেকে বের হয়, যে রেগে ছিল আর সে আমার মনে হয় আমি যে বেঁচে আছি তা বলতে সে খুবই বিরক্তিকর। আমি জীবিত না হওয়া পর্যন্ত, আল্লাহ তার শান্তি বজায় রেখেছে এবং তারা বলেছে যে আপনার মাস্টার এমন একজনকে ফোন করছে যে ঈশ্বরের কথা শুনেছে। সে বলে যে মিথ্যা কথা বলছে, ঈশ্বর যুদ্ধ করবে। তুমি তার কাছ থেকে এসেছ.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مِهْزَمٍ الْعَبْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي طَالُوتَ الْعَبْدِي ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏وَخَرَجَ مِنْ عِنْدِ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زِيَادٍ ‏ ‏وَهُوَ مُغْضَبٌ فَقَالَ مَا كُنْتُ أَظُنُّ أَنِّي أَعِيشُ حَتَّى أُخَلَّفُ فِي قَوْمٍ يُعَيِّرُونِي بِصُحْبَةِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا إِنَّ ‏ ‏مُحَمَّدِيَّكُمْ ‏ ‏هَذَا ‏ ‏لَدَحْدَاحٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي الْحَوْضِ ‏ ‏فَمَنْ كَذَّبَ فَلَا سَقَاهُ اللَّهُ تَبَارَكَ وَتَعَالَى مِنْهُ ‏","","",""],[18944,18944,"","আমরা ঈশ্বরের কথা বলেছিলাম এবং তার কথা শুনলাম। আমার বাবা দু'টো উপায়ের শিকার। আমি তাকে বা তাকে যেভাবে বলি, আমরা ঈশ্বরের বার্তাবাহকের সাথে ছিলাম, আর তাকে শপথ করে দেয়া হবে... ...যে গান গায়... ...সে আমার হৃদয়ের ক্ষতি করবে না, সে লর্ডকে হত্যা করবে না। সে বলেছে তারা দু'টো শব্দ আর বলেছে। ঈশ্বর এটা আমাদের দিয়েছেন, চলো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ الْأَحْوَصِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏رَبُّ هَذِهِ الدَّارِ ‏ ‏أَبُو هِلَالٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَسَمِعَ ‏ ‏رَجُلَيْنِ ‏ ‏يَتَغَنَّيَانِ وَأَحَدُهُمَا يُجِيبُ الْآخَرَ وَهُوَ يَقُولُ ‏ ‏لَا يَزَالُ ‏ ‏حَوَارِيَّ ‏ ‏تَلُوحُ عِظَامُهُ ‏ ‏زَوَى ‏ ‏الْحَرْبَ ‏ ‏عَنْهُ أَنْ يُجَنَّ فَيُقْبَرَا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْظُرُوا مَنْ هُمَا قَالَ فَقَالُوا فُلَانٌ وَفُلَانٌ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ ‏ ‏ارْكُسْهُمَا ‏ ‏رَكْسًا ‏ ‏وَدُعَّهُمَا إِلَى النَّارِ دَعًّا ‏","","",""],[18945,18945,"","আমরা আমার বাবার জন্মের কথা বলেছিলাম, আল্লাহ আছে আর সে ডিনারের আগে ঘুমাতে যাচ্ছে আর সে কথা বলতে চায় না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَكْرَهُ النَّوْمَ قَبْلَ الْعِشَاءِ وَلَا يُحِبُّ الْحَدِيثَ بَعْدَهَا ‏","","",""],[18946,18946,"","আমাদের আলোচনা হচ্ছে কিন্তু আমাদের সম্পর্কে সবচেয়ে ভালো বিষয় হচ্ছে আমার বাবা একজন আশীর্বাদ এবং আমার কানে তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন। তারা কিছু করেছে। তারা যা করেছে তার থেকেও বেশি কিছু, তারা চলে গিয়ে তোমাকে দেখে ফেলবে, ঈশ্বর আর মানুষ একত্র হয়ে আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُكَيْنُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏حَدَّثَنَا ‏ ‏سَيَّارُ بْنُ سَلَامَةَ أَبُو الْمِنْهَالِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ أَبِي عَلَى ‏ ‏أَبِي بَرْزَةَ ‏ ‏وَإِنَّ فِي أُذُنَيَّ يَوْمَئِذٍ ‏ ‏لَقُرْطَيْنِ ‏ ‏وَإِنِّي غُلَامٌ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأُمَرَاءُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏ثَلَاثًا مَا فَعَلُوا ثَلَاثًا مَا حَكَمُوا فَعَدَلُوا وَاسْتُرْحِمُوا فَرَحِمُوا وَعَاهَدُوا فَوَفَوْا فَمَنْ لَمْ يَفْعَلْ ذَلِكَ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[18947,18947,"","আমরা একটা স্বপ্নের ব্যাপারে কথা বলেছি... ...আমি একজন ক্রেতাকে বলেছিলাম... আমি যে ভয় দেখাতে চাচ্ছি, তার সাহস থেকে বিরতিতে বাবা, আমরা এমন কিছু শুনেছি যা সে ঈশ্বরের কাছ থেকে শুনতে পেয়েছে। দ্যা গাওয়ার তোমার সাথে কথা বলবে, আমার কাছে দেওয়া আছে, তার একজন লোক আছে যে কিনা অনুভব করছে তার তৃতীয় শিকার হবে... ...তারা তার মুখের সামনে শান্তি পাবে, আর সে কিছু দেবে, তারপর আমি নেব আমি কখনও তার নিজের হাত থেকে, বিভাগ থেকে, আমি ঈশ্বরকে নিজের হাতে পরিণত করার চেষ্টা করছি এবং তাকে আবার উদ্ধার করার চেষ্টা করছি. আপনি আমাকে বলবেন সে চলে গিয়েছে. তুমি দেখতে পাচ্ছ ধূসরের স্টক কিভাবে আর তার হাত দেয়া হবে না। একজনকে দেখতে হচ্ছে তাদের মরতে দেখা, সে বলেছে হামাদ তার কাছে ফিরে আসবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَزْرَقُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَتَمَنَّى أَنْ أَلْقَى رَجُلًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُنِي عَنْ ‏ ‏الْخَوَارِجِ ‏ ‏فَلَقِيتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏فِي يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فِي نَفَرٍ مِنْ أَصْحَابِهِ فَقُلْتُ يَا ‏ ‏أَبَا بَرْزَةَ ‏ ‏حَدِّثْنَا بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُهُ فِي ‏ ‏الْخَوَارِجِ ‏ ‏فَقَالَ أُحَدِّثُكَ بِمَا سَمِعَتْ أُذُنَيَّ وَرَأَتْ عَيْنَايَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِدَنَانِيرَ فَكَانَ يَقْسِمُهَا وَعِنْدَهُ ‏ ‏رَجُلٌ أَسْوَدُ ‏ ‏مَطْمُومُ ‏ ‏الشَّعْرِ عَلَيْهِ ثَوْبَانِ أَبْيَضَانِ بَيْنَ عَيْنَيْهِ ‏ ‏أَثَرُ ‏ ‏السُّجُودِ فَتَعَرَّضَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَاهُ مِنْ قِبَلِ وَجْهِهِ فَلَمْ يُعْطِهِ شَيْئًا ثُمَّ أَتَاهُ مِنْ خَلْفِهِ فَلَمْ يُعْطِهِ شَيْئًا فَقَالَ وَاللَّهِ يَا ‏ ‏مُحَمَّدُ ‏ ‏مَا عَدَلْتَ مُنْذُ الْيَوْمَ فِي الْقِسْمَةِ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَضَبًا شَدِيدًا ثُمَّ قَالَ وَاللَّهِ لَا تَجِدُونَ بَعْدِي أَحَدًا أَعْدَلَ عَلَيْكُمْ مِنِّي قَالَهَا ثَلَاثًا ثُمَّ قَالَ يَخْرُجُ مِنْ قِبَلِ الْمَشْرِقِ ‏ ‏رِجَالٌ كَانَ هَذَا مِنْهُمْ هَدْيُهُمْ هَكَذَا يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏لَا يَرْجِعُونَ إِلَيْهِ وَوَضَعَ يَدَهُ عَلَى صَدْرِهِ سِيمَاهُمْ ‏ ‏التَّحْلِيقُ ‏ ‏لَا يَزَالُونَ يَخْرُجُونَ حَتَّى يَخْرُجَ آخِرُهُمْ فَإِذَا رَأَيْتُمُوهُمْ فَاقْتُلُوهُمْ قَالَهَا ثَلَاثًا شَرُّ الْخَلْقِ وَالْخَلِيقَةِ قَالَهَا ثَلَاثًا ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏لَا يَرْجِعُونَ فِيهِ ‏","","",""],[18948,18948,"","আমি আমার মনের মধ্যে দিয়ে যাচ্ছি, আমি একজন লেখক, তিনি আপনাকে একই কাজ করতে দিয়েছেন, ঈশ্বর তা করেছেন, প্রয়োজন নেই বা না বলার জন্য। ঈশ্বর এতে উপস্থিত হন এবং তাকে উদ্ধার করতে বলেন। তিনি বলেছিলেন, তিনি ঈশ্বরকে জানতেন এবং ঈশ্বরকে ঘৃণা করতেন এবং বলতে চেয়েছিলেন যে আমি তাকে ভুলে যেতে চাই না। ঈশ্বর বলেছেন, ঈশ্বর বলেছেন ঈশ্বর বলেছেন ঈশ্বর বলেছেন, ঈশ্বর বলেছেন, ঈশ্বর বলেছেন, ঈশ্বর বলেছেন, এটা সত্য। আর আমি যদি তাঁর উদ্দেশ্য পূরণ করতে চাই না, তাহলে আমি তাঁর উদ্দেশ্য পূরণ করতে চাই। আর আমি যা চাই তা হল, আমি চাই না। আমি চাই না। আমি যদি চাই, আমি শুধু চাই যে, তা হলে আমি শুধু চাই, আমি শুধু চাই, আমি শুধু চাই। আর আমি শুধু আমার বাবা-মাগোতে চাই। আর আমি যেন আমি চাই যে, আমি শুধু চাই যে, আমি শুধু আমার বাবা-মা-মা আমাদের কাছে ফিরে যাই। আর আমি শুধু বিশ্বাস করি, আমি যেন আমি জানি যে, আমি জানি, আমি জানি যে, আমি জানি না, আমি জানি, আমি জানি, আমি যেন তুমি জানো, আমি আমার মা আমাদের মন ও আমার মা আমাদের মন পরিবর্তন করতে পারি। আর আমি যা করতে পারি। তাকে আর তার মা থ্রেডে বেঁধে রাখতে আদেশ দেয়া হয়েছে। আমাকে বলতে হবে, সে এটা ব্যর্থ করতে চায় না। তার ছেলে তোমাকে বিয়ে করতে দেবে না, যখন সে তাকে পরাজিত করতে চায়। তার মা তাকে বলেছে যে সে তার বাবার সাথে আটকে থাকতে চাচ্ছে। তাকে বলা হয়েছে, তিনি কোন একটাতে তার প্রার্থনার জন্য কখনো সাহায্য করেছেন। বিয়ে করে তিনি বলেছিলেন যে, তাকে করতে হবে । আমি দুই-তিন বার ঈশ্বরের কাছে পৌঁছে দেবো, তাকে সাহায্য করতে হবে, ঈশ্বরের কাছে প্রার্থনা করতে হবে, তাকে উদ্ধার করতে হবে এবং তারপর তা রাখতে হবে। তার পরের জায়গায় এবং তিনি তাকে মনে রাখবেন তিনি ভেসে চলে গেছেন। আমি আমার বাবার আঙ্গুল হারিয়ে ফেলছেন এবং তিনি জয়ী হওয়ার চেষ্টা করছেন। ঈশ্বর আদেশ দিয়েছেন এবং তিনি তাদের কাছে আত্মসমর্পণ করেছেন। ভালো যে তার সাথে এমন করেছে, ঋণের কারণে দুঃখিত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏كِنَانَةَ بْنِ نُعَيْمٍ الْعَدَوِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏أَنَّ ‏ ‏جُلَيْبِيبًا ‏ ‏كَانَ امْرَأً يَدْخُلُ عَلَى النِّسَاءِ يَمُرُّ بِهِنَّ وَيُلَاعِبُهُنَّ فَقُلْتُ لِامْرَأَتِي لَا يَدْخُلَنَّ عَلَيْكُمْ ‏ ‏جُلَيْبِيبٌ ‏ ‏فَإِنَّهُ إِنْ دَخَلَ عَلَيْكُمْ لَأَفْعَلَنَّ وَلَأَفْعَلَنَّ قَالَ وَكَانَتْ ‏ ‏الْأَنْصَارُ ‏ ‏إِذَا كَانَ لِأَحَدِهِمْ ‏ ‏أَيِّمٌ ‏ ‏لَمْ يُزَوِّجْهَا حَتَّى يَعْلَمَ هَلْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا حَاجَةٌ أَمْ لَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِرَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏زَوِّجْنِي ابْنَتَكَ فَقَالَ ‏ ‏نِعِمَّ وَكَرَامَةٌ يَا رَسُولَ اللَّهِ وَنُعْمَ عَيْنِي فَقَالَ إِنِّي لَسْتُ أُرِيدُهَا لِنَفْسِي قَالَ فَلِمَنْ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏لِجُلَيْبِيبٍ ‏ ‏قَالَ فَقَالَ يَا رَسُولَ اللَّهِ أُشَاوِرُ أُمَّهَا فَأَتَى أُمَّهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ ابْنَتَكِ فَقَالَتْ ‏ ‏نِعِمَّ وَنُعْمَةُ عَيْنِي فَقَالَ إِنَّهُ لَيْسَ يَخْطُبُهَا لِنَفْسِهِ إِنَّمَا يَخْطُبُهَا ‏ ‏لِجُلَيْبِيبٍ ‏ ‏فَقَالَتْ ‏ ‏أَجُلَيْبِيبٌ ‏ ‏ابْنَهْ ‏ ‏أَجُلَيْبِيبٌ ‏ ‏ابْنَهْ ‏ ‏أَجُلَيْبِيبٌ ‏ ‏ابْنَهْ ‏ ‏لَا لَعَمْرُ اللَّهِ لَا تُزَوَّجُهُ فَلَمَّا أَرَادَ أَنْ يَقُومَ لِيَأْتِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُخْبِرَهُ بِمَا قَالَتْ أُمُّهَا قَالَتْ ‏ ‏الْجَارِيَةُ ‏ ‏مَنْ خَطَبَنِي إِلَيْكُمْ فَأَخْبَرَتْهَا أُمُّهَا فَقَالَتْ أَتَرُدُّونَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْرَهُ ادْفَعُونِي فَإِنَّهُ لَمْ يُضَيِّعْنِي فَانْطَلَقَ أَبُوهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ قَالَ شَأْنَكَ بِهَا فَزَوَّجَهَا ‏ ‏جُلَيْبِيبًا ‏ ‏قَالَ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ لَهُ قَالَ فَلَمَّا ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَيْهِ قَالَ لِأَصْحَابِهِ هَلْ تَفْقِدُونَ مِنْ أَحَدٍ قَالُوا نَفْقِدُ فُلَانًا وَنَفْقِدُ فُلَانًا قَالَ انْظُرُوا هَلْ تَفْقِدُونَ مِنْ أَحَدٍ قَالُوا لَا قَالَ لَكِنِّي أَفْقِدُ ‏ ‏جُلَيْبِيبًا ‏ ‏قَالَ فَاطْلُبُوهُ فِي الْقَتْلَى قَالَ فَطَلَبُوهُ فَوَجَدُوهُ إِلَى جَنْبِ سَبْعَةٍ قَدْ قَتَلَهُمْ ثُمَّ قَتَلُوهُ فَقَالُوا يَا رَسُولَ اللَّهِ هَا هُوَ ذَا إِلَى جَنْبِ سَبْعَةٍ قَدْ قَتَلَهُمْ ثُمَّ قَتَلُوهُ فَأَتَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ عَلَيْهِ فَقَالَ قَتَلَ سَبْعَةً وَقَتَلُوهُ هَذَا مِنِّي وَأَنَا مِنْهُ هَذَا مِنِّي وَأَنَا مِنْهُ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏ثُمَّ وَضَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى سَاعِدَيْهِ وَحُفِرَ لَهُ مَا لَهُ سَرِيرٌ إِلَّا سَاعِدَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ وَضَعَهُ فِي قَبْرِهِ وَلَمْ يُذْكَرْ أَنَّهُ غَسَّلَهُ ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏فَمَا كَانَ فِي ‏ ‏الْأَنْصَارِ ‏ ‏أَيِّمٌ ‏ ‏أَنْفَقَ مِنْهَا ‏ ‏وَحَدَّثَ ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏ثَابِتًا ‏ ‏قَالَ ‏ ‏هَلْ تَعْلَمْ مَا دَعَا لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُمَّ صُبَّ عَلَيْهَا الْخَيْرَ صَبًّا وَلَا تَجْعَلْ عَيْشَهَا كَدًّا كَدًّا ‏ ‏قَالَ ‏ ‏فَمَا كَانَ فِي ‏ ‏الْأَنْصَارِ ‏ ‏أَيِّمٌ ‏ ‏أَنْفَقَ مِنْهَا ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏مَا حَدَّثَ بِهِ فِي الدُّنْيَا أَحَدٌ إِلَّا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏مَا أَحْسَنَهُ مِنْ حَدِيثٍ ‏","","",""],[18949,18949,"","আমরা আমাদের সব কাজ ভাল করে শেষ করেছি. আমি তার জন্য ঈশ্বরের কাছে জিতব আর তাকে বলতে চাই যে আমি ঈশ্বরের কাছে বলতে চাই যে তার কাছে বলতে হবে যে, সে একটা মই আছে. আপনি বলুন. আপনি যান. আপনি যান. আমরা ভাল ভাল ভাল ভাল ভাল কাজ করেছি. আমি তাকে বলতে. আমি তাকে বলতে. আমি তাকে বলতে হবে. আমি বলতে হবে যে তার জন্য আপনি ভাল কিছু আছে. আমি কি. আমি আপনার জন্য. আমি তাকে বলতে হবে. আমি তাকে বলতে হবে. আমি বলতে হবে. আমি বলতে যে তার জন্য একটি সিঁড়ি আছে. আপনি ভাল. আপনি ভাল. আপনি ভাল. আমি কি. আপনি ভাল. আপনি ভাল. আপনি ভাল. আমি ভাল. আমি ভাল. আমি ভাল. আমি কি. আমি ভাল. আমি তাকে বলতে পারেন. আমি তাকে বলতে. আর মুখ বন্ধ রাখো, আমাকে কথা বলো আমি তোমার ব্যাপারে যা করি, আর আমি তোমার ব্যাপারে ভুলে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ شُعَيْبِ بْنِ الْحَبْحَابِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْوَازِعِ ‏ ‏جَابِرًا الرَّاسِبِيَّ ‏ ‏ذَكَرَ أَنَّ ‏ ‏أَبَا بَرْزَةَ ‏ ‏حَدَّثَهُ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي لَا أَدْرِي لَعَسَى أَنْ تَمْضِيَ وَأَبْقَى بَعْدَكَ فَحَدِّثْنِي بِشَيْءٍ يَنْفَعُنِي اللَّهُ بِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏افْعَلْ كَذَا افْعَلْ كَذَا ‏ ‏أَنَا نَسِيتُ ذَلِكَ ‏ ‏وَأَمِزْ ‏ ‏الْأَذَى عَنْ الطَّرِيقِ ‏","","",""],[18950,18950,"","আমরা আমার বাবা, বাবা, তার অন্ত্যেষ্টিক্রিয়ার ব্যাপারে কথা বলেছি, আর তিনি চলে গেছেন, ঈশ্বরের কাছে আছে এবং আমি এটাকে একটা স্বপ্ন দেব যে তিনি এটা করতে চান, আমি আমার বাবাকে নিয়ে নিয়েছি। আমি তাকে আমার হাতকে জানিয়ে দেব ঈশ্বর তাকে বললেন এবং তিনি তাকে শিক্ষা দিয়েছেন। তার ছেলে তাদের উপহার দেয় আর বলে যে তুমি তিন বার তার জন্য উপহার, শান্তির প্রভু বললেন আমার বাবা আশীর্বাদ করেছেন আর তারপর বন্য জীবনে ফিরে আসেন \"শান্তির দেবতা\"","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عُيَيْنَةُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْتُ يَوْمًا أَمْشِي فَإِذَا بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَوَجِّهًا فَظَنَنْتُهُ يُرِيدُ حَاجَةً فَجَعَلْتُ ‏ ‏أَخْنَسُ ‏ ‏عَنْهُ وَأُعَارِضُهُ فَرَآنِي فَأَشَارَ إِلَيَّ فَأَتَيْتُهُ فَأَخَذَ بِيَدِي فَانْطَلَقْنَا نَمْشِي جَمِيعًا فَإِذَا نَحْنُ بِرَجُلٍ ‏ ‏يُصَلِّي يُكْثِرُ الرُّكُوعَ وَالسُّجُودَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُرَاهُ ‏ ‏مُرَائِيًا ‏ ‏فَقُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ فَأَرْسَلَ يَدِي ثُمَّ طَبَّقَ بَيْنَ كَفَّيْهِ فَجَمَعَهُمَا وَجَعَلَ يَرْفَعُهُمَا بِحِيَالِ مَنْكِبَيْهِ وَيَضَعُهُمَا وَيَقُولُ عَلَيْكُمْ ‏ ‏هَدْيًا ‏ ‏قَاصِدًا ثَلَاثَ مَرَّاتٍ فَإِنَّهُ مَنْ يُشَادَّ الدِّينَ يَغْلِبْهُ ‏ ‏و قَالَ ‏ ‏يَزِيدُ ‏ ‏بِبَغْدَادَ ‏ ‏بُرَيْدَةُ الْأَسْلَمِيُّ ‏ ‏وَقَدْ كَانَ قَالَ عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏ثُمَّ رَجَعَ إِلَى ‏ ‏بُرَيْدَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَا ‏ ‏بُرَيْدَةُ الْأَسْلَمِيُّ ‏","","",""],[18951,18951,"","আমরা আমার ছেলের শাসন নিয়ে কথা বলেছি, তাকে আত্মসমর্পণ করতে হবে, আমি যা ভয় পাচ্ছি তা হল তোমার বেল্টে তোমার ভালোবাসা আর তোমার আত্মা দেবতাদের মুখে আছে.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِمَّا أَخْشَى عَلَيْكُمْ شَهَوَاتِ ‏ ‏الْغَيِّ ‏ ‏فِي بُطُونِكُمْ وَفُرُوجِكُمْ وَمُضِلَّاتِ الْهَوَى ‏","","",""],[18952,18952,"","আমাদের সংবাদ থেকে আমরা অনেক বেশি কথা বলেছি, আমার বাবা আমার সবচেয়ে ভালো বন্ধু হওয়ার জন্য দৃঢ়প্রতিজ্ঞ। ঈশ্বর আমাকে এমন কিছু শিখিয়েছেন যা তুমি তাকে ঈশ্বর বলে \"মানুষকে কষ্ট দাও\"","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو هِلَالٍ الرَّاسِبِيُّ مُحَمَّدُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَازِعِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي شَيْئًا يَنْفَعُنِي اللَّهُ تَبَارَكَ وَتَعَالَى بِهِ فَقَالَ ‏ ‏انْظُرْ مَا يُؤْذِي النَّاسَ فَاعْزِلْهُ عَنْ طَرِيقِهِمْ ‏","","",""],[18953,18953,"","বাবার পুনরুত্থান নিয়ে আমরা খুশি হয়েছি আর সে আমার বাবার মৃত্যুর ব্যাপারে আমাদের বেশি কিছু বলেছে। আমার শান্তি হবে বাতাস অথবা বাতাসের মত কোন সমস্যা হতো। তারা তার কাছে প্রার্থনা করে এবং বলে যে এটা হচ্ছে অভিশাপ। ঈশ্বর তার জন্য প্রার্থনা করেন এবং আপনি চান না আমি যুদ্ধ করি অথবা ভালো কারণের জন্য যাই। তোমার পালা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏كَانَتْ رَاحِلَةٌ ‏ ‏أَوْ نَاقَةٌ أَوْ بَعِيرٌ ‏ ‏عَلَيْهَا مَتَاعٌ لِقَوْمٍ فَأَخَذُوا بَيْنَ جَبَلَيْنِ وَعَلَيْهَا جَارِيَةٌ فَتَضَايَقَ بِهِمْ الطَّرِيقُ فَأَبْصَرَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَتْ تَقُولُ ‏ ‏حَلْ ‏ ‏حَلْ ‏ ‏اللَّهُمَّ الْعَنْهَا ‏ ‏أَوْ الْعَنْهُ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَصْحَبْنِي نَاقَةٌ ‏ ‏أَوْ رَاحِلَةٌ أَوْ بَعِيرٌ ‏ ‏عَلَيْهَا ‏ ‏أَوْ عَلَيْهِ ‏ ‏لَعْنَةٌ مِنْ اللَّهِ تَبَارَكَ وَتَعَالَى ‏","","",""],[18954,18954,"","আমরা জয়ের চেষ্টা করে কথা বলেছি। তার এই সাহসী হাত তোমাকে পালিয়ে নিয়ে গিয়ে একজন লোককে নিয়ে চলে যেতে বাধ্য করেছে। আমি তার কাছে ছয়টা জিতলে বা তাকে নিয়ে মজা করতে পারি, আমি আমার ডাক্তারের সাথে যেতে চাই তাকে ছেড়ে দিতে এবং তাকে বলতে চাই আমি কতটা আশীর্বাদ করেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏الْأَزْرَقُ بْنُ قَيْسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ شَيْخًا ‏ ‏بِالْأَهْوَازِ ‏ ‏يُصَلِّي الْعَصْرَ وَلِجَامُ دَابَّتِهِ فِي يَدِهِ فَجَعَلَتْ تَتَأَخَّرُ وَجَعَلَ ‏ ‏يَنْكِصُ ‏ ‏مَعَهَا وَرَجُلٌ قَاعِدٌ مِنْ ‏ ‏الْخَوَارِجِ ‏ ‏يَسُبُّهُ فَلَمَّا صَلَّى قَالَ إِنِّي قَدْ سَمِعْتُ مَقَالَتَكُمْ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتَّ غَزَوَاتٍ ‏ ‏أَوْ سَبْعَ غَزَوَاتٍ ‏ ‏فَشَهِدْتُ أَمْرَهُ وَتَيْسِيرَهُ فَكُنْتُ أَرْجِعُ مَعِي دَابَّتِي أَحَبُّ إِلَيَّ مِنْ أَنْ أَدَعَهَا فَتَأْتِيَ ‏ ‏مَأْلَفَهَا ‏ ‏فَيَشُقَّ عَلَيَّ قَالَ قُلْتُ كَمْ صَلَّى قَالَ رَكْعَتَيْنِ قَالَ وَإِذَا هُوَ ‏ ‏أَبُو بَرْزَةَ ‏","","",""],[18955,18955,"","আমরা একটা ছেলের কথা বলেছি যে আমার বাবার কাছে রাজসভা জয় করার জন্য ডিজাইন করা হয়েছে, ঈশ্বর আমাকে কিছু করতে দিয়েছেন আমাকে যেতে অথবা পতাকা ভেঙ্গে ফেলতে ব্যবহার করতে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ صَمْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَازِعِ الرَّاسِبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏دُلَّنِي عَلَى عَمَلٍ يُدْخِلُنِي الْجَنَّةَ أَوْ أَنْتَفِعُ بِهِ قَالَ اعْزِلْ الْأَذَى عَنْ طَرِيقِ الْمُسْلِمِينَ ‏","","",""],[18956,18956,"","আমরা একে অপরের কথা বলেছি যে সে আমার ছেলের ব্যাপারে নরকের পিতার কথা শুনেছেন, ঈশ্বর তার পরে কথা বলার আগে ঘুমের উপরে উঠেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّوْمِ قَبْلَهَا وَالْحَدِيثِ بَعْدَهَا ‏","","",""],[18957,18957,"","দুই গ্রীষ্মের কথা আমার বাবার সাথে কথা বলেছি, সে পাঠ করছিল যে দুই ভদ্রলোক সকালে কি বলতে চেয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ بِمَا بَيْنَ السِّتِّينَ إِلَى الْمِائَةِ ‏ ‏يَعْنِي فِي الصُّبْحِ ‏","","",""],[18958,18958,"","আমরা সাহায্য করলাম, বসের পাশ দিয়ে আমার সাথে কথা বলে একজন ভালো সাহায্যর ছেলেকে খুঁজে পেতে। সে বলল আমি এই দু:খজনককে ভুল করে মেরে ফেলব এবং সে বলে ঈশ্বরই ঈশ্বর। আমি জানি, আমি আমার বসের সাথে কথা বলেছি, সে নাকি আমার সাথে কথা বলছে, সে নাকি আমার বসের ছেলে। আমি আমার সাথে কথা বলে দেব। ঈশ্বর আমাকে এটা করতে শিখিয়েছেন... ...এটা করার মাধ্যমে যে আমি আঘাত পাচ্ছি... ...এটা বিশ্বাস করা যে, তোমার বন্ধু আছে, যে আমার বন্ধু নয়।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏شَدَّادُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنِي ‏ ‏جَابِرُ بْنُ عَمْرٍو الرَّاسِبِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بَرْزَةَ الْأَسْلَمِيَّ ‏ ‏يَقُولُ ‏ ‏قَتَلْتُ ‏ ‏عَبْدَ الْعُزَّى بْنَ خَطَلٍ ‏ ‏وَهُوَ مُتَعَلِّقٌ بِسِتْرِ ‏ ‏الْكَعْبَةِ ‏ ‏وَقُلْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ مُرْنِي بِعَمَلٍ أَعْمَلُهُ فَقَالَ ‏ ‏أَمِطْ ‏ ‏الْأَذَى ‏ ‏عَنْ الطَّرِيقِ فَهُوَ لَكَ ‏ ‏صَدَقَةٌ ‏","","",""],[18959,18959,"","বাবা আমার বিয়ের অনুষ্ঠানে চলে যান, যতক্ষণ পর্যন্ত না আমরা তার সাথে তার সাথে দেখা করি এবং সে এর মাঝখানে আছে। প্রভুর দ্বারা পরিত্রাণ লাভ করা প্রভু প্রভু প্রভু হলেন প্রভু । তিনি বনের মধ্যে বলেছিলেন যে, তিনি যে - রাতের খাবার খেতে চান, তা দেরি করে দিতেন এবং তিনি ঘৃণা করতেন, তা ঘৃণা করতেন । জানি আমরা শুধু বসে ছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمِنْهَالِ ‏ ‏قَالَ ‏ ‏قَالَ لِي أَبِي انْطَلِقْ إِلَى ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏فَانْطَلَقْتُ مَعَهُ حَتَّى دَخَلْنَا عَلَيْهِ فِي دَارِهِ وَهُوَ قَاعِدٌ فِي ظِلِّ عُلْوٍ مِنْ ‏ ‏قَصَبٍ ‏ ‏فَجَلَسْنَا إِلَيْهِ فِي يَوْمٍ شَدِيدِ الْحَرِّ فَسَأَلَهُ أَبِي حَدِّثْنِي كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَكْتُوبَةَ قَالَ كَانَ ‏ ‏يُصَلِّي ‏ ‏الْهَجِيرَ ‏ ‏الَّتِي تَدْعُونَهَا الْأُولَى حِينَ ‏ ‏تَدْحَضُ ‏ ‏الشَّمْسُ وَكَانَ ‏ ‏يُصَلِّي الْعَصْرَ ثُمَّ يَرْجِعُ أَحَدُنَا إِلَى رَحْلِهِ فِي أَقْصَى ‏ ‏الْمَدِينَةِ ‏ ‏وَالشَّمْسُ ‏ ‏حَيَّةٌ ‏ ‏قَالَ وَنَسِيتُ مَا قَالَ فِي الْمَغْرِبِ ‏ ‏قَالَ وَكَانَ يَسْتَحِبُّ أَنْ يُؤَخِّرَ الْعِشَاءَ الَّتِي تَدْعُونَهَا ‏ ‏الْعَتَمَةَ ‏ ‏قَالَ وَكَانَ يَكْرَهُ النَّوْمَ قَبْلَهَا وَالْحَدِيثَ بَعْدَهَا قَالَ وَكَانَ ‏ ‏يَنْفَتِلُ ‏ ‏مِنْ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏حِينَ يَعْرِفُ أَحَدُنَا جَلِيسَهُ وَكَانَ يَقْرَأُ بِالسِّتِّينَ إِلَى الْمِائَةِ ‏","","",""],[18960,18960,"","আমরা এই ভেবে বাপ্তাইজিত হয়েছি যে, একটা বিদ্রোহ নিয়ে যে আবেগ তৈরি হয়েছে, আমি হয়ত বলেছি যে ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমাদের প্রভুর কাছে তিনি সমর্পণ করবেন। বলবে আমার বাবাকে বলতে তার সবচেয়ে ভালো টাকা আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُسَاوِرِ بْنِ عُبَيْدٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏فَقُلْتُ هَلْ ‏ ‏رَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ رَجُلًا مِنَّا يُقَالُ لَهُ ‏ ‏مَاعِزُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏مُسَاوِرُ بْنُ عُبَيْدٍ الْحِمَّانِيُّ ‏","","",""],[18961,18961,"","আমরা মাহদি বেন মেমির কথা বলেছি যিনি আমাদের ছেলে থেকে একজন পুরুষকে বিয়ে করার কথা বলেছেন, ঈশ্বরের বংশধরকে ঈশ্বরের কাছে হস্তান্তর করা হয়েছে, আর তিনি ঈশ্বরের কাছে নিজেকে উৎসর্গ করবেন। তারা তোমাকে মারতে চায়, যদি তুমি তাকে মারতে, সে তাকে মেরে ফেলতে পারত। আমরা একটা উপহার দিয়েছি যা আমরা বলেছিলাম যে বিরোধের বাবা-মা'কে একত্রিত করেছি। ছেলেটির কথা শুনুক বা বল, সে ঈশ্বরের বার্তাবাহকের হাতে হস্তান্তর করেছে, আর তাকে ঈশ্বরের দোহাই দিয়ে দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَازِعِ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي رَاسِبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَسُولًا إِلَى حَيٍّ مِنْ أَحْيَاءِ ‏ ‏الْعَرَبِ ‏ ‏فِي شَيْءٍ لَا يَدْرِي ‏ ‏مَهْدِيٌّ ‏ ‏مَا هُوَ قَالَ فَسَبُّوهُ وَضَرَبُوهُ فَشَكَا ذَلِكَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَوْ أَنَّكَ أَتَيْتَ أَهْلَ ‏ ‏عُمَانَ ‏ ‏مَا سَبُّوكَ وَمَا ضَرَبُوكَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرٌ أَبُو الْوَازِعِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَسُولًا إِلَى حَيٍّ مِنْ أَحْيَاءِ ‏ ‏الْعَرَبِ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18962,18962,"","আমরা বাবার স্বপ্নের কথা বলেছিলাম যে সে যেন কোন স্বপ্ন উদ্ধার করতে পারে। ঈশ্বর শেষ ডিনার দেরি করে আমাকে বলতেন তিন রাত ধরে। আর সে এটাকে ঘৃণা করবে। আমরা যখন সেখানে যাই, তখন আমরা কী করতে পারি?","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سَيَّارِ بْنِ سَلَامَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُؤَخِّرُ الْعِشَاءَ الْآخِرَةَ إِلَى ثُلُثِ اللَّيْلِ وَكَانَ يَكْرَهُ النَّوْمَ قَبْلَهَا وَالْحَدِيثَ بَعْدَهَا وَكَانَ يَقْرَأُ فِي الْفَجْرِ مَا بَيْنَ الْمِائَةِ إِلَى السِّتِّينَ وَكَانَ يَنْصَرِفُ حِينَ يَنْصَرِفُ وَبَعْضُنَا يَعْرِفُ وَجْهَ بَعْضٍ ‏","","",""],[18963,18963,"","তিনি বলেছিলেন যে, ঈশ্বর তার জন্য প্রার্থনা করছেন এবং এমনকি তিনি তার নিজের দশ জনের আনন্দও শুনতে পাবেন । তাদের আত্মার পিছু নাও, তার বাড়ি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏قُطْبَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏نَادَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَسْمَعَ ‏ ‏الْعَوَاتِقَ ‏ ‏فَقَالَ يَا مَعْشَرَ ‏ ‏مَنْ آمَنَ بِلِسَانِهِ وَلَمْ يَدْخُلْ الْإِيمَانُ قَلْبَهُ لَا تَغْتَابُوا الْمُسْلِمِينَ وَلَا تَتَّبِعُوا عَوْرَاتِهِمْ فَإِنَّهُ مَنْ يَتَّبِعْ عَوْرَةَ أَخِيهِ يَتَّبِعْ اللَّهُ عَوْرَتَهُ حَتَّى يَفْضَحَهُ فِي بَيْتِهِ ‏","","",""],[18964,18964,"","বাবা আমাকে এটা করতে শিখিয়েছে যে আমি ভুল করেছি, তোমার বিশ্বাস করাই তোমার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَدَّادٌ أَبُو طَلْحَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرُ بْنُ عَمْرٍو أَبُو الْوَازِعِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مُرْنِي بِعَمَلٍ أَعْمَلُهُ قَالَ أَمِطْ الْأَذَى عَنْ الطَّرِيقِ فَهُوَ لَكَ ‏ ‏صَدَقَةٌ ‏","","",""],[18965,18965,"","ভুলের ছেলে আমাকে হত্যা করে এবং সে তার থাবা দিয়ে ঝুলিয়ে বলে যে খোদা হলো তার চিতাবাঘ।","‏ ‏قَالَ ‏ ‏وَقَتَلْتُ ‏ ‏عَبْدَ الْعُزَّى بْنَ خَطَلٍ ‏ ‏وَهُوَ مُتَعَلِّقٌ بِسِتْرِ ‏ ‏الْكَعْبَةِ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏النَّاسُ آمِنُونَ غَيْرَ ‏ ‏عَبْدِ الْعُزَّى بْنِ خَطَلٍ ‏","","",""],[18966,18966,"","আমি ঈশ্বরের কাছে প্রার্থনা করেছি তার জন্য প্রার্থনা করে আর সে বলবে যে আমার আর কিছু করার আছে। আর.","‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ لِي حَوْضًا مَا بَيْنَ ‏ ‏أَيْلَةَ ‏ ‏إِلَى ‏ ‏صَنْعَاءَ ‏ ‏عَرْضُهُ كَطُولِهِ فِيهِ ‏ ‏مِيزَابَانِ ‏ ‏يَنْثَعِبَانِ ‏ ‏مِنْ الْجَنَّةِ مِنْ وَرِقٍ وَالْآخَرُ مِنْ ذَهَبٍ أَحْلَى مِنْ الْعَسَلِ وَأَبْرَدُ مِنْ الثَّلْجِ وَأَبْيَضُ مِنْ اللَّبَنِ مَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ حَتَّى يَدْخُلَ الْجَنَّةَ فِيهِ أَبَارِيقُ عَدَدَ نُجُومِ السَّمَاءِ ‏","","",""],[18967,18967,"","আমরা আমাদের চেয়ে ভাল কথা বলেছি, আমার ভালোবাসায় স্বপ্নের চেয়ে। আমার বাবা আমার কথা মেনে নিয়েছেন। আমি ইশ্বরকে দোষারোপ করছি এই দৈত্যের জন্য যে আমাদের হত্যা করছে আর আমাদের মেরে ফেলছে। এই আংটিটা হল তাদের দুঃখ এবং ভয় তাদের রক্ত থেকে তাদের মুখ ফিরিয়ে নেয় । পর্দার আড়ালে থাকা ছায়ার আবরণের আবরণের আবরণ, পর্দার আড়ালে থাকা পর্দার আড়ালে ঢেকে ফেলা ছায়ার আবরণ । তারা শাসন করে এবং ক্ষমা করে । ( যিশা.","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏سُكَيْنُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏سَيَّارِ بْنِ سَلَامَةَ أَبِي الْمِنْهَالِ الرِّيَاحِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ أَبِي عَلَى ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏وَإِنَّ فِي أُذُنَيَّ يَوْمَئِذٍ ‏ ‏لَقُرْطَيْنِ ‏ ‏قَالَ وَإِنِّي لَغُلَامٌ قَالَ فَقَالَ ‏ ‏أَبُو بَرْزَةَ ‏ ‏إِنِّي أَحْمَدُ اللَّهَ أَنِّي أَصْبَحْتُ لَائِمًا لِهَذَا الْحَيِّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏فُلَانٌ هَاهُنَا يُقَاتِلُ عَلَى الدُّنْيَا وَفُلَانٌ هَاهُنَا يُقَاتِلُ عَلَى الدُّنْيَا ‏ ‏يَعْنِي ‏ ‏عَبْدَ الْمَلِكِ بْنَ مَرْوَانَ ‏ ‏قَالَ حَتَّى ذَكَرَ ‏ ‏ابْنَ الْأَزْرَقِ ‏ ‏قَالَ ثُمَّ قَالَ إِنَّ أَحَبَّ النَّاسِ إِلَيَّ لَهَذِهِ ‏ ‏الْعِصَابَةُ ‏ ‏الْمُلَبَّدَةُ ‏ ‏الْخَمِيصَةُ ‏ ‏بُطُونُهُمْ مِنْ أَمْوَالِ الْمُسْلِمِينَ وَالْخَفِيفَةُ ظُهُورُهُمْ مِنْ دِمَائِهِمْ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأُمَرَاءُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏الْأُمَرَاءُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏الْأُمَرَاءُ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏لِي عَلَيْهِمْ حَقٌّ وَلَهُمْ عَلَيْكُمْ حَقٌّ مَا فَعَلُوا ثَلَاثًا مَا حَكَمُوا فَعَدَلُوا وَاسْتُرْحِمُوا فَرَحِمُوا وَعَاهَدُوا فَوَفَوْا فَمَنْ لَمْ يَفْعَلْ ذَلِكَ مِنْهُمْ فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[18968,18968,"","আমি আমার ভালবাসার ঈর্ষার কথা শুনেছি। বাবা ঈশ্বরের কাছে প্রার্থনা করেছিলেন। আর তিনি বললেন, তিনি তার জন্য প্রার্থনা করবেন এবং আমাকে জিজ্ঞেস করবেন আমি কি করছি এবং ঈশ্বর আপনার মঙ্গল করুক। তুমি বলো।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ أَبِي بَرْزَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غِفَارُ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَأَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ مَا أَنَا قُلْتُهُ وَلَكِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَهُ ‏","","",""],[18969,18969,"","বাবা যখন কথা বলেছিলেন, তখন আমরা যে - বধিররা কথা বলেছিলাম, তাদের কথা বলেছিলাম, তারা তখন সেই বধিরদের কথা বলেছিলাম । ঈশ্বর তাকে তার কাছ থেকে ছুঁড়ে ফেলে দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ أَبُو طَالُوتَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَبَّاسُ الْجُرَيْرِيُّ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ زِيَادٍ ‏ ‏قَالَ ‏ ‏لِأَبِي بَرْزَةَ ‏ ‏هَلْ سَمِعْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَهُ قَطُّ ‏ ‏يَعْنِي الْحَوْضَ ‏ ‏قَالَ نَعَمْ لَا مَرَّةً وَلَا مَرَّتَيْنِ ‏ ‏فَمَنْ كَذَّبَ بِهِ فَلَا سَقَاهُ اللَّهُ مِنْهُ ‏","","",""],[18970,18970,"","আমরা বধির আর সূর্য সম্পর্কে কথা বলেছি, \"হেইল,\" মানে, \"আমি বলতে চাচ্ছি, \"কাঠি, একটি ছেলে যে ব্যাজ নিয়ে উড়তে পারে\" নাবিক এখানে এসেছে যখন আমি দেখলাম যে একজন মানুষকে পরাজিত করা হয়েছে। আমি বলছি, \"আমি\" ভয় পাওয়ার কথা, আমি কখনও মুখ দিয়ে মুখ দিয়ে মুখটা দেখতে পারিনি, তুমি ঈশ্বরের কাছে প্রার্থনা করেছ, যেন সে আত্মসমর্পণ করে আমি ঈশ্বরের কাছে প্রার্থনা করছি, যে ছেলে হারিয়ে গেছে, আর তারপর সে একজন মানুষ যে কিনা হয়ে গেছে। যে ব ্ যক ্ তি উপুড় হয়ে পড়েছে , সেই সফলকাম হয় । আমি দেওয়ালের উপর প্রভাব ফেলতে পারি, যে তার নিজের মৃত্যুর আগে তাকে মেরে ফেলবে। শপথটা খুবই শক্ত এবং সে বলল, \"ঈশ্বর কখনো আমাকে খুঁজে পাবে না।\" মানুষ ছিল একজন মানুষ, তারা এমন মানুষ ছিল যেমন শিং এর স্টক আর তাদের শেষ হাতে ফিরে আসবে না. আপনার ক্রেতার সম্বন্ধে একজন প্রত্যক্ষদর্শীর কাছে বলা সম্বন্ধে বলা হয়েছে যে, আমি একজন অসন্তুষ্ট ব্যক্তির সঙ্গে দেখা করতে চাই । -a-a-a--Ta-a-a--a---aaa-----aa----aaaaaa------aaaa----------aaaaaaaaaaaaa--------------------aaaaaaaaaaaaaaaaaaaaa-----------------------aaaaaaaaaaaaaaaaaaaaaaaaaaaaaa--------------------------------------T-T-----------T-aaa-------------------------------- -a-a-a--a---a--------------------------------------------------------------------া-----া-------া-া-----aা------া-এ-া-aা------া----া-a-রা-এ","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَيُونُسُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْأَزْرَقِ بْنِ قَيْسٍ ‏ ‏أَنَّ ‏ ‏شَرِيكَ بْنَ شِهَابٍ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏الْحَارِثِيُّ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏عَبْدِ الصَّمَدِ ‏ ‏قَالَ ‏ ‏لَيْتَ أَنِّي رَأَيْتُ رَجُلًا مِنْ ‏ ‏أَصْحَابِ مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُنِي عَنْ ‏ ‏الْخَوَارِجِ ‏ ‏قَالَ فَلَقِيتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏فِي نَفَرٍ مِنْ ‏ ‏أَصْحَابِ مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ حَدِّثْنِي شَيْئًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْخَوَارِجِ ‏ ‏قَالَ أُحَدِّثُكُمْ بِشَيْءٍ قَدْ سَمِعَتْهُ أُذُنَايَ وَرَأَتْهُ عَيْنَايَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِدَنَانِيرَ فَقَسَمَهَا وَثَمَّ ‏ ‏رَجُلٌ ‏ ‏مَطْمُومُ ‏ ‏الشَّعْرِ ‏ ‏آدَمُ ‏ ‏أَوْ أَسْوَدُ ‏ ‏بَيْنَ عَيْنَيْهِ أَثَرُ السُّجُودِ عَلَيْهِ ثَوْبَانِ أَبْيَضَانِ فَجَعَلَ يَأْتِيهِ مِنْ قِبَلِ يَمِينِهِ وَيَتَعَرَّضُ لَهُ فَلَمْ يُعْطِهِ شَيْئًا قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏مَا عَدَلْتَ الْيَوْمَ فِي الْقِسْمَةِ فَغَضِبَ غَضَبًا شَدِيدًا ثُمَّ قَالَ وَاللَّهِ لَا تَجِدُونَ بَعْدِي أَحَدًا ‏ ‏أَعْدَلَ عَلَيْكُمْ مِنِّي ثَلَاثَ مَرَّاتٍ ثُمَّ قَالَ يَخْرُجُ مِنْ قِبَلِ الْمَشْرِقِ رِجَالٌ كَانَ هَذَا مِنْهُمْ هَدْيُهُمْ هَكَذَا يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ ‏ ‏تَرَاقِيَهُمْ ‏ ‏يَمْرُقُونَ ‏ ‏مِنْ الدِّينِ كَمَا ‏ ‏يَمْرُقُ ‏ ‏السَّهْمُ مِنْ ‏ ‏الرَّمِيَّةِ ‏ ‏ثُمَّ لَا يَرْجِعُونَ فِيهِ ‏ ‏سِيمَاهُمْ ‏ ‏التَّحْلِيقُ ‏ ‏لَا يَزَالُونَ يَخْرُجُونَ حَتَّى يَخْرُجَ آخِرُهُمْ مَعَ ‏ ‏الدَّجَّالِ ‏ ‏فَإِذَا لَقِيتُمُوهُمْ فَاقْتُلُوهُمْ هُمْ شَرُّ الْخَلْقِ وَالْخَلِيقَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَزْرَقُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَتَمَنَّى أَنْ أَلْقَى رَجُلًا مِنْ ‏ ‏أَصْحَابِ مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُنِي عَنْ ‏ ‏الْخَوَارِجِ ‏ ‏فَلَقِيتُ ‏ ‏أَبَا بَرْزَةَ ‏ ‏فِي يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فِي نَفَرٍ مِنْ أَصْحَابِهِ فَذَكَرَ الْحَدِيثَ ‏","","",""],[18971,18971,"","আমি যে - বধির ব্যক্তিদের সম্বন্ধে কথা বলেছিলাম, তারা একজন বেথিস্ট স্বপ্নবিদ, যিনি ছেলে ছিলেন । ( গীতসংহিতা ৩৪: ৮) আর প্রয়োজনের মধ্যে দিয়ে তা উদ্ধার করা হবে অথবা বলে ঈশ্বর তাঁর শান্তি নিয়ে আসবেন । তার মা যতক্ষণ পর্যন্ত না বলে যে, ঈশ্বর তার জন্য এসে আপনার মেয়েকে থ্রেড তৈরি করে দেবেন এবং তাকে তার কাছে আত্মসমর্পণ করতে হবে । তার ছেলে কখনো আমার কুকুরকে বিয়ে করেনি, সে বলেছিল তার বাবা এটা করেনি. আমাকে ঈশ্বরের কাছে আদেশ দিয়েছেন, ঈশ্বর আমাকে রক্ষা করেছেন আর আমাকে আদেশ করেছেন যে তিনি তাকে আমার কাছে পৌঁছে দিয়েছেন, তিনি এমন কিছু বলেছেন যা আপনি তাকে জিতেছে, যখন ভাববাদী ছিলেন ( গীতসংহিতা ৩৪: ১০) আপনার আশীর্বাদ ঈশ্বরের কাছে এসে তাঁর কাছে এসে পৌঁছায় এবং তিনি তাকে হত্যা করবেন । ঈশ্বর তাকে আত্মসমর্পণ করতে, হত্যা করতে এবং হত্যা করতে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏كِنَانَةَ بْنِ نُعَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ ‏ ‏أَنَّ ‏ ‏جُلَيْبِيبًا ‏ ‏كَانَ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَكَانَ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ لِأَحَدِهِمْ ‏ ‏أَيِّمٌ ‏ ‏لَمْ يُزَوِّجْهَا حَتَّى يَعْلَمَ أَلِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا حَاجَةٌ أَمْ لَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ لِرَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏زَوِّجْنِي ابْنَتَكَ فَقَالَ ‏ ‏نِعِمَّ وَنُعْمَةُ عَيْنٍ فَقَالَ لَهُ إِنِّي لَسْتُ لِنَفْسِي أُرِيدُهَا قَالَ فَلِمَنْ قَالَ ‏ ‏لِجُلَيْبِيبٍ ‏ ‏قَالَ حَتَّى ‏ ‏أَسْتَأْمِرَ ‏ ‏أُمَّهَا فَأَتَاهَا فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ ابْنَتَكِ قَالَتْ ‏ ‏نِعِمَّ وَنُعْمَةُ عَيْنٍ زَوِّجْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّهُ لَيْسَ يُرِيدُهَا لِنَفْسِهِ قَالَتْ فَلِمَنْ قَالَ ‏ ‏لِجُلَيْبِيبٍ ‏ ‏قَالَتْ حَلْقَى ‏ ‏أَجُلَيْبِيبٌ ‏ ‏ابْنَهْ مَرَّتَيْنِ لَا لَعَمْرُ اللَّهِ لَا أُزَوِّجُ ‏ ‏جُلَيْبِيبًا ‏ ‏قَالَ فَلَمَّا قَامَ أَبُوهَا لِيَأْتِيَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ الْفَتَاةُ لِأُمِّهَا مِنْ ‏ ‏خِدْرِهَا ‏ ‏مَنْ خَطَبَنِي إِلَيْكُمَا قَالَتْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَتَرُدُّونَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْرَهُ ادْفَعُونِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّهُ لَا يُضَيِّعُنِي فَأَتَى أَبُوهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ شَأْنَكَ بِهَا فَزَوَّجَهَا ‏ ‏جُلَيْبِيبًا ‏ ‏فَبَيْنَمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَغْزًى لَهُ وَأَفَاءَ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَيْهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَفْقِدُونَ مِنْ أَحَدٍ قَالُوا نَفْقِدُ فُلَانًا وَنَفْقِدُ فُلَانًا فَقَالَ النَّبِيُّ لَكِنِّي أَفْقِدُ ‏ ‏جُلَيْبِيبًا ‏ ‏فَانْظُرُوهُ فِي الْقَتْلَى فَنَظَرُوهُ فَوَجَدُوهُ إِلَى جَنْبِ سَبْعَةٍ قَدْ قَتَلَهُمْ ثُمَّ قَتَلُوهُ قَالَ فَوَقَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ قَتَلَ سَبْعَةً ثُمَّ قَتَلُوهُ هَذَا مِنِّي وَأَنَا مِنْهُ ثُمَّ حَمَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى سَاعِدَيْهِ مَا لَهُ سَرِيرٌ غَيْرَ سَاعِدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى حُفِرَ لَهُ ثُمَّ وَضَعَهُ فِي لَحْدِهِ وَمَا ذَكَرَ غُسْلًا ‏","","",""],[18972,18972,"","আমার ভাইয়ের কথা নিয়ে আমরা কথা বলেছি যে বিপদে পড়বে, ঈশ্বরের কাছে প্রার্থনা করতে হবে যেন সে উদ্ধার করতে পারে এবং মারা যেতে পারে। সেই শহর জীবিত আছে এবং সূর্য চলে গেছে, যেভাবে আমি ভুলে গিয়েছিলাম এবং তার এবং তার আগে ঘুমের জন্য খাবার শেষ হয়নি । তাকে গ্রীষ্মের সকালে ডাকা হয়, আর সে প্রাসাদে চলে যায়, ১০০ জন বলল যে একটা গাড়ি আমি তাদের একজনকে চিনি না।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَيَّارِ بْنِ سَلَامَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا وَأَبِي عَلَى ‏ ‏أَبِي بَرْزَةَ ‏ ‏فَسَأَلْنَاهُ عَنْ وَقْتِ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ كَانَ ‏ ‏يُصَلِّي الظُّهْرَ حِينَ تَزُولُ الشَّمْسُ وَالْعَصْرَ يَرْجِعُ الرَّجُلُ إِلَى أَقْصَى ‏ ‏الْمَدِينَةِ ‏ ‏وَالشَّمْسُ حَيَّةٌ وَالْمَغْرِبَ ‏ ‏قَالَ ‏ ‏سَيَّارٌ ‏ ‏نَسِيتُهَا ‏ ‏وَالْعِشَاءَ لَا يُبَالِي بَعْدَ تَأْخِيرِهَا إِلَى ثُلُثِ اللَّيْلِ وَكَانَ لَا يُحِبُّ النَّوْمَ قَبْلَهَا وَالْحَدِيثَ بَعْدَهَا وَكَانَ ‏ ‏يُصَلِّي الصُّبْحَ فَيَنْصَرِفُ الرَّجُلُ فَيَعْرِفُ وَجْهَ جَلِيسِهِ وَكَانَ يَقْرَأُ فِيهَا مَا بَيْنَ السِّتِّينَ إِلَى الْمِائَةِ ‏ ‏قَالَ ‏ ‏سَيَّارٌ ‏ ‏لَا أَدْرِي فِي إِحْدَى الرَّكْعَتَيْنِ أَوْ فِي كِلْتَيْهِمَا ‏","","",""],[18973,18973,"","আমরা বাবার সবচেয়ে ভালো কথা বলেছি, সে আমার বাবার কাছে প্রার্থনা করেনি, সে ঈশ্বরের কাছে প্রার্থনা করতো সে আত্মসমর্পণ করবে, মহারাজ, তুমি কি বলো না যে তুমি বল না এটা তোমার মনে হচ্ছে না যে তুমি এটা বলতে চাচ্ছ এটা এমন নয় যে তুমি এটা বলবে এটা এমন নয় যে তুমি বলবে এটা এমন নয় যে তুমি এমন হবে যে তুমি হবে তোমার মত হবে কে বলবে এটা একই কথা নয় আমরা ভেবেছিলাম এটা একটা বড় ব্যাপার.","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏رُفَيْعٍ أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ بِآخِرَةٍ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَلَسَ فِي الْمَجْلِسِ فَأَرَادَ أَنْ يَقُومَ قَالَ ‏ ‏سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ تَقُولُ الْآنَ كَلَامًا مَا كُنْتَ تَقُولُهُ فِيمَا خَلَا قَالَ هَذَا كَفَّارَةُ مَا يَكُونُ فِي الْمَجْلِسِ ‏","","",""],[18974,18974,"","বাবার সাথে একবার আমার বাবার দেখা হয়েছিল একবার জয়-উইনের চেয়ে ভালো। এবং লর্ড লর্ডের লর্ডের লর্ডের লর্ডের লর্ডের কাছে তার প্রভুর কাছে হস্তান্তর করেছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏جَمِيلِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَضِيءِ ‏ ‏قَالَ ‏ ‏كُنَّا فِي سَفَرٍ وَمَعَنَا ‏ ‏أَبُو بَرْزَةَ ‏ ‏فَقَالَ ‏ ‏أَبُو بَرْزَةَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا ‏","","",""],[18975,18975,"","ঈশ্বরের হাত নিয়ে আমি কথা বলেছি, আমাকে এটা বলতে হবে। আমার প্রভু গর্ভের মধ্যে আছেন আমার শান্তি জয়ের জন্য। আমি আপনাকে ঈশ্বরের অনুগ্রহ থেকে শুনতে আমি আপনাকে সন্তুষ্ট করতে চাই না। ঈশ্বর জয়ী হয়েছেন এবং তা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏شَكَّ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏فِي الْحَوْضِ فَأَرْسَلَ إِلَى ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏فَأَتَاهُ فَقَالَ لَهُ جُلَسَاءُ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏إِنَّمَا ‏ ‏أَرْسَلَ إِلَيْكَ الْأَمِيرُ ‏ ‏لِيَسْأَلَكَ عَنْ الْحَوْضِ فَهَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا قَالَ نَعَمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُهُ فَمَنْ كَذَّبَ بِهِ فَلَا سَقَاهُ اللَّهُ عَزَّ وَجَلَّ مِنْهُ ‏","","",""],[18976,18976,"","আমরা সেই সময়ের কথা শুনে খুশি হয়েছি কিন্তু আমাদের জীবনের সবচেয়ে প্রতিশ্রুতিশীল ছেলে, একজন অতিথি ঈশ্বরের অনুগ্রহে চলে গেছে এবং ব্যর্থ হয়েছে। আপনার লর্ডকে বলা যেতে পারে আপনি হয়ত তার চেষ্টা করেছেন, আমরা একটি নির্দিষ্ট আবেগ শুনেছি যে আমরা একজন পর্যটকের কাছ থেকে যে কোন একটি বার্তা শুনেছি একটা কুত্তার বাচ্চা, দুটো ঘোড়ার সাথে, সে তার আদর্শের কথা বলেছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَإِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ فَقَرَأَ رَجُلٌ خَلْفَهُ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏فَلَمَّا صَلَّى قَالَ ‏ ‏أَيُّكُمْ قَرَأَ ‏ ‏سَبِّحْ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏فَقَالَ رَجُلٌ أَنَا قَالَ قَدْ عَرَفْتُ أَنَّ بَعْضَكُمْ ‏ ‏خَالَجَنِيهَا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى يُحَدِّتُ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[18977,18977,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমাদের সময় ও আমরা যা বলি, তা আমাদের সকলের কাছে পৌঁছে দেবে । তিনি বলেছিলেন, আমি দু - বছর ভবিষ্যদ্বাণীর বিষয়ে তার কাছে প্রার্থনা করেছি এবং তার আদর্শকে রক্ষা করেছি ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ رَبَاحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا السَّوَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَيَاءُ خَيْرٌ كُلُّهُ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ رَبَاحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا السَّوَّارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[18978,18978,"","আমরা একে অপরের কথা বলেছি একটি প্রান্তরে ভালো ছেলের ভালোর জন্য। আমার কাছে পাইপ ছিল। আমি ভবিষ্যদ্বাণী করতে বলেছিলাম, আর প্রার্থনা করতে করতে হবে। এমন কিছু যা ভুল ছিল, তুমি কাপুরুষ হতে পারো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏عَنْ ‏ ‏حُسَيْنٍ الْمُعَلِّمِ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏كَانَ بِي ‏ ‏النَّاصُورُ ‏ ‏فَسَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّلَاةِ فَقَالَ ‏ ‏صَلِّ قَائِمًا فَإِنْ لَمْ تَسْتَطِعْ فَقَاعِدًا فَإِنْ لَمْ تَسْتَطِعْ فَعَلَى جَنْبٍ ‏","","",""],[18979,18979,"","আমরা এই বিষয়ে কথা বলেছি, তারপর লোকজন আশীর্বাদ পাবে আর বিষ দিয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالُ بْنُ يَسَافٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ النَّاسِ قَرْنِي ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ يَجِيءُ قَوْمٌ ‏ ‏يَتَسَمَّنُونَ ‏ ‏يُحِبُّونَ السِّمَنَ يُعْطُونَ الشَّهَادَةَ قَبْلَ أَنْ يُسْأَلُوهَا ‏","","",""],[18980,18980,"","আমরা কথা বলেছি দুটো ঘোড়া আছে খোদাকে যেতে বলেছে, সে গায়কের আদেশ দিয়েছে, তার মুখে, সে আমার বাবাকে দোষ দিয়েছে, আমি তার ভালবাসাকে কখনো জানতাম না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسْأَلَةُ الْغَنِيِّ ‏ ‏شَيْنٌ ‏ ‏فِي وَجْهِهِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏لَمْ أَعْلَمْ أَحَدًا أَسْنَدَهُ غَيْرَ ‏ ‏وَكِيعٍ ‏","","",""],[18981,18981,"","আমরা গত দুই মাস ধরে অনেক ভালো কাজ করেছি। আমার ছেলের উপর দয়া করে প্রভুর কাছে তার কাছে এসেছি। আরে, বাবা, আমরা শপথ করে বলছি, \"যা খুশি হতে হবে.\" আর আল্লাহ তাকে জীবিত বলতে হবে যে, যদি সে এটার জন্য পড়ে না যায় তাহলে সে মারা যাবে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏جَاءَ نَفَرٌ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏جَاءَتْ ‏ ‏بَنُو تَمِيمٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَبْشِرُوا يَا ‏ ‏بَنِي تَمِيمٍ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ بَشَّرْتَنَا فَأَعْطِنَا ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَجَاءَ حَيٌّ مِنْ ‏ ‏يَمَنٍ ‏ ‏فَقَالَ اقْبَلُوا الْبُشْرَى إِذْ لَمْ يَقْبَلْهَا ‏ ‏بَنُو تَمِيمٍ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ قَبِلْنَا ‏","","",""],[18982,18982,"","আমরা রাজার কথা শুনি বধিরদের মাধ্যমে, আর তারপর আমরা বিচার শুরু করি যখন একমাত্র ঈশ্বর তার জন্য প্রার্থনা করেন আর তার মুখ দিয়ে তার মঙ্গলভাবের কথা বলেন। যাদের পাওয়া গেছে তাদের পাওয়া যাবে যারা মারা যাবে এবং তৈরি হবে, তারা দেখছে আর তারা বিষের মধ্যে আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا ثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ هَذِهِ الْأُمَّةِ ‏ ‏الْقَرْنُ ‏ ‏الَّذِي بُعِثْتُ فِيهِمْ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏الَّذِينَ بُعِثْتُ فِيهِمْ ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ يَنْشَأُ قَوْمٌ يَنْذُرُونَ وَلَا يُوفُونَ وَيَخُونُونَ وَلَا يُؤْتَمَنُونَ وَيَشْهَدُونَ وَلَا يُسْتَشْهَدُونَ وَيَنْشَأُ فِيهِمْ السِّمَنُ ‏","","",""],[18983,18983,"","আমরা তাদের বলেছিলাম, আমার বাবাকে দুটো ঘোড়ার কথা জানা থেকে কতটা ভালো হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي مِرَايَةَ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى ‏","","",""],[18984,18984,"","আমরা আমার বাবার সাথে গাউনের বড়দের সাথে খেলছি। দাঁড়িয়ে থাকো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَن ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ إِنَّ فُلَانًا لَا يُفْطِرُ نَهَارَ الدَّهْرِ فَقَالَ ‏ ‏لَا أَفْطَرَ وَلَا صَامَ ‏","","",""],[18985,18985,"","আমরা আমার বাবাকে মারার চেষ্টা করেছি, তার ছয় জন মালিকের মৃত্যুর টাকা নেই, আমি তাদের ছেলেদের ঘৃণা করতাম আর আমি তাদের কাছে যেতাম, আমি আমার বাবার কাছে গিয়ে আরো কাছে যেতাম এবং আমি আমার বাবার খুন করতাম। সে বলে খারাপ কিছু বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ رَجُلًا أَعْتَقَ سِتَّةَ مَمْلُوكِينَ لَهُ عِنْدَ مَوْتِهِ لَمْ يَكُنْ لَهُ مَالٌ غَيْرُهُمْ فَدَعَا بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَزَّأَهُمْ أَثْلَاثًا ثُمَّ أَقْرَعَ بَيْنَهُمْ فَأَعْتَقَ اثْنَيْنِ وَأَرَقَّ أَرْبَعَةً وَقَالَ لَهُ قَوْلًا شَدِيدًا ‏","","",""],[18986,18986,"","ঈশ্বর আছেন এবং আমার ছেলে শয়তানের ফাঁদ থেকে দুই জন মানুষ থাকবে ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَى ‏ ‏رَجُلَيْنِ مِنْ الْمُسْلِمِينَ بِرَجُلٍ مِنْ الْمُشْرِكِينَ مِنْ ‏ ‏بَنِي عُقَيْلٍ ‏","","",""],[18987,18987,"","ঈশ্বর তাকে তার চোরদের দলে সমর্পণ এবং আত্মসমর্পণ করার আদেশ দিয়েছেন আর এরপর তিনি তার মুখে প্রবেশ করেছেন, ঈশ্বর । বাইরে গিয়ে তাকে বলো যে সে তৈরি হয়েছে, সে দুটি মসজিদ খুঁজে পেয়েছে, আর তারপর সে পৌঁছে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلَّمَ فِي ثَلَاثِ رَكَعَاتٍ مِنْ الْعَصْرِ ثُمَّ قَامَ فَدَخَلَ فَقَامَ إِلَيْهِ رَجُلٌ يُقَالُ لَهُ ‏ ‏الْخِرْبَاقُ ‏ ‏وَكَانَ فِي يَدَيْهِ طُولٌ فَقَالَ يَا رَسُولَ اللَّهِ فَخَرَجَ إِلَيْهِ فَذَكَرَ لَهُ صَنِيعَهُ فَجَاءَ فَقَالَ أَصَدَقَ هَذَا قَالُوا نَعَمْ فَصَلَّى الرَّكْعَةَ الَّتِي تَرَكَ ثُمَّ سَلَّمَ ثُمَّ سَجَدَ سَجْدَتَيْنِ ثُمَّ سَلَّمَ ‏","","",""],[18988,18988,"","আমরা আবেগ নিয়ে কথা বলেছি, আর তারপর দাঙ্গা হয়েছে, কিন্তু আমি বিষের বিষ খুঁজে বের করার চেষ্টা করেছি। অথবা তার কথাবার্তার ব্যাপারে তিনি তার বক্তব্যের ব্যাপারে বলেছেন যে একজন ব্যক্তি হয়তো পাশ করেছে ( ১ রাজাবলি ১৮: ১ - ৩) তাদের মধ্যে কেউ কেউ তাদের হাতকে ভেঙে ফেলতে পারত ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ ثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏قَاتَلَ ‏ ‏يَعْلَى ابْنُ مُنْيَةٍَ ‏ ‏أَوْ ‏ ‏ابْنُ أُمَيَّةَ ‏ ‏رَجُلًا فَعَضَّ أَحَدُهُمَا يَدَ صَاحِبِهِ فَانْتَزَعَ يَدَهُ مِنْ فِيهَ فَانْتَزَعَ ‏ ‏ثَنِيَّتَهُ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏ثَنِيَّتَيْهِ ‏ ‏فَاخْتَصَمَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏يَعَضُّ أَحَدُكُمَا أَخَاهُ كَمَا يَعَضُّ ‏ ‏الْفَحْلُ ‏ ‏لَا ‏ ‏دِيَةَ ‏ ‏لَهُ ‏","","",""],[18989,18989,"","আমরা একটা নিয়মের ব্যবহার নিয়ে অনেক আবেগ নিয়ে কাজ করেছি যা আমি যুদ্ধের কথা শুনেছি। আমার লজ্জাজনক আত্মা ঈশ্বরের হতাশার কথা বলে। এটা অনেকটা শপথের খেলা। এটা এমন এক সময়, যখন আমি একটি নিয়মে পরিণত হয়েছি, আমি একটি নিয়মে পরিণত হয়েছি। এটি ছিল একটি নতুন নিয়মে পরিণত হয়েছে। এটি এমন এক নিয়ম যা আমি যা নিয়ে কথা বলেছি। আমি বলেছিলাম, আমি যা আমার কাছে অনেক বেশি আবেগ এবং আমি মনে করি, আমি মনে করি, আমি মনে করি, আমি মনে করি, এটা এমন এক নিয়ম, যা আমি করতে চাই না। আমি যা করছি, আমি জানি না। আমি যদি আমার মন থেকে কিছু শিখেছি। আমি শুধু চাই, আমি শুধু চাই, আমি যদি আমার মন পরিবর্তন করি, আমি সত্যিই চাই, আমি এটা একটা বিষয় নিয়ে কথা বলি। আমি জানি, এটা আমার মন খারাপ কিছু না। এটা একটা বিষয় যে, এটা একটা বিষয়। কিন্তু আমি যা জানি, এটা একটা ভালো কিছু না। আমি যদি আমি সত্যিই করতে চাই, এটা করতে পারি। আমি শুধু একটা বিষয় যে, আমি চাই, এটা একটা বিষয় নিয়ে আমি শুধু একটা কথা বলি, এটা একটা কথা বলি, কিন্তু আমি যদি আমি শুধু মন, আমি চাই। আমি শুধু জানতে চাই, আমি শুধু একটা কথা বলি, কিন্তু আমি যদি আমি শুধু একটা কথা বলি, কিন্তু আমি জানি, এটা একটা কথা বলি, গভর্নরের একটা গ্যালারি আছে আর এটা বলা যে আমি আপনার সাথে কথা বলছি, সে আমাকে পাঠিয়ে দিয়েছে আর তোমার কাগজপত্র নিয়ে কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا السَّوَّارِ الْعَدَوِىَّ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ الْخُزَاعِيَّ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏الْحَيَاءُ لَا يَأْتِي إِلَّا بِخَيْرٍ ‏ ‏فَقَالَ ‏ ‏بُشَيْرُ بْنُ كَعْبٍ ‏ ‏مَكْتُوبٌ فِي الْحِكْمَةِ أَنَّ مِنْهُ وَقَارًا وَمِنْهُ ‏ ‏سَكِينَةً ‏ ‏فَقَالَ ‏ ‏عِمْرَانُ ‏ ‏أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتُحَدِّثُنِي عَنْ صُحُفِكَ ‏","","",""],[18990,18990,"","আমরা আমাদের অভিজ্ঞতার দ্বারা বাপ্তাইজিত হয়েছি। আমরা বলেছি, আমরা ঈশ্বরের কাছে প্রার্থনা করব এবং আমরা আমাদের অধিকার অনুযায়ী ছেড়ে দেব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْكَيِّ فَاكْتَوَيْنَا فَمَا أَفْلَحْنَا وَلَا أَنْجَحْنَا ‏","","",""],[18991,18991,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি... ...যে মৃত্যু নিয়ে আমি আমার দু:খজনকতার কথা শুনেছি। সে ঈশ্বরের ছাদের সাথে নেই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مِرَايَةَ الْعِجْلِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[18992,18992,"","আমরা খালি খালি হাতে যে হাসিগুলো শুনেছি, সেগুলো নিয়ে আমরা একটা ঢালের শব্দ শুনছিলাম। আমি যখন তাকে ছেড়ে চলে আসি, তখন তাকে মরতে হয় না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا أَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏إِنِّي أُحَدِّثُكَ حَدِيثًا عَسَى اللَّهُ عَزَّ وَجَلَّ أَنْ يَنْفَعَكَ بِهِ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏جَمَعَ بَيْنَ حَجٍّ وَعُمْرَةٍ ثُمَّ لَمْ يَنْهَ عَنْهُ حَتَّى مَاتَ وَلَمْ يَنْزِلْ قُرْآنٌ فِيهِ يُحَرِّمُهُ وَإِنَّهُ كَانَ يُسَلِّمُ عَلَيَّ فَلَمَّا اكْتَوَيْتُ ‏ ‏أَمْسَكَ ‏ ‏عَنِّي فَلَمَّا تَرَكْتُهُ عَادَ إِلَيَّ ‏","","",""],[18993,18993,"","আমরা এক দাঙ্গার শিকার হয়েছি, যা আমাদের বলছে যে আমরা একটা রীতি পেয়েছি যা ব্যর্থতার চেয়ে বেশী কিছু। তিনি ও সেই ব্যক্তি এটি যেন দেবী হতে বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سُئِلَ ‏ ‏أَوْ قِيلَ لَهُ ‏ ‏أَيُعْرَفُ أَهْلُ النَّارِ مِنْ أَهْلِ الْجَنَّةِ فَقَالَ نَعَمْ قَالَ فَلِمَ يَعْمَلُ الْعَامِلُونَ قَالَ ‏ ‏يَعْمَلُ كُلٌّ لِمَا خُلِقَ لَهُ ‏ ‏أَوْ لِمَا يُسِّرَ لَهُ ‏","","",""],[18994,18994,"","আমরা একটা আবেগ দিয়ে চেষ্টা করেছি যে আমরা একসাথে একটা যুদ্ধ করেছি যা আমরা শুনেছি বা আগুনের কথা শুনেছি। আমি জানি, ঈশ্বর যদি তাঁর কাছে প্রার্থনা করেন, তা হলে তিনি তাঁর কাছে সাহায্য করবেন । শত বছর ধরে, আশীর্বাদ, তারা প্রতারণা করে না এবং তারা ভয় পায় না এবং তারা বিষ ফেলে দেয় না। একটি দাঙ্গা শুনলাম বাবা বলল আমি আমার দোকানে এসেছি এবং কথা বলে ( গীতসংহিতা ৩৭: ১১) ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি আপনাকে ও সেইসঙ্গে তিনি যেভাবে চান, সেভাবে চিন্তা করেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا جَمْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَهْدَمَ بْنَ مُضَرِّبٍ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ قَالَ جَاءَنِي ‏ ‏زَهْدَمٌ ‏ ‏فِي دَارِي ‏ ‏فَحَدَّثَنِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ خَيْرَكُمْ ‏ ‏قَرْنِي ‏ ‏ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ ‏ ‏قَالَ ‏ ‏عِمْرَانُ ‏ ‏فَلَا أَدْرِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ‏ ‏قَرْنِهِ ‏ ‏مَرَّتَيْنِ أَوْ ثَلَاثَةً ‏ ‏ثُمَّ يَكُونُ بَعْدَهُمْ قَوْمٌ يَشْهَدُونَ وَلَا يُسْتَشْهَدُونَ وَيَخُونُونَ وَلَا يُؤْتَمَنُونَ ‏ ‏وَيَنْذُرُونَ ‏ ‏وَلَا يُوفُونَ وَيَظْهَرُ فِيهِمْ السِّمَنُ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا جَمْرَةَ ‏ ‏يَقُولُ ‏ ‏جَاءَنِي ‏ ‏زَهْدَمٌ ‏ ‏فِي دَارِي ‏ ‏فَحَدَّثَنِي قَالَ سَمِعْتُ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ خَيْرَكُمْ ‏ ‏قَرْنِي ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ وَيَخُونُونَ وَلَا يُؤْتَمَنُونَ ‏","","",""],[18995,18995,"","হঠাৎ করে তিনি তার চাচার সঙ্গে একটা পদক্ষেপ নিয়েছিলেন বলে বলেছিলেন এবং বলেছিলেন যে, তিনি যখন এসেছিলেন তখন তিনি এসেছিলেন । ভাববাদী তার কাছে প্রার্থনা করে বললেন আমি নিজেকে মেরে ফেলব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏يُحَدِّثُ أَنَّهُ ‏ ‏كَانَتْ لَهُ امْرَأَتَانِ قَالَ فَجَاءَ إِلَى إِحْدَاهُمَا قَالَ فَجَعَلَتْ تَنْزِعُ بِهِ عِمَامَتَهُ وَقَالَتْ جِئْتَ مِنْ عِنْدِ امْرَأَتِكَ ‏ ‏قَالَ ‏ ‏جِئْتُ مِنْ عِنْدِ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏فَحَدَّثَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْسَبُ أَنَّهُ قَالَ ‏ ‏إِنَّ أَقَلَّ سَاكِنِي الْجَنَّةِ النِّسَاءُ ‏","","",""],[18996,18996,"","আমার ছেলের কথা বলছিলাম যে আমার ছেলের জন্য একটা ছেলে শুনলো, দুটো ঘোড়া একটা দাঙ্গার কথা বলছে অথবা বলে যে আমি ঈশ্বরের সাক্ষী। সীলরা যখন আগুন ধরে যায়, তখন তারা তাদের চোখ দিয়ে তাদের দিকে তাকিয়ে থাকে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏بَنِي لَيْثٍ ‏ ‏قَالَ أَشْهَدُ عَلَى ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ ‏ ‏قَالَ ‏ ‏عِمْرَانُ ‏ ‏أَشْهَدُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْحَنَاتِمِ ‏ ‏أَوْ قَالَ ‏ ‏الْحَنْتَمِ ‏ ‏وَخَاتَمِ الذَّهَبِ وَالْحَرِيرِ ‏","","",""],[18997,18997,"","আমরা আমাদের আবেগ নিয়ে কথা বলেছি যা আমাদের ভাইয়ের ছেলের জন্য একটা খেলনা নিয়ে এসেছে, অজ্ঞতার উপেক্ষার এক নৃতাত্ত্বিক রূপ, কিন্তু নবী যে দুই ঘোড়া, তারা আমাদের জন্য এক দুই ঘোড়া নিয়ে এসেছে। তার কাছে প্রার্থনা করো আর সে এমন একজন লোক কে বলেছে যে এই বিখ্যাত জিনিস থেকে তৈরি করা হয়েছে, সে বলেনি যে সে যাবে নাকি সে সন্দেহ করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي مُطَرِّفِ بْنِ الشِّخِّيرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ ‏ ‏هَلْ صُمْتَ مِنْ ‏ ‏سُرَرِ ‏ ‏هَذَا الشَّهْرِ شَيْئًا ‏ ‏يَعْنِي شَعْبَانَ ‏ ‏فَقَالَ لَا قَالَ فَقَالَ لَهُ إِذَا أَفْطَرْتَ رَمَضَانَ فَصُمْ يَوْمًا ‏ ‏أَوْ يَوْمَيْنِ شَكَّ الَّذِي شَكَّ فِيهِ قَالَ وَأَظُنُّهُ قَالَ يَوْمَيْنِ ‏","","",""],[18998,18998,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...আমরা অনেক দুরের একটা কুকুরের ছেলে হয়ে খুশি হয়েছি। তলোয়ার, সে যা দেখেছে, সে সব কিছুর জন্ম দিয়েছে, সে বলেছিল সে প্রার্থনা করছে যেন সে তার মত করে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنِ ‏ ‏صَاحِبٍ لَهُ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ الشِّخِّيرِ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏بِالْكُوفَةِ ‏ ‏فَصَلَّى بِنَا ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏فَجَعَلَ ‏ ‏يُكَبِّرُ كُلَّمَا سَجَدَ وَكُلَّمَا رَفَعَ رَأْسَهُ فَلَمَّا فَرَغَ قَالَ ‏ ‏عِمْرَانُ ‏ ‏صَلَّى بِنَا هَذَا مِثْلَ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[18999,18999,"","আমি তোমাকে হিংসা করার জন্য কথা বলছিলাম, আমি যদি বেঁচে থাকি, তাহলে তোমার কথা শুনতে পাবো। আর যখন আমি এটা করতে শেখালাম, একটা বর্বর যুক্তি, তারপর তিনি এটা মধ্যে পড়ে যাননি একজন লেখক হিসেবে যার কাছে ভবিষ্যদ্বাণী ছিল না। আমরা সবার সেরাটা নিয়ে কথা বলেছি। আমরা আমাদের বলা হয়েছে, আমরা এটা নিয়ে কথা বলেছি। আমরা যখন বলি, তখন আমরা এটা নিয়ে আলোচনা করি, আমরা আমাদের কাছে একটা বাজে যুক্তি ছিল। কিন্তু আমরা এটা একটা সাধারণ ব্যাপার। কিন্তু আমরা যা আমি মনে করি, আমরা যদি আমরা শুধু একটা ধারণা করি, আমরা তা হল, আমরা শুধু একটা সাধারণ ব্যাপার। আমরা যা বলছি, আমরা যদি আমরা শুধু একটা সাধারণ মানুষ বলি, তাহলে আমরা শুধু একটা সাধারণ বিষয় নিয়ে কথা বলি। কিন্তু আমরা যখন আমরা তা করি, আমরা তা হল, আমরা শুধু একটা নতুন ধারণা করি। আমরা যখন আমরা শুধু একটা বিষয় নিয়ে কথা বলি, তখন আমরা যখন আমরা তা বলি, তখন আমরা আমাদের কাছে একটা প্রশ্ন করি, তখন আমরা শুধু একটা প্রশ্ন করি। এবং আমরা যখন আমরা তা করি, তখন আমরা শুধু একটা ধারণা করি। এবং আমরা যখন আমরা তা করি, তখন আমরা তা করি। আমরা যখন আমরা তা করি, তখন আমরা শুধু একটা ধারণা করি। এবং আমরা যখন আমরা তা করি, তখন আমরা যখন আমরা তা করি। এবং আমরা যখন দেখি, তখন আমরা তা করি, তখন আমরা আমাদের কাছে যাই। এবং আমরা যখন আমরা তা করি, তখন আমরা আমাদের কাছে যাই। এবং আমরা যখন একটা স্টিমার যে আমাকে বলেছে দুই ঘোড়া, মৃত্যুর আগ পর্যন্ত তুমি তাদের সাথে কথা বলবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَعَثَ إِلَيَّ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فِي مَرَضِهِ فَأَتَيْتُهُ فَقَالَ لِي إِنِّي كُنْتُ أُحَدِّثُكَ بِأَحَادِيثَ لَعَلَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَنْفَعُكَ بِهَا بَعْدِي وَاعْلَمْ أَنَّهُ كَانَ يُسَلِّمُ عَلَيَّ فَإِنْ عِشْتُ فَاكْتُمْ عَلَيَّ وَإِنْ مِتُّ فَحَدِّثْ إِنْ شِئْتَ وَاعْلَمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏جَمَعَ بَيْنَ حَجَّةٍ وَعُمْرَةٍ ثُمَّ لَمْ يَنْزِلْ فِيهَا كِتَابٌ وَلَمْ يَنْهَ عَنْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏فِيهَا بِرَأْيِهِ مَا شَاءَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فَذَكَرَ مِثْلَهُ وَقَالَ لَا تُحَدِّثْ بِهِمَا حَتَّى أَمُوتَ ‏","","",""],[19000,19000,"","আমরা আবেগ নিয়ে কথা বলেছি এবং পাইলটের ছেলে বলে আমরা সুখী হব এবং আমরা সুখী হব। আমি দুঃখিত, আমি দুঃখিত, সে বাইরে গিয়েছিল এবং সে ঈশ্বরের কাছে গিয়েছিল। তারপর সে তার জন্য ঈশ্বরের কাছে গিয়েছিল। এবং সে ছিল আমার জন্য এক আদর্শ বার্তা। আমি তাকে বলেছিলাম, আমি সুখী হবার জন্য, আমি তাকে ধন্যবাদ বলে দিলাম, আমি সুখী ছিলাম, আমি সুখী। আমি তাকে বলেছিলাম, আমি খুব খুশি হব। আমি তাকে বলেছিলাম, আমি যদি আমার মনে হয়, আমি তোমার সাথে থাকবে। আমি তোমার সাথে থাকবে। আমি তোমার সাথে আমার জীবনের জন্য অনেক কষ্ট হবে। কিন্তু আমি তাকে সাহায্য করব। আর আমি তোমার সাথে থাকব। আমি তোমার সাথে আমার সাথে আমার সম্পর্ক গড়ে তুলতে চাই। আমি তোমার সাথে থাকবে। আমি এখন তোমার জন্য এটা একটা বিষয় নিয়ে কথা বলব। আর আমি তোমার সাথে কথা বলব। আমি তোমার সাথে আমার মনে রাখতে চাই না। আমি এখন তোমার জন্য এটা একটা ভালো হবে। না, কাদাটা কিভাবে করে?","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا ثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا عَضَّ رَجُلًا عَلَى ذِرَاعِهِ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏فَنَزَعَ يَدَهُ مِنْهُ فَسَقَطَتْ ثَنِيَّتَاهُ فَجَذَبَهَا فَانْتَزَعَتْ ثَنِيَّتَهُ فَرُفِعَ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَبْطَلَهَا وَقَالَ أَرَدْتَ أَنْ تَقْضَمَ لَحْمَ أَخِيكَ كَمَا يَقْضَمُ ‏ ‏الْفَحْلُ ‏","","",""]];
